INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '727285f1-736e-53df-9df5-91d16602f811', id, 'wudu-step-by-step', '{"bn": "ওযু করার নিয়ম: ধাপে ধাপে", "en": "How to Perform Wudu: Step by Step"}', '{"bn": "নামাজের আগে ওযু ফরজ। রাসুলুল্লাহ ﷺ যেভাবে ওযু করতেন, সেভাবে শুরু থেকে শেষ পর্যন্ত — দোয়াসহ।", "en": "Wudu is required before salah. Here is wudu as the Prophet ﷺ performed it, from start to finish, with the duas."}', 'basic', '[{"type": "text", "text": {"bn": "ওযু ছাড়া নামাজ হয় না। আল্লাহ তাআলা কুরআনে ওযুর মূল অঙ্গগুলো নিজেই বলে দিয়েছেন। রাসুলুল্লাহ ﷺ বলেছেন, যার ওযু ভেঙে গেছে, সে ওযু না করা পর্যন্ত আল্লাহ তার নামাজ কবুল করেন না।", "en": "Salah is not valid without wudu. Allah Himself names the main parts of wudu in the Quran, and the Prophet ﷺ said that Allah does not accept the prayer of someone whose wudu has broken until he performs wudu."}}, {"type": "arabic", "label": {"bn": "ওযুর আয়াত", "en": "The ayah of wudu"}, "ar": "يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ", "pron": {"bn": "ইয়া আইয়্যুহাল্লাযিনা আমানু ইযা কুমতুম ইলাস সালাতি ফাগসিলু উজুহাকুম ওয়া আইদিয়াকুম ইলাল মারাফিকি ওয়ামসাহু বিরুউসিকুম ওয়া আরজুলাকুম ইলাল কা''বাইন।", "en": "Ya ayyuhal-ladhina amanu idha qumtum ilas-salati faghsilu wujuhakum wa aydiyakum ilal-marafiqi wamsahu bi-ru''usikum wa arjulakum ilal-ka''bayn."}, "meaning": {"bn": "হে ঈমানদারগণ! যখন তোমরা নামাজের জন্য দাঁড়াতে চাও, তখন তোমাদের মুখমণ্ডল ও কনুই পর্যন্ত হাত ধুয়ে নাও, মাথা মাসেহ করো এবং টাখনু পর্যন্ত পা ধুয়ে নাও।", "en": "O you who believe, when you rise for prayer, wash your faces and your arms up to the elbows, wipe your heads, and wash your feet up to the ankles."}, "ref": {"bn": "সূরা মায়েদা ৫:৬ (আংশিক)", "en": "Al-Ma''idah 5:6 (part)"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৩৫; সহিহ মুসলিম ২২৫ — ওযু ছাড়া নামাজ কবুল হয় না", "en": "Sahih al-Bukhari 135; Sahih Muslim 225: prayer is not accepted without wudu"}}, {"type": "heading", "text": {"bn": "ওযুর ধাপগুলো", "en": "The steps of wudu"}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention (niyyah)"}, "text": {"bn": "মনে মনে ঠিক করুন যে আপনি আল্লাহর জন্য পবিত্রতা অর্জন করছেন। নিয়ত অন্তরের কাজ; মুখে বলা জরুরি নয়।", "en": "Intend in your heart that you are purifying yourself for Allah. Niyyah is in the heart; saying it aloud is not required."}}, {"type": "step", "title": {"bn": "বিসমিল্লাহ বলা", "en": "Say Bismillah"}, "text": {"bn": "ওযুর শুরুতে \"বিসমিল্লাহ\" বলুন। অধিকাংশ আলেমের মতে এটি সুন্নত; হাম্বলি মাযহাবের একটি মতে ওয়াজিব।", "en": "Say \"Bismillah\" at the start. Most scholars hold it is sunnah; one Hanbali view holds it obligatory."}}, {"type": "arabic", "label": {"bn": "ওযুর শুরুতে", "en": "At the start of wudu"}, "ar": "بِسْمِ اللَّهِ", "pron": {"bn": "বিসমিল্লাহ", "en": "Bismillah"}, "meaning": {"bn": "আল্লাহর নামে (শুরু করছি)।", "en": "In the name of Allah."}, "ref": {"bn": "সুনান আবু দাউদ ১০১", "en": "Sunan Abi Dawud 101"}}, {"type": "step", "title": {"bn": "দুই হাত কবজি পর্যন্ত ধোয়া", "en": "Wash both hands to the wrists"}, "text": {"bn": "প্রথমে ডান হাত, তারপর বাম হাত কবজি পর্যন্ত তিনবার ধুয়ে নিন। আঙুলের ফাঁকে পানি পৌঁছান।", "en": "Wash the hands up to the wrists three times, right first, letting water reach between the fingers."}}, {"type": "step", "title": {"bn": "মিসওয়াক করা", "en": "Use a miswak"}, "text": {"bn": "সম্ভব হলে মিসওয়াক বা ব্রাশ দিয়ে দাঁত পরিষ্কার করুন; না থাকলে আঙুল দিয়ে ঘষে নিন। এটি গুরুত্বপূর্ণ সুন্নত।", "en": "If possible, clean the teeth with a miswak (or brush); otherwise rub with a finger. It is an emphasised sunnah."}}, {"type": "step", "title": {"bn": "কুলি করা", "en": "Rinse the mouth"}, "text": {"bn": "ডান হাতে পানি নিয়ে তিনবার কুলি করুন। রোজা না থাকলে গড়গড়া করুন।", "en": "Take water with the right hand and rinse the mouth three times; gargle if you are not fasting."}}, {"type": "step", "title": {"bn": "নাকে পানি দেওয়া", "en": "Rinse the nose"}, "text": {"bn": "ডান হাতে নাকে পানি দিন এবং বাম হাতে নাক ঝেড়ে পরিষ্কার করুন — তিনবার। রোজা থাকলে বেশি ভেতরে টানবেন না।", "en": "Draw water into the nose with the right hand and blow it out with the left, three times. Do not sniff deeply when fasting."}}, {"type": "step", "title": {"bn": "মুখমণ্ডল ধোয়া (ফরজ)", "en": "Wash the face (fard)"}, "text": {"bn": "কপালের চুলের গোড়া থেকে থুতনির নিচ পর্যন্ত এবং এক কানের লতি থেকে অন্য কানের লতি পর্যন্ত পুরো মুখ তিনবার ধুয়ে নিন। ঘন দাড়ি থাকলে আঙুল দিয়ে খিলাল করুন।", "en": "Wash the whole face three times: from the hairline to below the chin and from ear to ear. Run wet fingers through a thick beard."}}, {"type": "step", "title": {"bn": "দুই হাত কনুইসহ ধোয়া (ফরজ)", "en": "Wash the arms including the elbows (fard)"}, "text": {"bn": "প্রথমে ডান হাত আঙুলের মাথা থেকে কনুইসহ তিনবার, তারপর বাম হাত একইভাবে তিনবার ধুয়ে নিন। আংটি বা চুড়ি থাকলে নাড়িয়ে নিচে পানি পৌঁছান।", "en": "Wash the right arm from the fingertips up to and including the elbow three times, then the left. Move any ring or bangle so water reaches beneath."}}, {"type": "step", "title": {"bn": "মাথা মাসেহ করা (ফরজ)", "en": "Wipe the head (fard)"}, "text": {"bn": "দুই হাত ভিজিয়ে কপালের দিক থেকে মাথার পেছন পর্যন্ত নিয়ে যান, তারপর আবার সামনে ফিরিয়ে আনুন — একবার। পুরো মাথা মাসেহ করা সুন্নত।", "en": "Wet both hands and pass them from the front of the head to the back and return them to the front, once. Wiping the whole head is sunnah."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৮৫ — মাথা মাসেহের পদ্ধতি", "en": "Sahih al-Bukhari 185: how the head is wiped"}}, {"type": "step", "title": {"bn": "কান মাসেহ করা", "en": "Wipe the ears"}, "text": {"bn": "একই ভেজা হাতে শাহাদাত আঙুল দিয়ে কানের ভেতরের অংশ এবং বুড়ো আঙুল দিয়ে কানের পেছনের অংশ মাসেহ করুন।", "en": "With the same wet hands, wipe the inside of the ears with the index fingers and the back of the ears with the thumbs."}}, {"type": "note", "tone": "info", "text": {"bn": "ঘাড় মাসেহ নিয়ে যেসব বর্ণনা আছে সেগুলো দুর্বল। কিছু হানাফি ফকিহ একে মুস্তাহাব বলেছেন, আবার অনেক আলেম বলেন এটি সুন্নত হিসেবে প্রমাণিত নয়। এটি না করলে ওযুর কোনো ক্ষতি হয় না।", "en": "Reports about wiping the neck are weak. Some Hanafi jurists called it recommended, while many scholars say it is not established as sunnah. Leaving it does not affect wudu."}, "check": true}, {"type": "step", "title": {"bn": "দুই পা টাখনুসহ ধোয়া (ফরজ)", "en": "Wash the feet including the ankles (fard)"}, "text": {"bn": "প্রথমে ডান পা টাখনুসহ তিনবার, তারপর বাম পা তিনবার ধুয়ে নিন। বাম হাতের কনিষ্ঠা আঙুল দিয়ে পায়ের আঙুলের ফাঁকে খিলাল করুন। গোড়ালি যেন শুকনো না থাকে।", "en": "Wash the right foot including the ankle three times, then the left. Pass the little finger between the toes. Make sure the heels are not left dry."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৬৫; সহিহ মুসলিম ২৪১ — শুকনো গোড়ালির জন্য সতর্কবাণী", "en": "Sahih al-Bukhari 165; Sahih Muslim 241: the warning about dry heels"}}, {"type": "step", "title": {"bn": "ওযুর পরের দোয়া পড়া", "en": "Recite the dua after wudu"}, "text": {"bn": "ওযু শেষ করে নিচের দোয়াটি পড়ুন। রাসুলুল্লাহ ﷺ বলেছেন, যে ভালোভাবে ওযু করে এই সাক্ষ্য দেয়, তার জন্য জান্নাতের আটটি দরজা খুলে দেওয়া হয়।", "en": "After finishing, recite the dua below. The Prophet ﷺ said that whoever performs wudu well and then says this testimony, the eight gates of Paradise are opened for him."}}, {"type": "arabic", "label": {"bn": "ওযুর পরের দোয়া", "en": "Dua after wudu"}, "ar": "أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "pron": {"bn": "আশহাদু আল লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ।", "en": "Ashhadu an la ilaha illallahu wahdahu la sharika lah, wa ashhadu anna Muhammadan ''abduhu wa rasuluh."}, "meaning": {"bn": "আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; এবং আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসুল।", "en": "I bear witness that there is no god but Allah alone, with no partner, and I bear witness that Muhammad is His servant and Messenger."}, "ref": {"bn": "সহিহ মুসলিম ২৩৪", "en": "Sahih Muslim 234"}}, {"type": "arabic", "label": {"bn": "সাথে যোগ করা যায়", "en": "Can be added"}, "ar": "اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ، وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ", "pron": {"bn": "আল্লাহুম্মাজ আলনি মিনাত তাওয়াবিনা, ওয়াজ আলনি মিনাল মুতাতাহহিরিন।", "en": "Allahummaj''alni minat-tawwabina waj''alni minal-mutatahhirin."}, "meaning": {"bn": "হে আল্লাহ! আমাকে তওবাকারীদের অন্তর্ভুক্ত করুন এবং পবিত্রতা অর্জনকারীদের অন্তর্ভুক্ত করুন।", "en": "O Allah, make me among those who repent often and among those who purify themselves."}, "ref": {"bn": "সুনান তিরমিযি ৫৫", "en": "Jami'' at-Tirmidhi 55"}}, {"type": "step", "title": {"bn": "দুই রাকাত তাহিয়্যাতুল ওযু (ঐচ্ছিক)", "en": "Two rakats after wudu (optional)"}, "text": {"bn": "ওযুর পর মনোযোগ দিয়ে দুই রাকাত নফল নামাজ পড়া ফজিলতপূর্ণ, যদি তা নিষিদ্ধ সময় না হয় (বিস্তারিত \"বিশেষ নামাজ\" বিভাগে)।", "en": "Praying two voluntary rakats with focus after wudu is virtuous, if it is not a forbidden time (details in the Special Prayers section)."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫৯; সহিহ মুসলিম ২২৬ — উসমান (রা.) বর্ণিত রাসুলুল্লাহ ﷺ-এর ওযু", "en": "Sahih al-Bukhari 159; Sahih Muslim 226: the Prophet''s wudu as narrated by Uthman (RA)"}}, {"type": "note", "tone": "warn", "text": {"bn": "প্রত্যেক অঙ্গ ধোয়ার সময় আলাদা আলাদা দোয়া (যেমন মুখ ধোয়ার দোয়া, হাত ধোয়ার দোয়া) প্রচলিত আছে, কিন্তু এগুলো রাসুলুল্লাহ ﷺ থেকে নির্ভরযোগ্য সূত্রে প্রমাণিত নয়। শুরুতে বিসমিল্লাহ আর শেষে উপরের দোয়াই যথেষ্ট।", "en": "Separate duas for washing each limb are widespread, but they are not reliably established from the Prophet ﷺ. Bismillah at the start and the dua above at the end are enough."}}, {"type": "note", "tone": "tip", "text": {"bn": "পানি অপচয় করবেন না, প্রতিটি অঙ্গ তিনবারের বেশি ধোবেন না, আর অঙ্গগুলো পরপর ধোবেন — যেন আগের অঙ্গ শুকিয়ে না যায়।", "en": "Do not waste water, do not wash any part more than three times, and wash the parts one after another without long gaps."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '4f20252d-a99f-5dd3-8340-9ac6f6a17e1c', id, 'wudu-fard-sunnah', '{"bn": "ওযুর ফরজ, সুন্নত ও মাকরুহ", "en": "Wudu: Fard, Sunnah and Makruh"}', '{"bn": "ওযুর কোন কাজ বাদ পড়লে ওযু হয় না, কোনগুলো সুন্নত, আর কোনগুলো করা অপছন্দনীয় — মাযহাবগুলোর মতপার্থক্যসহ।", "en": "Which acts of wudu are essential, which are sunnah, and which are disliked, with the differences between the madhhabs."}', 'detail', '[{"type": "heading", "text": {"bn": "ওযুর ফরজ (হানাফি মাযহাব অনুযায়ী ৪টি)", "en": "Fard of wudu (four, in the Hanafi madhhab)"}}, {"type": "list", "items": [{"bn": "পুরো মুখমণ্ডল একবার ধোয়া", "en": "Washing the whole face once"}, {"bn": "দুই হাত কনুইসহ একবার ধোয়া", "en": "Washing both arms including the elbows once"}, {"bn": "মাথার এক-চতুর্থাংশ মাসেহ করা", "en": "Wiping a quarter of the head"}, {"bn": "দুই পা টাখনুসহ একবার ধোয়া", "en": "Washing both feet including the ankles once"}]}, {"type": "text", "text": {"bn": "এর যেকোনো একটি বাদ পড়লে, বা কোনো অংশ চুল পরিমাণ শুকনো থাকলে ওযু হবে না। এই চারটি সরাসরি সূরা মায়েদার ৬ নম্বর আয়াতে আছে।", "en": "If any of these is missed, or even a hair''s breadth of the area stays dry, wudu is not valid. All four are named directly in Al-Ma''idah 5:6."}}, {"type": "differ", "title": {"bn": "ওযুর ফরজ কয়টি? — মাযহাবগুলোর মত", "en": "How many fard acts does wudu have?"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "ফরজ ৪টি — আয়াতে উল্লিখিত চার অঙ্গ। নিয়ত, ধারাবাহিকতা (তারতিব) ও পরপর করা (মুওয়ালাত) সুন্নত। মাথার এক-চতুর্থাংশ মাসেহ ফরজ।", "en": "Four: the four parts named in the ayah. Intention, order and continuity are sunnah. Wiping a quarter of the head is the obligatory amount."}, "evidence": {"bn": "সূরা মায়েদা ৫:৬ শুধু এই চারটির আদেশ দেয়। রাসুলুল্লাহ ﷺ মাথার সামনের অংশ (নাসিয়া) মাসেহ করেছেন — সহিহ মুসলিম ২৭৪।", "en": "Al-Ma''idah 5:6 commands only these four. The Prophet ﷺ wiped the front part of his head (Sahih Muslim 274)."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "ফরজ ৬টি — নিয়ত, মুখ, হাত, মাথার সামান্য অংশ মাসেহ, পা এবং ধারাবাহিকতা (তারতিব)।", "en": "Six: intention, face, arms, wiping any part of the head, feet, and doing them in order."}, "evidence": {"bn": "\"সকল কাজ নিয়তের উপর নির্ভরশীল\" — সহিহ বুখারি ১; আয়াতে অঙ্গগুলোর ক্রম এবং রাসুলুল্লাহ ﷺ সবসময় এই ক্রমেই ওযু করেছেন।", "en": "\"Actions are by intentions\" (Sahih al-Bukhari 1); the order in the ayah, and the Prophet ﷺ always kept that order."}}, {"label": {"bn": "মালেকি", "en": "Maliki"}, "text": {"bn": "ফরজ ৭টি — নিয়ত, চার অঙ্গ (পুরো মাথা মাসেহ), অঙ্গ ঘষা (দালক) এবং পরপর করা (মুওয়ালাত)।", "en": "Seven: intention, the four parts (wiping the whole head), rubbing the limbs, and continuity."}, "evidence": {"bn": "আয়াতের \"বিরুউসিকুম\" দ্বারা পুরো মাথা বোঝায়; রাসুলুল্লাহ ﷺ-এর ওযুতে পুরো মাথা মাসেহ — সহিহ বুখারি ১৮৫।", "en": "They read \"your heads\" in the ayah as the whole head; the Prophet ﷺ wiped his whole head (Sahih al-Bukhari 185)."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "ফরজ ৬টি — চার অঙ্গ (কুলি ও নাকে পানি মুখ ধোয়ার অংশ, পুরো মাথা ও কান মাসেহ), তারতিব ও মুওয়ালাত; নিয়ত শর্ত।", "en": "Six: the four parts (rinsing mouth and nose count as part of the face; the whole head with the ears), order and continuity; intention is a condition."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ কখনো কুলি ও নাকে পানি দেওয়া ছাড়েননি বলে বর্ণিত; আয়াতের ক্রম ও সুন্নাহর ধারাবাহিক আমল।", "en": "The Prophet ﷺ is not reported to have ever left rinsing the mouth and nose; the order in the ayah and his consistent practice."}}]}, {"type": "heading", "text": {"bn": "ওযুর সুন্নতসমূহ", "en": "Sunnah acts of wudu"}}, {"type": "list", "items": [{"bn": "নিয়ত করা (হানাফি মতে সুন্নত)", "en": "Making the intention (sunnah in the Hanafi view)"}, {"bn": "বিসমিল্লাহ বলে শুরু করা", "en": "Starting with Bismillah"}, {"bn": "দুই হাত কবজি পর্যন্ত তিনবার ধোয়া", "en": "Washing the hands to the wrists three times"}, {"bn": "মিসওয়াক করা", "en": "Using a miswak"}, {"bn": "তিনবার কুলি করা ও তিনবার নাকে পানি দেওয়া", "en": "Rinsing the mouth and nose three times each"}, {"bn": "প্রতিটি অঙ্গ তিনবার করে ধোয়া", "en": "Washing each part three times"}, {"bn": "ঘন দাড়ি এবং হাত-পায়ের আঙুল খিলাল করা", "en": "Running fingers through a thick beard and between fingers and toes"}, {"bn": "পুরো মাথা একবার মাসেহ করা এবং কান মাসেহ করা", "en": "Wiping the whole head once and wiping the ears"}, {"bn": "ডান দিক থেকে শুরু করা", "en": "Starting with the right side"}, {"bn": "কুরআনের ক্রম অনুযায়ী ধারাবাহিকভাবে ধোয়া", "en": "Following the order given in the Quran"}, {"bn": "এক অঙ্গ শুকানোর আগেই পরের অঙ্গ ধোয়া", "en": "Washing each part before the previous one dries"}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫৯ (উসমান রা.) ও ১৮৫ (আবদুল্লাহ ইবনে যায়েদ রা.) — রাসুলুল্লাহ ﷺ-এর ওযুর বিবরণ", "en": "Sahih al-Bukhari 159 (Uthman RA) and 185 (Abdullah ibn Zayd RA): descriptions of the Prophet''s wudu"}}, {"type": "heading", "text": {"bn": "ওযুতে যা মাকরুহ (অপছন্দনীয়)", "en": "What is disliked (makruh) in wudu"}}, {"type": "list", "items": [{"bn": "প্রয়োজনের চেয়ে বেশি পানি খরচ করা, এমনকি নদীর পাশে থাকলেও", "en": "Using more water than needed, even beside a river"}, {"bn": "কোনো অঙ্গ তিনবারের বেশি ধোয়া", "en": "Washing any part more than three times"}, {"bn": "মুখে জোরে পানি ছিটিয়ে মারা", "en": "Splashing water forcefully on the face"}, {"bn": "ওযুর মধ্যে অপ্রয়োজনীয় দুনিয়াবি কথা বলা", "en": "Unnecessary worldly talk during wudu"}, {"bn": "কোনো সুন্নত ইচ্ছাকৃতভাবে ছেড়ে দেওয়া", "en": "Deliberately leaving out a sunnah"}]}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'bb8d73eb-b5c9-5b9d-9675-5ef6f346d56f', id, 'wudu-breakers', '{"bn": "যেসব কারণে ওযু ভেঙে যায়", "en": "What Breaks Wudu"}', '{"bn": "যেসব কারণে ওযু ভাঙে তাতে সব আলেম একমত, আর কিছু বিষয়ে মতপার্থক্য আছে — দুটোই এখানে।", "en": "Some things break wudu by agreement of all scholars; on others they differ. Both are covered here."}', 'basic', '[{"type": "heading", "text": {"bn": "যেসব কারণে ওযু ভাঙে — সবাই একমত", "en": "What breaks wudu: agreed by all"}}, {"type": "list", "items": [{"bn": "পেশাব-পায়খানার রাস্তা দিয়ে কিছু বের হওয়া: পেশাব, পায়খানা, বায়ু, মজি (কামরস), ওদি ইত্যাদি", "en": "Anything leaving the front or back passage: urine, stool, wind, pre-seminal fluid (madhy), wadi and the like"}, {"bn": "গভীর ঘুম — বিশেষ করে শুয়ে বা হেলান দিয়ে এমনভাবে ঘুমানো যাতে শরীর ঢিলে হয়ে যায়", "en": "Deep sleep, especially lying down or leaning so the body relaxes"}, {"bn": "জ্ঞান হারানো: বেহুঁশ হওয়া, পাগলামি, নেশাগ্রস্ত হওয়া", "en": "Losing consciousness: fainting, insanity, intoxication"}, {"bn": "যেসব কারণে গোসল ফরজ হয় (সহবাস, বীর্যপাত, হায়েজ-নিফাস শেষ হওয়া) — সেগুলো ওযুও ভেঙে দেয়", "en": "Whatever makes ghusl obligatory (intercourse, ejaculation, end of menses or post-natal bleeding) also breaks wudu"}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৩৫ — \"হাদাস\" অর্থ বায়ু বের হওয়া ইত্যাদি", "en": "Sahih al-Bukhari 135: \"hadath\" explained as passing wind and the like"}}, {"type": "heading", "text": {"bn": "মতপার্থক্যপূর্ণ বিষয়", "en": "Points where scholars differ"}}, {"type": "differ", "title": {"bn": "রক্ত, পুঁজ বা বমি বের হলে কি ওযু ভাঙে?", "en": "Does flowing blood, pus or vomit break wudu?"}, "views": [{"label": {"bn": "হানাফি (এবং হাম্বলি — বেশি পরিমাণে হলে)", "en": "Hanafi (and Hanbali, if the amount is large)"}, "text": {"bn": "শরীরের কোথাও থেকে রক্ত বা পুঁজ বের হয়ে গড়িয়ে পড়লে, অথবা মুখ ভরে বমি হলে ওযু ভেঙে যায়। সামান্য রক্ত যা জায়গা থেকে গড়ায় না, তাতে ভাঙে না।", "en": "Blood or pus that flows from any part of the body, or a mouthful of vomit, breaks wudu. A little blood that does not flow does not."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ বমি করার পর ওযু করেছেন বলে বর্ণিত (সুনান তিরমিযি); কিছু সাহাবির আমল।", "en": "It is reported that the Prophet ﷺ vomited and then made wudu (Jami at-Tirmidhi); practice of some Companions."}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "পেশাব-পায়খানার রাস্তা ছাড়া অন্য কোথাও থেকে রক্ত, পুঁজ বা বমি বের হলে ওযু ভাঙে না।", "en": "Blood, pus or vomit from anywhere other than the two passages does not break wudu."}, "evidence": {"bn": "এক আনসারি সাহাবি তির বিদ্ধ হয়ে রক্তাক্ত অবস্থায় নামাজ চালিয়ে গেছেন (সুনান আবু দাউদ); ওযু ভাঙার স্পষ্ট দলিল নেই বলে মূল অবস্থা বহাল।", "en": "A Companion kept praying while bleeding from arrow wounds (Sunan Abi Dawud); with no clear proof, the default (wudu remains) stands."}}], "check": true}, {"type": "differ", "title": {"bn": "লজ্জাস্থান বা বিপরীত লিঙ্গের শরীর স্পর্শ করলে", "en": "Touching the private part, or touching the opposite sex"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "নিজের লজ্জাস্থান স্পর্শ করলে বা স্ত্রী/নারীকে স্পর্শ করলে ওযু ভাঙে না (যদি কিছু বের না হয়)।", "en": "Touching one''s private part, or touching a woman, does not break wudu (if nothing is discharged)."}, "evidence": {"bn": "\"এটা তো তোমার শরীরেরই একটা অংশ\" — সুনান আবু দাউদ ১৮২ (তালক রা.); রাসুলুল্লাহ ﷺ নামাজে আয়েশা (রা.)-এর পা স্পর্শ করতেন — সহিহ বুখারি ৩৮২। সূরা নিসা ৪:৪৩-এর \"লামাসতুম\" দ্বারা ইবনে আব্বাস (রা.) সহবাস বুঝিয়েছেন।", "en": "\"It is only a part of you\" (Sunan Abi Dawud 182, Talq RA); the Prophet ﷺ touched Aisha''s feet while praying (Sahih al-Bukhari 382). Ibn Abbas understood \"lamastum\" in An-Nisa 4:43 as intercourse."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি (মালেকি — শর্তসাপেক্ষে)", "en": "Shafi''i and Hanbali (Maliki with conditions)"}, "text": {"bn": "হাতের তালু দিয়ে সরাসরি লজ্জাস্থান স্পর্শ করলে ওযু ভাঙে। শাফেয়ি মতে গায়রে মাহরাম নারী-পুরুষের ত্বক স্পর্শে ওযু ভাঙে; মালেকি ও হাম্বলি মতে কামভাবসহ স্পর্শ করলে ভাঙে।", "en": "Touching the private part directly with the hand breaks wudu. For Shafi''is, skin contact between a non-mahram man and woman breaks it; for Malikis and Hanbalis, only touch with desire."}, "evidence": {"bn": "\"যে নিজের লজ্জাস্থান স্পর্শ করে, সে যেন ওযু করে\" — সুনান আবু দাউদ ১৮১ (বুসরা রা.); সূরা নিসা ৪:৪৩ \"অথবা তোমরা নারীদের স্পর্শ করো\" আয়াতের বাহ্যিক অর্থ।", "en": "\"Whoever touches his private part, let him make wudu\" (Sunan Abi Dawud 181, Busrah RA); the apparent meaning of \"or you have touched women\" in An-Nisa 4:43."}}]}, {"type": "list", "items": [{"bn": "উটের গোশত খাওয়া: হাম্বলি মতে ওযু ভাঙে (সহিহ মুসলিম ৩৬০), অধিকাংশ আলেমের মতে ভাঙে না।", "en": "Eating camel meat: breaks wudu in the Hanbali view (Sahih Muslim 360); most scholars say it does not."}, {"bn": "নামাজের মধ্যে অট্টহাসি: হানাফি মতে নামাজ ও ওযু দুটোই ভাঙে; অন্যদের মতে শুধু নামাজ ভাঙে।", "en": "Laughing out loud in salah: in the Hanafi view it breaks both salah and wudu; others say only the salah."}]}, {"type": "heading", "text": {"bn": "যেসব কারণে ওযু ভাঙে না", "en": "What does not break wudu"}}, {"type": "list", "items": [{"bn": "ওযু ভেঙেছে কি না — শুধু সন্দেহ হলে। নিশ্চিত না হওয়া পর্যন্ত ওযু আছে ধরে নিতে হবে।", "en": "Mere doubt about whether wudu broke. Wudu remains until you are certain."}, {"bn": "বসে বসে হালকা ঝিমুনি বা তন্দ্রা, যাতে শরীর ঢিলে হয় না", "en": "Light dozing while sitting firmly"}, {"bn": "নখ বা চুল কাটা", "en": "Cutting nails or hair"}, {"bn": "নিজের বা অন্যের সতর দেখে ফেলা", "en": "Seeing someone''s awrah, or one''s own"}, {"bn": "সামান্য রক্ত যা গড়িয়ে পড়ে না", "en": "A little blood that does not flow"}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৩৭; সহিহ মুসলিম ৩৬২ — \"শব্দ না শোনা বা গন্ধ না পাওয়া পর্যন্ত নামাজ ছাড়বে না\"", "en": "Sahih al-Bukhari 137; Sahih Muslim 362: \"Do not leave (the prayer) until you hear a sound or smell something\""}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৭৬ — সাহাবিরা বসে ঝিমিয়ে নতুন ওযু ছাড়াই নামাজ পড়তেন", "en": "Sahih Muslim 376: Companions dozed while sitting and prayed without renewing wudu"}}, {"type": "note", "tone": "tip", "text": {"bn": "যার সবসময় ফোঁটা ফোঁটা পেশাব, বায়ু বা রক্ত বের হতে থাকে (মাজুর), সে প্রতি ওয়াক্তে নতুন ওযু করে সেই ওয়াক্তের সব নামাজ পড়বে।", "en": "Someone with a constant flow of urine drops, wind or blood (ma''dhur) makes a fresh wudu for each prayer time and prays all that time''s prayers with it."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'af947358-5662-518e-9834-4c4a1a5fc76d', id, 'ghusl-fard', '{"bn": "ফরজ গোসল: কখন ও কীভাবে", "en": "Fard Ghusl: When and How"}', '{"bn": "কোন অবস্থায় গোসল ফরজ হয় এবং সুন্নত পদ্ধতিতে কীভাবে গোসল করতে হয় — ধাপে ধাপে।", "en": "When ghusl becomes obligatory and how to do it the sunnah way, step by step."}', 'basic', '[{"type": "text", "text": {"bn": "বড় নাপাকি (জানাবাত, হায়েজ বা নিফাস) থেকে পবিত্র হওয়ার জন্য পুরো শরীর ধোয়াকে গোসল বলে। গোসল ফরজ থাকা অবস্থায় নামাজ, কাবার তাওয়াফ, কুরআন শরিফ স্পর্শ করা এবং (অধিকাংশ আলেমের মতে) কুরআন তিলাওয়াত করা যায় না।", "en": "Ghusl is washing the whole body to remove major impurity (janabah, menses or post-natal bleeding). Until ghusl is done one may not pray, do tawaf, touch the Mushaf, or (in the view of most scholars) recite the Quran."}}, {"type": "ref", "text": {"bn": "সূরা মায়েদা ৫:৬ — \"আর যদি তোমরা জুনুবি (অপবিত্র) হও, তবে ভালোভাবে পবিত্র হও\"", "en": "Al-Ma''idah 5:6: \"And if you are in a state of janabah, then purify yourselves\""}}, {"type": "heading", "text": {"bn": "যেসব কারণে গোসল ফরজ হয়", "en": "When ghusl becomes obligatory"}}, {"type": "list", "items": [{"bn": "স্বামী-স্ত্রীর সহবাস — বীর্যপাত না হলেও", "en": "Sexual intercourse, even without ejaculation"}, {"bn": "জাগ্রত অবস্থায় উত্তেজনার সাথে বীর্যপাত", "en": "Ejaculation with desire while awake"}, {"bn": "স্বপ্নদোষ — ঘুম থেকে উঠে ভেজা চিহ্ন দেখলে", "en": "A wet dream, if one wakes and finds wetness"}, {"bn": "হায়েজ (মাসিক) শেষ হলে", "en": "When menstruation ends"}, {"bn": "নিফাস (সন্তান প্রসবের পরের রক্তস্রাব) শেষ হলে", "en": "When post-natal bleeding ends"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৪৮ — সহবাসে গোসল ফরজ, বীর্যপাত না হলেও; সহিহ বুখারি ২৮২ — স্বপ্নে ভেজা দেখলে গোসল", "en": "Sahih Muslim 348: ghusl after intercourse even without ejaculation; Sahih al-Bukhari 282: ghusl when wetness is seen after a dream"}}, {"type": "differ", "title": {"bn": "গোসলের ফরজ কী কী?", "en": "What is obligatory in ghusl?"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "ফরজ ৩টি — ভালোভাবে কুলি করা (গড়গড়াসহ, রোজা না থাকলে), নাকের নরম অংশ পর্যন্ত পানি পৌঁছানো, এবং পুরো শরীর এমনভাবে ধোয়া যাতে একটি চুল পরিমাণ জায়গাও শুকনো না থাকে।", "en": "Three: rinsing the whole mouth, rinsing the nose up to the soft bone, and washing the entire body so that not a hair''s breadth stays dry."}, "evidence": {"bn": "সূরা মায়েদা ৫:৬-এর \"ফাত্তাহহারু\" (ভালোভাবে পবিত্র হও) শব্দ পুরো শরীর, এমনকি মুখ ও নাকের ভেতরের যতটুকু ধোয়া সম্ভব তা-ও অন্তর্ভুক্ত করে।", "en": "The intensive word \"fattahharu\" (purify yourselves thoroughly) in Al-Ma''idah 5:6 includes all of the body, including the inside of mouth and nose as far as can be washed."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "নিয়তসহ পুরো শরীর ধোয়া ফরজ; কুলি ও নাকে পানি দেওয়াও ওয়াজিব।", "en": "Washing the whole body with intention; rinsing the mouth and nose is also obligatory."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ গোসলে সবসময় কুলি ও নাকে পানি দিয়েছেন।", "en": "The Prophet ﷺ always rinsed his mouth and nose in ghusl."}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "নিয়ত এবং পুরো শরীরে পানি পৌঁছানো ফরজ; কুলি ও নাকে পানি সুন্নত। মালেকি মতে শরীর ঘষা ও পরপর ধোয়াও জরুরি।", "en": "Intention and water reaching the whole body; rinsing the mouth and nose is sunnah. Malikis also require rubbing and continuity."}, "evidence": {"bn": "\"তোমার মাথায় তিন আঁজলা পানি ঢেলে তারপর পুরো শরীরে পানি ঢাললেই তুমি পবিত্র হয়ে যাবে\" — সহিহ মুসলিম ৩৩০।", "en": "\"It is enough for you to pour three handfuls on your head, then pour water over yourself, and you are purified\" (Sahih Muslim 330)."}}]}, {"type": "heading", "text": {"bn": "সুন্নত পদ্ধতিতে গোসল", "en": "Ghusl the sunnah way"}}, {"type": "step", "title": {"bn": "নিয়ত ও বিসমিল্লাহ", "en": "Intention and Bismillah"}, "text": {"bn": "মনে মনে নাপাকি দূর করার নিয়ত করুন এবং বিসমিল্লাহ বলুন (বাথরুমের ভেতরে হলে মনে মনে)।", "en": "Intend in your heart to remove the impurity and say Bismillah (silently if inside the bathroom)."}}, {"type": "step", "title": {"bn": "দুই হাত ধোয়া", "en": "Wash the hands"}, "text": {"bn": "দুই হাত কবজি পর্যন্ত তিনবার ধুয়ে নিন।", "en": "Wash both hands up to the wrists three times."}}, {"type": "step", "title": {"bn": "লজ্জাস্থান ধোয়া ও নাপাকি দূর করা", "en": "Wash the private parts and remove any impurity"}, "text": {"bn": "বাম হাত দিয়ে লজ্জাস্থান এবং শরীরের যেখানে নাপাকি লেগে আছে তা ধুয়ে ফেলুন, তারপর হাত ভালো করে পরিষ্কার করুন।", "en": "With the left hand wash the private parts and any place with impurity, then clean the hand well."}}, {"type": "step", "title": {"bn": "পূর্ণ ওযু করা", "en": "Make a complete wudu"}, "text": {"bn": "নামাজের ওযুর মতো পুরো ওযু করুন। দাঁড়ানোর জায়গায় পানি জমলে পা দুটো সবশেষে ধোয়া যায়।", "en": "Perform a full wudu as for prayer. If water collects where you stand, you may wash the feet at the very end."}}, {"type": "step", "title": {"bn": "মাথায় তিনবার পানি ঢালা", "en": "Pour water over the head three times"}, "text": {"bn": "মাথায় তিনবার পানি ঢালুন এবং আঙুল দিয়ে চুলের গোড়া পর্যন্ত পানি পৌঁছান।", "en": "Pour water on the head three times, working it into the roots of the hair with the fingers."}}, {"type": "step", "title": {"bn": "পুরো শরীরে পানি ঢালা", "en": "Pour water over the whole body"}, "text": {"bn": "প্রথমে ডান কাঁধে, তারপর বাম কাঁধে, তারপর পুরো শরীরে পানি ঢালুন। নাভি, বগল, কানের ভাঁজ, আঙুলের ফাঁক — কোথাও যেন শুকনো না থাকে।", "en": "Pour water over the right shoulder, then the left, then the whole body. Make sure the navel, armpits, folds of the ears and between the fingers and toes are not left dry."}}, {"type": "step", "title": {"bn": "পা ধোয়া", "en": "Wash the feet"}, "text": {"bn": "আগে পা না ধুয়ে থাকলে এখন সরে গিয়ে দুই পা ধুয়ে নিন।", "en": "If you left the feet earlier, move aside and wash them now."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২৪৮ (আয়েশা রা.) ও ২৪৯ (মাইমুনা রা.); সহিহ মুসলিম ৩১৬, ৩১৭ — রাসুলুল্লাহ ﷺ-এর গোসলের বিবরণ", "en": "Sahih al-Bukhari 248 (Aisha RA) and 249 (Maymunah RA); Sahih Muslim 316, 317: how the Prophet ﷺ performed ghusl"}}, {"type": "note", "tone": "info", "text": {"bn": "নারীদের চুল বেণি বা খোঁপা করা থাকলে, পানি চুলের গোড়ায় পৌঁছালে বেণি খোলা জরুরি নয় (সহিহ মুসলিম ৩৩০)।", "en": "A woman with braided hair need not undo the braids if water reaches the roots (Sahih Muslim 330)."}}, {"type": "note", "tone": "tip", "text": {"bn": "গোসলের আগে নখপালিশ বা পানি আটকায় এমন কিছু থাকলে তুলে ফেলুন; নইলে গোসল হবে না। গোসলের ভেতরে ওযু হয়ে যায় — গোসলের পর ওযু না ভাঙলে নতুন ওযু লাগবে না।", "en": "Remove nail polish or anything that blocks water first, or the ghusl is not valid. Wudu is included in the ghusl: if it is not broken afterwards, no new wudu is needed."}}, {"type": "note", "tone": "info", "text": {"bn": "জুমার দিন, দুই ঈদের দিন এবং ইহরাম বাঁধার আগে গোসল করা সুন্নত (ফরজ নয়)।", "en": "Ghusl on Friday, on the two Eids, and before entering ihram is sunnah, not fard."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮৭৭ — জুমার জন্য গোসল", "en": "Sahih al-Bukhari 877: ghusl for Jumu''ah"}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '2f19fc04-d1b4-5347-a8f3-717507f8c76c', id, 'tayammum', '{"bn": "তায়াম্মুম: কখন ও কীভাবে", "en": "Tayammum: When and How"}', '{"bn": "পানি না পেলে বা পানি ব্যবহারে ক্ষতি হলে মাটি দিয়ে পবিত্রতা অর্জন — শর্ত ও পদ্ধতি।", "en": "Purifying with clean earth when water is not available or would cause harm: conditions and method."}', 'basic', '[{"type": "text", "text": {"bn": "তায়াম্মুম আল্লাহর দেওয়া একটি সহজতা। পানি না পাওয়া গেলে বা পানি ব্যবহারে ক্ষতির আশঙ্কা থাকলে ওযু ও গোসল — দুটোর পরিবর্তেই পবিত্র মাটি দিয়ে তায়াম্মুম করা যায়।", "en": "Tayammum is an ease granted by Allah. When water cannot be found or using it would cause harm, tayammum with clean earth replaces both wudu and ghusl."}}, {"type": "arabic", "label": {"bn": "তায়াম্মুমের আয়াত (অংশ)", "en": "The ayah of tayammum (part)"}, "ar": "فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ", "pron": {"bn": "ফালাম তাজিদু মাআন ফাতাইয়াম্মামু সাঈদান তাইয়িবান ফামসাহু বিউজুহিকুম ওয়া আইদিকুম।", "en": "Falam tajidu ma''an fatayammamu sa''idan tayyiban famsahu biwujuhikum wa aydikum."}, "meaning": {"bn": "অতঃপর যদি পানি না পাও, তবে পবিত্র মাটি দিয়ে তায়াম্মুম করো — তা দিয়ে তোমাদের মুখমণ্ডল ও হাত মাসেহ করো।", "en": "And if you find no water, then seek clean earth and wipe your faces and hands with it."}, "ref": {"bn": "সূরা নিসা ৪:৪৩; সূরা মায়েদা ৫:৬", "en": "An-Nisa 4:43; Al-Ma''idah 5:6"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩৩৫ — \"সমস্ত জমিন আমার জন্য মসজিদ ও পবিত্রতার উপকরণ করা হয়েছে\"", "en": "Sahih al-Bukhari 335: \"The earth has been made for me a place of prayer and a means of purification\""}}, {"type": "heading", "text": {"bn": "কখন তায়াম্মুম করা যায়", "en": "When tayammum is allowed"}}, {"type": "list", "items": [{"bn": "আশেপাশে পানি পাওয়া যায় না (হানাফি মতে প্রায় এক মাইল বা তার বেশি দূরে)", "en": "No water nearby (in the Hanafi view, about a mile away or more)"}, {"bn": "অসুস্থতা বা ক্ষত, যেখানে পানি ব্যবহারে রোগ বাড়া বা দেরিতে সারার আশঙ্কা আছে", "en": "Illness or wounds where water would worsen or delay healing"}, {"bn": "প্রচণ্ড ঠান্ডা, পানি গরম করার ব্যবস্থা নেই এবং ঠান্ডা পানিতে গুরুতর ক্ষতির আশঙ্কা", "en": "Severe cold with no way to heat water and real risk of harm"}, {"bn": "যে পানি আছে তা খাওয়ার জন্য প্রয়োজন", "en": "The only water available is needed for drinking"}, {"bn": "পানির কাছে যেতে শত্রু, হিংস্র প্রাণী বা অন্য কোনো বিপদের ভয়", "en": "Fear of an enemy, animal or other danger on the way to water"}]}, {"type": "note", "tone": "warn", "text": {"bn": "শুধু অলসতা বা পানি একটু দূরে বলে তায়াম্মুম জায়েজ নয়। পানি ব্যবহারের সামর্থ্য থাকলে তায়াম্মুম দিয়ে নামাজ হবে না।", "en": "Laziness, or water being slightly far, is not a valid reason. If you are able to use water, salah with tayammum is not valid."}}, {"type": "heading", "text": {"bn": "তায়াম্মুমের পদ্ধতি (হানাফি ও শাফেয়ি মত অনুযায়ী)", "en": "How to do tayammum (Hanafi and Shafi''i method)"}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "মনে মনে পবিত্রতা অর্জনের নিয়ত করুন। তায়াম্মুমে নিয়ত সব মাযহাবেই জরুরি।", "en": "Intend in your heart to purify yourself. Intention is required for tayammum in all the madhhabs."}}, {"type": "step", "title": {"bn": "বিসমিল্লাহ", "en": "Bismillah"}, "text": {"bn": "বিসমিল্লাহ বলুন।", "en": "Say Bismillah."}}, {"type": "step", "title": {"bn": "প্রথম বার মাটিতে হাত মারা ও মুখ মাসেহ", "en": "First strike: wipe the face"}, "text": {"bn": "দুই হাতের তালু পবিত্র মাটি, বালু বা পাথরে আলতো করে মারুন, অতিরিক্ত ধুলা ঝেড়ে নিন বা ফুঁ দিন, তারপর পুরো মুখমণ্ডল একবার মাসেহ করুন।", "en": "Strike both palms lightly on clean earth, sand or stone, shake or blow off the excess, then wipe the whole face once."}}, {"type": "step", "title": {"bn": "দ্বিতীয় বার হাত মারা ও দুই হাত মাসেহ", "en": "Second strike: wipe the arms"}, "text": {"bn": "আবার মাটিতে হাত মারুন। বাম হাত দিয়ে ডান হাত আঙুল থেকে কনুইসহ মাসেহ করুন, তারপর ডান হাত দিয়ে বাম হাত একইভাবে। আংটি থাকলে নাড়িয়ে নিন।", "en": "Strike again. Wipe the right arm from the fingers to and including the elbow with the left hand, then the left arm with the right hand. Move any ring."}}, {"type": "differ", "title": {"bn": "তায়াম্মুমে কয়বার মাটিতে হাত মারতে হবে, হাত কতটুকু মাসেহ করতে হবে?", "en": "How many strikes, and how much of the arms is wiped?"}, "views": [{"label": {"bn": "হানাফি ও শাফেয়ি", "en": "Hanafi and Shafi''i"}, "text": {"bn": "দুই বার মারা — একবার মুখের জন্য, একবার কনুইসহ দুই হাতের জন্য।", "en": "Two strikes: one for the face and one for the arms up to and including the elbows."}, "evidence": {"bn": "ইবনে উমর (রা.) সহ কয়েকজন সাহাবি থেকে এভাবে বর্ণিত (সুনান দারাকুতনি, মুয়াত্তা মালিক); ওযুতে হাত কনুই পর্যন্ত ধোয়ার সাথে মিল।", "en": "Reported from Ibn Umar (RA) and others (Sunan ad-Daraqutni, Muwatta Malik); it matches washing the arms to the elbows in wudu."}}, {"label": {"bn": "হাম্বলি ও অনেক মুহাদ্দিস (মালেকি মতে এটুকুই ফরজ)", "en": "Hanbali and many hadith scholars (for Malikis this is the obligatory minimum)"}, "text": {"bn": "একবার মাটিতে হাত মেরে মুখ এবং কবজি পর্যন্ত দুই হাত মাসেহ করাই যথেষ্ট।", "en": "One strike, wiping the face and the hands up to the wrists, is enough."}, "evidence": {"bn": "আম্মার (রা.)-কে রাসুলুল্লাহ ﷺ একবার মাটিতে হাত মেরে মুখ ও দুই হাত মাসেহ করে দেখিয়েছেন — সহিহ বুখারি ৩৩৮; সহিহ মুসলিম ৩৬৮।", "en": "The Prophet ﷺ showed Ammar (RA) one strike, then wiped his face and hands (Sahih al-Bukhari 338; Sahih Muslim 368)."}}], "check": true}, {"type": "heading", "text": {"bn": "তায়াম্মুম কী দিয়ে এবং কখন ভাঙে", "en": "What to use, and what ends tayammum"}}, {"type": "text", "text": {"bn": "মাটি, বালু, পাথর, ইট বা মাটিজাতীয় পবিত্র জিনিস দিয়ে তায়াম্মুম করা যায় (হানাফি মত)। শাফেয়ি মতে ধুলাযুক্ত মাটি জরুরি। যেসব কারণে ওযু বা গোসল ভাঙে, সেগুলোতে তায়াম্মুমও ভাঙে; আর পানি পাওয়া গেলে বা পানি ব্যবহারের সামর্থ্য ফিরে এলে তায়াম্মুম শেষ হয়ে যায়।", "en": "Earth, sand, stone, brick or anything of the earth''s kind may be used (Hanafi view); Shafi''is require earth with dust. Tayammum is broken by whatever breaks wudu or ghusl, and it ends once water is found or one becomes able to use it."}}, {"type": "note", "tone": "info", "text": {"bn": "এক তায়াম্মুমে ওযু ও গোসল দুটোর কাজই হয়, নিয়ত অনুযায়ী। আমর ইবনুল আস (রা.) প্রচণ্ড ঠান্ডায় গোসলের বদলে তায়াম্মুম করেছিলেন এবং রাসুলুল্লাহ ﷺ তা মেনে নিয়েছিলেন (সুনান আবু দাউদ ৩৩৪)।", "en": "The same tayammum serves for wudu or ghusl, according to the intention. Amr ibn al-As (RA) did tayammum instead of ghusl in severe cold and the Prophet ﷺ approved (Sunan Abi Dawud 334)."}, "check": true}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '7509a390-592c-5eab-980e-528a7af765b6', id, 'masah-on-khuff', '{"bn": "মোজার উপর মাসেহ", "en": "Wiping over Khuffs (Leather Socks)"}', '{"bn": "ওযুতে পা না ধুয়ে মোজার উপর মাসেহ করার শর্ত, সময়সীমা ও পদ্ধতি।", "en": "Conditions, time limits and method for wiping over khuffs in wudu instead of washing the feet."}', 'detail', '[{"type": "text", "text": {"bn": "মোজার উপর মাসেহ রাসুলুল্লাহ ﷺ থেকে বহু সাহাবির সূত্রে প্রমাণিত একটি সহজতা। পূর্ণ ওযু করে মোজা পরলে, পরবর্তী ওযুতে পা ধোয়ার বদলে মোজার উপরে ভেজা হাত বুলিয়ে নেওয়া যায়।", "en": "Wiping over khuffs is an ease established from the Prophet ﷺ through many Companions. If you put them on after a complete wudu, in later wudus you may wipe over them with wet hands instead of washing the feet."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০৬; সহিহ মুসলিম ২৭৪ — \"এগুলো থাক, আমি পবিত্র অবস্থায় পরেছি\" (মুগিরা রা.)", "en": "Sahih al-Bukhari 206; Sahih Muslim 274: \"Leave them, I put them on in a state of purity\" (al-Mughirah RA)"}}, {"type": "heading", "text": {"bn": "শর্তসমূহ", "en": "Conditions"}}, {"type": "list", "items": [{"bn": "পূর্ণ ওযু করার পর মোজা পরতে হবে", "en": "The khuffs must be put on after a complete wudu"}, {"bn": "মোজা টাখনুসহ পুরো পা ঢেকে রাখবে", "en": "They must cover the whole foot including the ankles"}, {"bn": "এত মজবুত হবে যে তা পরে স্বাভাবিকভাবে হাঁটা যায়", "en": "They must be strong enough to walk in normally"}, {"bn": "বড় ছেঁড়া থাকবে না (হানাফি মতে পায়ের ছোট তিন আঙুল পরিমাণ ছেঁড়া হলে মাসেহ হবে না)", "en": "No large tear (Hanafi: a tear the size of three small toes prevents wiping)"}, {"bn": "গোসল ফরজ হলে মোজা খুলে গোসল করতে হবে — মাসেহ শুধু ওযুর জন্য", "en": "If ghusl becomes due, the khuffs must be removed; wiping is only for wudu"}]}, {"type": "heading", "text": {"bn": "সময়সীমা", "en": "Time limit"}}, {"type": "table", "head": [{"bn": "অবস্থা", "en": "Situation"}, {"bn": "মাসেহের মেয়াদ", "en": "Duration of wiping"}], "rows": [[{"bn": "নিজ এলাকায় অবস্থানকারী (মুকিম)", "en": "Resident"}, {"bn": "এক দিন এক রাত (২৪ ঘণ্টা)", "en": "One day and night (24 hours)"}], [{"bn": "মুসাফির (শরিয়তসম্মত সফরে)", "en": "Traveller (on a journey)"}, {"bn": "তিন দিন তিন রাত (৭২ ঘণ্টা)", "en": "Three days and nights (72 hours)"}]]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৭৬ (আলি রা.)", "en": "Sahih Muslim 276 (Ali RA)"}}, {"type": "note", "tone": "info", "text": {"bn": "হানাফি ও শাফেয়ি মতে মেয়াদ গণনা শুরু হয় মোজা পরার পর প্রথম যখন ওযু ভাঙে তখন থেকে।", "en": "In the Hanafi and Shafi''i views, the period is counted from the first time wudu breaks after putting the khuffs on."}}, {"type": "heading", "text": {"bn": "মাসেহের পদ্ধতি", "en": "How to wipe"}}, {"type": "step", "title": {"bn": "হাত ভেজানো", "en": "Wet the hands"}, "text": {"bn": "ওযুর বাকি সব অঙ্গ ধোয়ার পর দুই হাত পানিতে ভিজিয়ে নিন।", "en": "After washing the other parts of wudu, wet both hands."}}, {"type": "step", "title": {"bn": "মোজার উপরিভাগ মাসেহ", "en": "Wipe the top of the khuffs"}, "text": {"bn": "ডান হাতের আঙুলগুলো ডান পায়ের মোজার উপরে আঙুলের মাথা থেকে টেনে পায়ের গোছার দিকে নিয়ে যান; বাম হাত দিয়ে বাম পায়ে একইভাবে — একবার। হানাফি মতে কমপক্ষে হাতের ছোট তিন আঙুল পরিমাণ জায়গা মাসেহ করা ফরজ।", "en": "Draw the wet fingers of the right hand over the top of the right khuff from the toes towards the shin, and the left hand over the left, once. In the Hanafi view at least the width of three fingers must be wiped."}}, {"type": "note", "tone": "info", "text": {"bn": "মোজার নিচের দিকে বা গোড়ালিতে মাসেহ নেই। আলি (রা.) বলেছেন, দ্বীন যদি নিছক যুক্তি দিয়ে চলত, তবে মোজার উপরের চেয়ে নিচের দিক মাসেহ করাই বেশি যুক্তিযুক্ত হতো (সুনান আবু দাউদ ১৬২)।", "en": "The underside and heel are not wiped. Ali (RA) said that if religion were based on opinion, wiping the underside would seem more fitting than the top (Sunan Abi Dawud 162)."}}, {"type": "heading", "text": {"bn": "মাসেহ যেভাবে ভাঙে", "en": "What ends the wiping"}}, {"type": "list", "items": [{"bn": "যেসব কারণে ওযু ভাঙে", "en": "Anything that breaks wudu (then wipe again in the new wudu)"}, {"bn": "এক বা দুই পায়ের মোজা খুলে ফেলা বা পায়ের বেশির ভাগ বের হয়ে যাওয়া", "en": "Removing one or both khuffs, or most of the foot coming out"}, {"bn": "মেয়াদ শেষ হয়ে যাওয়া", "en": "The time limit running out"}, {"bn": "গোসল ফরজ হওয়া", "en": "Ghusl becoming obligatory"}]}, {"type": "note", "tone": "tip", "text": {"bn": "ওযু থাকা অবস্থায় মোজা খুললে বা মেয়াদ শেষ হলে হানাফি মতে শুধু দুই পা ধুয়ে নিলেই চলে; পুরো ওযু নতুন করে করা উত্তম।", "en": "If you remove the khuffs or the time ends while you still have wudu, the Hanafi view is that washing the feet is enough; repeating the whole wudu is better."}}, {"type": "differ", "title": {"bn": "সাধারণ কাপড়ের বা নাইলনের পাতলা মোজায় মাসেহ করা যাবে কি?", "en": "Can one wipe over ordinary thin cloth or nylon socks?"}, "views": [{"label": {"bn": "হানাফি, শাফেয়ি ও মালেকি", "en": "Hanafi, Shafi''i and Maliki"}, "text": {"bn": "চামড়ার মোজা (খুফ) বা এমন মোটা মোজায় মাসেহ জায়েজ যা খুফের মতো — বাঁধা ছাড়াই পায়ে থাকে, পানি সহজে ভেতরে যায় না এবং পরে অনেক পথ হাঁটা যায়। সাধারণ পাতলা সুতি বা নাইলনের মোজায় মাসেহ জায়েজ নয়।", "en": "Wiping is allowed over leather khuffs, or thick socks that act like khuffs: they stay up without tying, do not let water through easily, and can be walked in for a long distance. Ordinary thin cotton or nylon socks do not qualify."}, "evidence": {"bn": "মাসেহের মূল দলিল খুফ নিয়ে, যা মুতাওয়াতির; অন্য মোজাকে শুধু তখনই খুফের হুকুমে আনা যায় যখন তা খুফের মতো হয়। জাওরাবের হাদিসের সনদ নিয়ে অনেক মুহাদ্দিস আপত্তি করেছেন।", "en": "The mass-transmitted evidence is about khuffs; other socks take the same ruling only if they are like khuffs. Many hadith scholars criticised the chain of the narration about socks (jawrab)."}}, {"label": {"bn": "হাম্বলি ও কিছু আলেম", "en": "Hanbali and some scholars"}, "text": {"bn": "পা ঢেকে রাখে এমন সাধারণ মোজাতেও মাসেহ জায়েজ, যদিও শর্তের বিস্তারিত নিয়ে তাদের মধ্যেও পার্থক্য আছে।", "en": "Wiping over ordinary socks that cover the foot is permitted, though they also differ on the exact conditions."}, "evidence": {"bn": "মুগিরা (রা.) বর্ণনা করেছেন, রাসুলুল্লাহ ﷺ জাওরাব (মোজা) ও জুতার উপর মাসেহ করেছেন — সুনান আবু দাউদ ১৫৯; সুনান তিরমিযি ৯৯; কয়েকজন সাহাবির আমল।", "en": "Al-Mughirah (RA) reported that the Prophet ﷺ wiped over socks and sandals (Sunan Abi Dawud 159; Jami at-Tirmidhi 99); practice of several Companions."}}], "check": true}, {"type": "note", "tone": "info", "text": {"bn": "ক্ষতস্থানে ব্যান্ডেজ বা প্লাস্টার থাকলে এবং তা খুলে পানি দেওয়া ক্ষতিকর হলে, ব্যান্ডেজের উপর ভেজা হাত বুলিয়ে মাসেহ করা যায় — এর কোনো সময়সীমা নেই।", "en": "If there is a bandage or cast on a wound and removing it or washing would cause harm, wipe over it with a wet hand. There is no time limit for this."}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '29f60a12-ce89-5ef0-b4d7-fd6fb4f267f5', id, 'istinja', '{"bn": "ইস্তিঞ্জা ও টয়লেটের আদব", "en": "Istinja and Toilet Etiquette"}', '{"bn": "পেশাব-পায়খানার পর পবিত্র হওয়ার নিয়ম, টয়লেটে ঢোকা-বের হওয়ার দোয়া এবং জরুরি আদব।", "en": "How to clean oneself after relieving oneself, the duas for entering and leaving, and key etiquette."}', 'basic', '[{"type": "text", "text": {"bn": "পেশাব-পায়খানার পর পানি, টিস্যু বা ঢিলা দিয়ে নাপাকি পরিষ্কার করাকে ইস্তিঞ্জা বলে। পেশাবের ছিটা থেকে সাবধান না থাকা কবরের আজাবের একটি কারণ বলে রাসুলুল্লাহ ﷺ সতর্ক করেছেন।", "en": "Istinja is cleaning away impurity with water, tissue or stones after relieving oneself. The Prophet ﷺ warned that carelessness about urine splashes is a cause of punishment in the grave."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২১৮; সহিহ মুসলিম ২৯২ — দুই কবরের ঘটনা", "en": "Sahih al-Bukhari 218; Sahih Muslim 292: the two graves"}}, {"type": "heading", "text": {"bn": "টয়লেটে ঢোকার সময়", "en": "When entering the toilet"}}, {"type": "arabic", "label": {"bn": "প্রবেশের দোয়া (বাম পা দিয়ে, ভেতরে যাওয়ার আগে)", "en": "Dua for entering (step in with the left foot, said before entering)"}, "ar": "بِسْمِ اللَّهِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ", "pron": {"bn": "বিসমিল্লাহ, আল্লাহুম্মা ইন্নি আউযু বিকা মিনাল খুবুসি ওয়াল খাবায়িস।", "en": "Bismillah. Allahumma inni a''udhu bika minal-khubuthi wal-khaba''ith."}, "meaning": {"bn": "আল্লাহর নামে। হে আল্লাহ! আমি আপনার কাছে পুরুষ ও নারী শয়তান (সব ধরনের অনিষ্ট) থেকে আশ্রয় চাই।", "en": "In the name of Allah. O Allah, I seek refuge with You from the male and female devils (from all filth and evil)."}, "ref": {"bn": "সহিহ বুখারি ১৪২; সহিহ মুসলিম ৩৭৫ (শুরুতে বিসমিল্লাহ: সুনান তিরমিযি)", "en": "Sahih al-Bukhari 142; Sahih Muslim 375 (Bismillah at the start: Jami at-Tirmidhi)"}, "check": true}, {"type": "heading", "text": {"bn": "বের হওয়ার সময়", "en": "When leaving"}}, {"type": "arabic", "label": {"bn": "বের হওয়ার দোয়া (ডান পা দিয়ে বের হয়ে)", "en": "Dua for leaving (step out with the right foot)"}, "ar": "غُفْرَانَكَ", "pron": {"bn": "গুফরানাকা", "en": "Ghufranaka"}, "meaning": {"bn": "হে আল্লাহ! আমি আপনার ক্ষমা চাই।", "en": "O Allah, I ask Your forgiveness."}, "ref": {"bn": "সুনান আবু দাউদ ৩০; সুনান তিরমিযি ৭", "en": "Sunan Abi Dawud 30; Jami'' at-Tirmidhi 7"}}, {"type": "heading", "text": {"bn": "ইস্তিঞ্জার নিয়ম", "en": "How to do istinja"}}, {"type": "step", "title": {"bn": "বাম হাত ব্যবহার করা", "en": "Use the left hand"}, "text": {"bn": "পরিষ্কারের কাজ বাম হাতে করুন; ডান হাতে লজ্জাস্থান ধরবেন না।", "en": "Clean with the left hand; do not hold the private part with the right hand."}}, {"type": "step", "title": {"bn": "টিস্যু বা ঢিলা", "en": "Tissue or stones"}, "text": {"bn": "প্রথমে টিস্যু, ঢিলা বা পবিত্র কিছু দিয়ে নাপাকি মুছে নিন — বেজোড় সংখ্যায়, কমপক্ষে তিনবার। হাড় বা গোবর দিয়ে নয়।", "en": "First wipe the impurity with tissue, stones or other clean material, an odd number of times and at least three. Not with bone or dung."}}, {"type": "step", "title": {"bn": "পানি দিয়ে ধোয়া", "en": "Wash with water"}, "text": {"bn": "তারপর পানি দিয়ে ভালো করে ধুয়ে নিন। টিস্যু ও পানি দুটো একসাথে ব্যবহার করা সবচেয়ে উত্তম; শুধু পানিও যথেষ্ট।", "en": "Then wash well with water. Using both tissue and water is best; water alone is enough."}}, {"type": "step", "title": {"bn": "হাত পরিষ্কার করা", "en": "Clean the hands"}, "text": {"bn": "শেষে সাবান বা মাটি দিয়ে হাত ভালোভাবে ধুয়ে নিন।", "en": "Finally wash the hands well with soap or earth."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৬২ (সালমান রা.) — কিবলামুখী না হওয়া, ডান হাতে ইস্তিঞ্জা না করা, তিনটির কম ঢিলা না নেওয়া, হাড় ও গোবর ব্যবহার না করা", "en": "Sahih Muslim 262 (Salman RA): not facing the qiblah, not cleaning with the right hand, not fewer than three stones, not using bone or dung"}}, {"type": "heading", "text": {"bn": "জরুরি আদব", "en": "Key etiquette"}}, {"type": "list", "items": [{"bn": "পেশাব-পায়খানার সময় কিবলার দিকে মুখ বা পিঠ করে বসবেন না — খোলা জায়গায় এটা নিষিদ্ধ; ঘরের ভেতরেও এড়িয়ে চলা নিরাপদ (হানাফি মতে ঘরের ভেতরেও মাকরুহ)।", "en": "Do not face or turn your back to the qiblah while relieving yourself. It is forbidden in the open; avoiding it indoors is safer (Hanafis hold it disliked indoors too)."}, {"bn": "পেশাবের ছিটা যেন শরীর বা কাপড়ে না লাগে; সম্ভব হলে বসে পেশাব করুন।", "en": "Avoid splashes on the body and clothes; sit to urinate where possible."}, {"bn": "আল্লাহর নাম লেখা কিছু (যেমন আংটি বা কাগজ) টয়লেটে না নেওয়া উত্তম।", "en": "It is better not to take anything with Allah''s name written on it into the toilet."}, {"bn": "ভেতরে কথা বলা, জিকির বা সালামের জবাব দেওয়া থেকে বিরত থাকুন।", "en": "Avoid talking, dhikr or returning greetings inside."}, {"bn": "মানুষের চলাচলের পথ, ছায়া ও পানির উৎসে পেশাব-পায়খানা করবেন না।", "en": "Do not relieve yourself on paths, in shade people use, or in water sources."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪৪; সহিহ মুসলিম ২৬৪ — কিবলার দিকে মুখ বা পিঠ না করা (আবু আইয়ুব রা.)", "en": "Sahih al-Bukhari 144; Sahih Muslim 264: not facing or turning one''s back to the qiblah (Abu Ayyub RA)"}}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'b46fb125-3852-5d8f-ae39-fc8735d6fe26', id, 'hayd-nifas-salah', '{"bn": "হায়েজ ও নিফাস: নামাজের বিধান", "en": "Menstruation and Post-natal Bleeding: Rulings for Salah"}', '{"bn": "মাসিক ও প্রসব-পরবর্তী রক্তস্রাবের সময় নামাজ, রোজা ও অন্যান্য ইবাদতের বিধান — সংক্ষেপে।", "en": "A short guide to salah, fasting and other worship during menstruation and post-natal bleeding."}', 'detail', '[{"type": "text", "text": {"bn": "হায়েজ (মাসিক) ও নিফাস (সন্তান প্রসবের পরের রক্তস্রাব) আল্লাহর সৃষ্টিগত স্বাভাবিক বিষয়। এ সময় নারীদের জন্য নামাজ মাফ — এটা আল্লাহর দেওয়া সহজতা, এতে কোনো গুনাহ নেই।", "en": "Menstruation (hayd) and post-natal bleeding (nifas) are natural matters created by Allah. During them women are excused from salah. It is an ease from Allah, and there is no sin in it."}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:২২২", "en": "Al-Baqarah 2:222"}}, {"type": "heading", "text": {"bn": "এ সময় যা নিষিদ্ধ", "en": "What is not allowed during this time"}}, {"type": "list", "items": [{"bn": "নামাজ পড়া — এবং পরে এই নামাজগুলো কাজা করতে হয় না", "en": "Praying salah, and these prayers are not made up later"}, {"bn": "রোজা রাখা — তবে রমজানের ছুটে যাওয়া রোজা পরে কাজা করতে হবে", "en": "Fasting, but missed Ramadan fasts must be made up later"}, {"bn": "কাবার তাওয়াফ", "en": "Tawaf of the Ka''bah"}, {"bn": "কুরআন শরিফ (মুসহাফ) সরাসরি স্পর্শ করা", "en": "Touching the Mushaf directly"}, {"bn": "মসজিদে অবস্থান করা", "en": "Staying in the mosque"}, {"bn": "স্বামী-স্ত্রীর মিলন", "en": "Marital intercourse"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৩৫; সহিহ বুখারি ৩২১ — \"আমাদের রোজা কাজা করার আদেশ দেওয়া হতো, নামাজ কাজার আদেশ দেওয়া হতো না\" (আয়েশা রা.)", "en": "Sahih Muslim 335; Sahih al-Bukhari 321: \"We were ordered to make up the fasts but not the prayers\" (Aisha RA)"}}, {"type": "note", "tone": "info", "text": {"bn": "অধিকাংশ আলেমের (হানাফি, শাফেয়ি, হাম্বলি) মতে এ সময় কুরআন তিলাওয়াত করা যায় না; মালেকি মাযহাব ও কিছু আলেম অনুমতি দিয়েছেন, কারণ নিষেধের হাদিসটির সনদ দুর্বল। জিকির, দোয়া, দরুদ, ইস্তিগফার এবং কুরআন শোনা সবার মতেই জায়েজ।", "en": "Most scholars (Hanafi, Shafi''i, Hanbali) hold that she does not recite the Quran in this state; the Maliki school and some others allow it, as the hadith forbidding it has a weak chain. Dhikr, dua, durood, istighfar and listening to the Quran are allowed by all."}, "check": true}, {"type": "heading", "text": {"bn": "সময়সীমা", "en": "Durations"}}, {"type": "differ", "title": {"bn": "হায়েজ ও নিফাসের সর্বনিম্ন ও সর্বোচ্চ সময়", "en": "Minimum and maximum duration of hayd and nifas"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "হায়েজ: সর্বনিম্ন ৩ দিন, সর্বোচ্চ ১০ দিন। নিফাস: সর্বোচ্চ ৪০ দিন, সর্বনিম্ন কোনো সীমা নেই। এর বাইরের রক্ত ইস্তিহাযা (রোগজনিত)।", "en": "Hayd: minimum 3 days, maximum 10. Nifas: maximum 40 days, no minimum. Bleeding outside these limits is istihadah (irregular bleeding)."}, "evidence": {"bn": "কিছু সাহাবি থেকে বর্ণিত বক্তব্য (যার সনদ নিয়ে আলোচনা আছে); নিফাসে নারীরা ৪০ দিন বসে থাকতেন — সুনান আবু দাউদ ৩১১।", "en": "Statements reported from some Companions (whose chains are discussed); women used to wait 40 days after childbirth (Sunan Abi Dawud 311)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি (মালেকি ভিন্ন হিসাবে)", "en": "Shafi''i and Hanbali (Maliki counts differently)"}, "text": {"bn": "হায়েজ: সর্বনিম্ন এক দিন এক রাত, সর্বোচ্চ ১৫ দিন। নিফাস: সর্বোচ্চ ৬০ দিন (শাফেয়ি, মালেকি) বা ৪০ দিন (হাম্বলি)।", "en": "Hayd: minimum one day and night, maximum 15 days. Nifas: maximum 60 days (Shafi''i, Maliki) or 40 (Hanbali)."}, "evidence": {"bn": "কুরআন-হাদিসে নির্দিষ্ট সীমা স্পষ্টভাবে নেই বলে তারা নারীদের বাস্তব অভিজ্ঞতা ও প্রচলিত অভ্যাসকে ভিত্তি ধরেছেন।", "en": "As the texts give no explicit limit, they based it on women''s actual, observed patterns."}}], "check": true}, {"type": "heading", "text": {"bn": "পবিত্র হলে নামাজ", "en": "Resuming salah"}}, {"type": "step", "title": {"bn": "রক্ত বন্ধ হলে গোসল", "en": "Ghusl when the bleeding stops"}, "text": {"bn": "রক্ত পুরোপুরি বন্ধ হলে (সাদা স্রাব দেখা গেলে বা পুরো শুকনো থাকলে) ফরজ গোসল করে নামাজ শুরু করুন। নিফাসে ৪০ দিনের আগে রক্ত বন্ধ হলেও গোসল করে নামাজ পড়তে হবে।", "en": "When the bleeding fully stops (clear discharge or complete dryness), do the obligatory ghusl and start praying. If post-natal bleeding stops before 40 days, she still does ghusl and prays."}}, {"type": "step", "title": {"bn": "ওয়াক্তের ভেতরে পবিত্র হলে", "en": "Becoming pure within a prayer time"}, "text": {"bn": "কোনো নামাজের ওয়াক্ত থাকতেই রক্ত বন্ধ হলে, গোসল করে সেই ওয়াক্তের নামাজ আদায় করা জরুরি। কতটুকু সময় বাকি থাকলে নামাজ জরুরি হয় — এর বিস্তারিত নিয়ে মাযহাবগুলোতে পার্থক্য আছে; স্থানীয় আলেমের কাছে জেনে নিন।", "en": "If the bleeding stops while a prayer''s time remains, she does ghusl and prays that prayer. How much time must remain for this differs between the madhhabs; ask a local scholar for the details."}}, {"type": "note", "tone": "info", "text": {"bn": "পবিত্র হওয়ার পর হলুদ বা বাদামি স্রাব দেখা দিলে তা হায়েজ হিসেবে গণ্য হয় না (সহিহ বুখারি ৩২৬)।", "en": "Yellowish or brownish discharge after purity is not counted as menstruation (Sahih al-Bukhari 326)."}}, {"type": "heading", "text": {"bn": "ইস্তিহাযা (অনিয়মিত রক্তস্রাব)", "en": "Istihadah (irregular bleeding)"}}, {"type": "text", "text": {"bn": "স্বাভাবিক সময়ের বাইরে যে রক্ত আসে তা ইস্তিহাযা — এটা রোগজনিত, হায়েজ নয়। এ অবস্থায় নামাজ-রোজা মাফ নয়। প্রতি ওয়াক্তে নতুন ওযু করে নামাজ পড়বেন এবং প্যাড ব্যবহার করবেন।", "en": "Bleeding outside the normal pattern is istihadah: an illness, not menstruation. Salah and fasting are not excused. She makes a fresh wudu for each prayer time, uses a pad, and prays."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২২৮ — \"এটা একটা শিরার রক্ত, হায়েজ নয়… প্রত্যেক নামাজের জন্য ওযু করো\" (ফাতিমা বিনতে আবি হুবাইশ রা.)", "en": "Sahih al-Bukhari 228: \"That is from a blood vessel, not menstruation… make wudu for every prayer\" (Fatimah bint Abi Hubaysh RA)"}}, {"type": "note", "tone": "tip", "text": {"bn": "নিজের মাসিকের নিয়ম (কত দিন, কবে শুরু) লিখে রাখলে ইস্তিহাযা আর হায়েজ আলাদা করা সহজ হয়। জটিল অবস্থায় একজন নির্ভরযোগ্য আলেম ও ডাক্তারের পরামর্শ নিন।", "en": "Keeping a record of your usual cycle (how many days, when it starts) makes it easier to tell istihadah from menstruation. In complicated cases, consult a trusted scholar and a doctor."}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'taharah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '07e0a56a-7be7-50b7-ae6f-9a877d06d1d6', id, 'salah-importance', '{"bn": "নামাজের গুরুত্ব", "en": "The Importance of Salah"}', '{"bn": "নামাজ ইসলামের দ্বিতীয় স্তম্ভ এবং কিয়ামতের দিন বান্দার প্রথম হিসাব। কুরআন ও সহিহ হাদিসে নামাজের মর্যাদা।", "en": "Salah is the second pillar of Islam and the first deed to be judged on the Day of Judgement. Its place in the Quran and authentic hadith."}', 'basic', '[{"type": "text", "text": {"bn": "ঈমানের পর ইসলামের সবচেয়ে বড় ফরজ ইবাদত হলো নামাজ। প্রত্যেক প্রাপ্তবয়স্ক, সুস্থ মস্তিষ্কের মুসলিম নারী-পুরুষের উপর দিনে পাঁচ ওয়াক্ত নামাজ ফরজ। অসুস্থ হলে বসে বা শুয়ে, সফরে সংক্ষেপে — কিন্তু জ্ঞান থাকা পর্যন্ত নামাজ মাফ হয় না।", "en": "After faith, salah is the greatest obligation in Islam. Five daily prayers are obligatory on every adult, sane Muslim man and woman. When ill one prays sitting or lying down, when travelling it is shortened, but as long as one is conscious it is never dropped."}}, {"type": "arabic", "label": {"bn": "নামাজের প্রতি যত্নবান হওয়ার আদেশ", "en": "The command to guard the prayers"}, "ar": "حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَىٰ وَقُومُوا لِلَّهِ قَانِتِينَ", "pron": {"bn": "হাফিযু আলাস সালাওয়াতি ওয়াস সালাতিল উসতা, ওয়া কুমু লিল্লাহি কানিতিন।", "en": "Hafizu ''alas-salawati was-salatil-wusta wa qumu lillahi qanitin."}, "meaning": {"bn": "তোমরা নামাজগুলোর প্রতি যত্নবান হও, বিশেষ করে মধ্যবর্তী নামাজের প্রতি, এবং আল্লাহর সামনে বিনীতভাবে দাঁড়াও।", "en": "Guard the prayers, especially the middle prayer, and stand before Allah in devout obedience."}, "ref": {"bn": "সূরা বাকারা ২:২৩৮", "en": "Al-Baqarah 2:238"}}, {"type": "arabic", "label": {"bn": "নামাজ মন্দ কাজ থেকে বিরত রাখে", "en": "Prayer restrains from wrong"}, "ar": "وَأَقِمِ الصَّلَاةَ ۖ إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ", "pron": {"bn": "ওয়া আকিমিস সালাহ, ইন্নাস সালাতা তানহা আনিল ফাহশায়ি ওয়াল মুনকার।", "en": "Wa aqimis-salah, innas-salata tanha ''anil-fahsha''i wal-munkar."}, "meaning": {"bn": "আর নামাজ কায়েম করো। নিশ্চয়ই নামাজ অশ্লীল ও মন্দ কাজ থেকে বিরত রাখে।", "en": "And establish prayer. Indeed, prayer restrains from indecency and wrongdoing."}, "ref": {"bn": "সূরা আনকাবুত ২৯:৪৫ (অংশ)", "en": "Al-''Ankabut 29:45 (part)"}}, {"type": "heading", "text": {"bn": "হাদিসে নামাজের মর্যাদা", "en": "Salah in the hadith"}}, {"type": "list", "items": [{"bn": "ইসলাম পাঁচটি স্তম্ভের উপর প্রতিষ্ঠিত — কালিমার সাক্ষ্য, নামাজ কায়েম, যাকাত, হজ ও রমজানের রোজা। (সহিহ বুখারি ৮; সহিহ মুসলিম ১৬)", "en": "Islam is built on five: the testimony, establishing prayer, zakat, hajj and fasting Ramadan. (Sahih al-Bukhari 8; Sahih Muslim 16)"}, {"bn": "কিয়ামতের দিন বান্দার আমলের মধ্যে প্রথম হিসাব নেওয়া হবে নামাজের। (সুনান তিরমিযি ৪১৩)", "en": "The first of a servant''s deeds to be judged on the Day of Resurrection is his prayer. (Jami at-Tirmidhi 413)"}, {"bn": "কারো দরজার সামনে নদী থাকলে আর সে দিনে পাঁচবার তাতে গোসল করলে যেমন শরীরে ময়লা থাকে না, পাঁচ ওয়াক্ত নামাজ তেমনি গুনাহ মুছে দেয়। (সহিহ বুখারি ৫২৮; সহিহ মুসলিম ৬৬৭)", "en": "Like a river at one''s door in which one bathes five times a day, leaving no dirt, the five prayers wipe away sins. (Sahih al-Bukhari 528; Sahih Muslim 667)"}, {"bn": "আল্লাহর কাছে সবচেয়ে প্রিয় আমল — সময়মতো নামাজ পড়া। (সহিহ বুখারি ৫২৭)", "en": "The deed most beloved to Allah is prayer at its proper time. (Sahih al-Bukhari 527)"}, {"bn": "মানুষ এবং শিরক-কুফরের মাঝে পার্থক্য হলো নামাজ ছেড়ে দেওয়া। (সহিহ মুসলিম ৮২)", "en": "Between a man and shirk and disbelief is abandoning the prayer. (Sahih Muslim 82)"}]}, {"type": "heading", "text": {"bn": "খুশু: মনোযোগ ও বিনয়", "en": "Khushu: focus and humility"}}, {"type": "arabic", "ar": "قَدْ أَفْلَحَ الْمُؤْمِنُونَ ﴿١﴾ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ ﴿٢﴾", "pron": {"bn": "কাদ আফলাহাল মু''মিনুন। আল্লাযিনা হুম ফি সালাতিহিম খাশিউন।", "en": "Qad aflahal-mu''minun. Alladhina hum fi salatihim khashi''un."}, "meaning": {"bn": "নিশ্চয়ই সফল হয়েছে মুমিনরা, যারা নিজেদের নামাজে বিনয়ী ও মনোযোগী।", "en": "Successful indeed are the believers, those who are humble and focused in their prayer."}, "ref": {"bn": "সূরা মুমিনুন ২৩:১–২", "en": "Al-Mu''minun 23:1–2"}}, {"type": "text", "text": {"bn": "নামাজে কী পড়ছেন তার অর্থ জানলে মনোযোগ অনেক বাড়ে। তাই এই গাইডের প্রতিটি দোয়া ও সূরার সাথে অর্থ দেওয়া আছে। রাসুলুল্লাহ ﷺ বলেছেন: \"তোমরা আমাকে যেভাবে নামাজ পড়তে দেখেছ, সেভাবে নামাজ পড়ো।\"", "en": "Knowing the meaning of what you recite greatly helps focus, so every dua and surah in these guides comes with its meaning. The Prophet ﷺ said: \"Pray as you have seen me praying.\""}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৩১", "en": "Sahih al-Bukhari 631"}}, {"type": "heading", "text": {"bn": "ছুটে যাওয়া নামাজ ও সন্তানদের শেখানো", "en": "Missed prayers and teaching children"}}, {"type": "list", "items": [{"bn": "ঘুম বা ভুলে যাওয়ার কারণে নামাজ ছুটে গেলে মনে পড়ামাত্র তা আদায় (কাজা) করতে হবে। (সহিহ বুখারি ৫৯৭; সহিহ মুসলিম ৬৮৪)", "en": "A prayer missed through sleep or forgetfulness is prayed (made up) as soon as it is remembered. (Sahih al-Bukhari 597; Sahih Muslim 684)"}, {"bn": "সন্তানের বয়স সাত হলে নামাজের আদেশ দাও, দশ বছরে নামাজের জন্য শাসন করো। (সুনান আবু দাউদ ৪৯৫)", "en": "Command your children to pray at seven, and discipline them for it at ten. (Sunan Abi Dawud 495)"}]}, {"type": "note", "tone": "tip", "text": {"bn": "নামাজ ছেড়ে দিয়ে থাকলে হতাশ হবেন না — আজই তওবা করে পরের ওয়াক্ত থেকে শুরু করুন। ছুটে যাওয়া ফরজ নামাজের কাজা কীভাবে করবেন, তা একজন আলেমের সাথে পরামর্শ করে ঠিক করে নিন।", "en": "If you have left prayer, do not despair: repent today and start from the next prayer. Ask a scholar how to plan making up missed obligatory prayers."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '43c0925a-b591-5194-8f7f-70d0c076b367', id, 'salah-times-rakats', '{"bn": "পাঁচ ওয়াক্ত নামাজ: রাকাত সংখ্যা ও সময়", "en": "The Five Prayers: Rakats and Times"}', '{"bn": "কোন নামাজে কত রাকাত ফরজ, সুন্নত, বিতর ও নফল; প্রতিটি নামাজের শুরু-শেষের সময় এবং নিষিদ্ধ সময়।", "en": "How many fard, sunnah, witr and nafl rakats each prayer has; when each prayer begins and ends; and the forbidden times."}', 'basic', '[{"type": "heading", "text": {"bn": "রাকাত সংখ্যার তালিকা", "en": "Table of rakats"}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "ফরজ", "en": "Fard"}, {"bn": "সুন্নতে মুয়াক্কাদা", "en": "Sunnah muakkadah"}, {"bn": "সুন্নতে গায়রে মুয়াক্কাদা", "en": "Sunnah ghair muakkadah"}, {"bn": "বিতর", "en": "Witr"}, {"bn": "নফল (ঐচ্ছিক)", "en": "Nafl (optional)"}], "rows": [[{"bn": "ফজর", "en": "Fajr"}, {"bn": "২", "en": "2"}, {"bn": "২ (ফরজের আগে)", "en": "2 (before fard)"}, {"bn": "—", "en": "—"}, {"bn": "—", "en": "—"}, {"bn": "—", "en": "—"}], [{"bn": "জোহর", "en": "Zuhr"}, {"bn": "৪", "en": "4"}, {"bn": "৪ (আগে) + ২ (পরে)", "en": "4 (before) + 2 (after)"}, {"bn": "—", "en": "—"}, {"bn": "—", "en": "—"}, {"bn": "২ (পরে)", "en": "2 (after)"}], [{"bn": "আসর", "en": "Asr"}, {"bn": "৪", "en": "4"}, {"bn": "—", "en": "—"}, {"bn": "৪ (আগে)", "en": "4 (before)"}, {"bn": "—", "en": "—"}, {"bn": "—", "en": "—"}], [{"bn": "মাগরিব", "en": "Maghrib"}, {"bn": "৩", "en": "3"}, {"bn": "২ (পরে)", "en": "2 (after)"}, {"bn": "—", "en": "—"}, {"bn": "—", "en": "—"}, {"bn": "২ (পরে)", "en": "2 (after)"}], [{"bn": "এশা", "en": "Isha"}, {"bn": "৪", "en": "4"}, {"bn": "২ (পরে)", "en": "2 (after)"}, {"bn": "৪ (আগে)", "en": "4 (before)"}, {"bn": "৩ (এশার পর)", "en": "3 (after Isha)"}, {"bn": "২ (সুন্নতের পর) + ২ (বিতরের পর)", "en": "2 (after sunnah) + 2 (after witr)"}]]}, {"type": "note", "tone": "info", "text": {"bn": "ফরজ মোট ১৭ রাকাত — এতে সব মাযহাব একমত। সুন্নতের হিসাব উপরে বাংলাদেশে প্রচলিত হানাফি মত অনুযায়ী। শাফেয়ি ও হাম্বলি মতে জোহরের আগে নিয়মিত সুন্নত ২ রাকাত (ইবনে উমর রা.-এর বর্ণনা, সহিহ বুখারি ১১৮০), যদিও ৪ রাকাতও প্রমাণিত (সহিহ বুখারি ১১৮২)। বিতর নামাজের বিস্তারিত নিয়ম ও দোয়া কুনুত \"বিশেষ নামাজ\" বিভাগে দেওয়া আছে।", "en": "The fard total of 17 rakats is agreed by all. The sunnah counts above follow the Hanafi practice common in Bangladesh. Shafi''is and Hanbalis count 2 regular rakats before Zuhr (Ibn Umar''s report, Sahih al-Bukhari 1180), though 4 is also established (Sahih al-Bukhari 1182). The full method of witr and the dua qunut are in the Special Prayers section."}}, {"type": "text", "text": {"bn": "সুন্নতে মুয়াক্কাদা হলো সেই সুন্নত যা রাসুলুল্লাহ ﷺ নিয়মিত পড়তেন এবং খুব কমই ছেড়েছেন; বিনা কারণে নিয়মিত ছেড়ে দেওয়া উচিত নয়। গায়রে মুয়াক্কাদা পড়লে সওয়াব, না পড়লে গুনাহ নেই। রাসুলুল্লাহ ﷺ বলেছেন, যে দিনে-রাতে ১২ রাকাত (সুন্নত) পড়ে, তার জন্য জান্নাতে একটি ঘর তৈরি করা হয়।", "en": "Sunnah muakkadah are the sunnahs the Prophet ﷺ prayed regularly and rarely left; they should not be habitually skipped without reason. Ghair muakkadah earn reward if prayed, with no sin if left. The Prophet ﷺ said that whoever prays twelve (sunnah) rakats in a day and night, a house is built for him in Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৭২৮; বিস্তারিত তালিকা: সুনান তিরমিযি", "en": "Sahih Muslim 728; the detailed list: Jami at-Tirmidhi"}, "check": true}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৭২৫ — \"ফজরের দুই রাকাত (সুন্নত) দুনিয়া ও তার সবকিছুর চেয়ে উত্তম\"", "en": "Sahih Muslim 725: \"The two rakats of Fajr are better than the world and all it contains\""}}, {"type": "note", "tone": "info", "text": {"bn": "জুমার দিন জোহরের বদলে দুই রাকাত জুমার ফরজ নামাজ পড়া হয়। জুমার আগে-পরের সুন্নতের বিস্তারিত \"বিশেষ নামাজ\" বিভাগে দেওয়া আছে।", "en": "On Friday, two rakats of Jumu''ah replace Zuhr. The sunnahs before and after Jumu''ah are covered in the Special Prayers section."}}, {"type": "heading", "text": {"bn": "নামাজের সময়", "en": "Prayer times"}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "শুরু", "en": "Begins"}, {"bn": "শেষ", "en": "Ends"}], "rows": [[{"bn": "ফজর", "en": "Fajr"}, {"bn": "সুবহে সাদিক — পূর্ব আকাশে সাদা আলো আড়াআড়িভাবে ছড়িয়ে পড়া", "en": "True dawn: when white light spreads across the eastern horizon"}, {"bn": "সূর্যোদয় শুরু হওয়া পর্যন্ত", "en": "Until sunrise begins"}], [{"bn": "জোহর", "en": "Zuhr"}, {"bn": "সূর্য মাথার উপর থেকে পশ্চিমে হেলে পড়ার পর (জাওয়াল)", "en": "Once the sun passes its zenith and begins to decline"}, {"bn": "আসরের সময় শুরু হওয়া পর্যন্ত (নিচের মতপার্থক্য দেখুন)", "en": "Until Asr begins (see the difference below)"}], [{"bn": "আসর", "en": "Asr"}, {"bn": "জোহরের সময় শেষ হলে", "en": "When Zuhr time ends"}, {"bn": "সূর্যাস্ত পর্যন্ত; তবে সূর্য হলুদ হয়ে যাওয়া পর্যন্ত দেরি করা মাকরুহ", "en": "Until sunset, but delaying until the sun turns yellow is disliked"}], [{"bn": "মাগরিব", "en": "Maghrib"}, {"bn": "সূর্য পুরোপুরি অস্ত যাওয়ার পর", "en": "Right after the sun has fully set"}, {"bn": "পশ্চিম আকাশের লালিমা (শাফাক) মিলিয়ে যাওয়া পর্যন্ত", "en": "Until the twilight (shafaq) disappears from the western sky"}], [{"bn": "এশা", "en": "Isha"}, {"bn": "শাফাক মিলিয়ে যাওয়ার পর", "en": "After the twilight disappears"}, {"bn": "সুবহে সাদিক পর্যন্ত; তবে মধ্যরাতের আগে পড়ে নেওয়া উত্তম", "en": "Until true dawn, but it is best prayed before midnight"}]]}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৩৯৩; সুনান তিরমিযি ১৪৯ — জিবরাইল (আ.)-এর ইমামতি; সহিহ মুসলিম ৬১২ — নামাজের সময়সমূহ", "en": "Sunan Abi Dawud 393; Jami at-Tirmidhi 149: Jibril leading the prayers; Sahih Muslim 612: the prayer times"}}, {"type": "differ", "title": {"bn": "আসরের সময় কখন শুরু হয়?", "en": "When does Asr time begin?"}, "views": [{"label": {"bn": "অধিকাংশ আলেম (শাফেয়ি, মালেকি, হাম্বলি; হানাফি ইমাম আবু ইউসুফ ও মুহাম্মাদ)", "en": "Most scholars (Shafi''i, Maliki, Hanbali; the Hanafi imams Abu Yusuf and Muhammad)"}, "text": {"bn": "কোনো বস্তুর ছায়া (দুপুরের মূল ছায়া বাদ দিয়ে) যখন বস্তুর সমান হয়, তখন জোহর শেষ হয়ে আসর শুরু হয়।", "en": "Asr begins when an object''s shadow (beyond its noon shadow) equals its length."}, "evidence": {"bn": "জিবরাইল (আ.) প্রথম দিন ছায়া এক গুণ হলে আসর পড়িয়েছেন — সুনান আবু দাউদ ৩৯৩; সুনান তিরমিযি ১৪৯; সহিহ মুসলিম ৬১২।", "en": "Jibril led Asr on the first day when the shadow equalled the object (Sunan Abi Dawud 393; Jami at-Tirmidhi 149; Sahih Muslim 612)."}}, {"label": {"bn": "ইমাম আবু হানিফা (বাংলাদেশের প্রচলিত ক্যালেন্ডার সাধারণত এই মত অনুসরণ করে)", "en": "Imam Abu Hanifah (calendars in Bangladesh usually follow this)"}, "text": {"bn": "ছায়া বস্তুর দ্বিগুণ হলে আসর শুরু হয়; তাই হানাফি ক্যালেন্ডারে আসরের সময় কিছুটা দেরিতে।", "en": "Asr begins when the shadow is twice the object''s length, so Hanafi timetables show Asr somewhat later."}, "evidence": {"bn": "জিবরাইল (আ.) দ্বিতীয় দিন ছায়া এক গুণ হলে জোহর পড়িয়েছেন (একই হাদিস), অর্থাৎ তখনো জোহরের সময় ছিল; এবং গরম তীব্র হলে জোহর ঠান্ডা সময়ে পড়ার নির্দেশনা (সহিহ বুখারি)।", "en": "On the second day Jibril led Zuhr when the shadow equalled the object (the same hadith), so Zuhr time was still running then; and the instruction to delay Zuhr until it is cooler in intense heat (Sahih al-Bukhari)."}}], "check": true}, {"type": "heading", "text": {"bn": "নামাজ নিষিদ্ধ সময়", "en": "Forbidden times"}}, {"type": "list", "items": [{"bn": "সূর্যোদয়ের সময় — সূর্য পুরোপুরি উঠে কিছুটা উপরে না আসা পর্যন্ত (প্রায় ১৫–২০ মিনিট)", "en": "At sunrise, until the sun has fully risen and climbed a little (about 15–20 minutes)"}, {"bn": "ঠিক দুপুরে — সূর্য মাথার উপর থাকা অবস্থায়, পশ্চিমে হেলে পড়া পর্যন্ত", "en": "At midday, while the sun is at its zenith, until it declines"}, {"bn": "সূর্যাস্তের সময় — সূর্য হলুদ হয়ে অস্ত যাওয়া পর্যন্ত", "en": "At sunset, from when the sun turns yellow until it has set"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮৩১ (উকবা ইবনে আমির রা.)", "en": "Sahih Muslim 831 (Uqbah ibn ''Amir RA)"}}, {"type": "text", "text": {"bn": "এ ছাড়া ফজরের ফরজের পর থেকে সূর্যোদয় পর্যন্ত এবং আসরের ফরজের পর থেকে সূর্যাস্ত পর্যন্ত নফল নামাজ পড়া নিষেধ। হানাফি মতে উপরের তিন সময়ে কাজা নামাজও পড়া যাবে না; তবে কেউ সেদিনের আসর এত দেরিতে পড়লে সূর্যাস্তের সময়ও শেষ করে নেবে (দেরি করার কারণে গুনাহ হবে)।", "en": "Also, voluntary prayer is not prayed after the Fajr fard until sunrise, nor after the Asr fard until sunset. In the Hanafi view not even missed prayers are made up in the three times above, except that a person who delayed that day''s Asr completes it even at sunset (though the delay is sinful)."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৮৬; সহিহ মুসলিম ৮২৭", "en": "Sahih al-Bukhari 586; Sahih Muslim 827"}}, {"type": "note", "tone": "tip", "text": {"bn": "নিজ এলাকার নির্ভরযোগ্য নামাজের ক্যালেন্ডার বা এই অ্যাপের সময়সূচি দেখে নামাজ পড়ুন। সময় শুরু হওয়ার আগে নামাজ পড়লে তা হয় না।", "en": "Follow a reliable local prayer timetable, or the times in this app. A prayer offered before its time has begun is not valid."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5a0b8f1a-a5ca-5520-bb82-3e1b3f23dcc8', id, 'salah-fard-wajib', '{"bn": "নামাজের ফরজ ও ওয়াজিব", "en": "Salah: Conditions, Pillars and Wajib Acts"}', '{"bn": "নামাজের বাইরের ও ভেতরের ফরজ এবং ওয়াজিবগুলো — কোনটি ছুটলে নামাজ হয় না, কোনটি ছুটলে সাহু সিজদা লাগে।", "en": "The conditions and pillars of salah, and its wajib acts: which ones invalidate the prayer if missed, and which call for sajdah sahw."}', 'basic', '[{"type": "text", "text": {"bn": "বাংলাদেশে প্রচলিত হানাফি কিতাবগুলোতে নামাজের ফরজ ১৩টি বলা হয়: ৭টি নামাজের বাইরে (আহকাম বা শর্ত) এবং ৬টি নামাজের ভেতরে (আরকান)। এর কোনো একটি বাদ পড়লে — ইচ্ছায় হোক বা ভুলে — নামাজ হয় না, আবার পড়তে হয়।", "en": "Hanafi books used in Bangladesh list 13 fard acts: 7 outside the prayer (conditions) and 6 inside it (pillars). If any is missed, deliberately or by mistake, the prayer is invalid and must be repeated."}}, {"type": "heading", "text": {"bn": "নামাজের বাইরের ফরজ (শর্ত) — ৭টি", "en": "Conditions (outside the prayer): seven"}}, {"type": "table", "head": [{"bn": "শর্ত", "en": "Condition"}, {"bn": "ব্যাখ্যা", "en": "Explanation"}, {"bn": "দলিল", "en": "Evidence"}], "rows": [[{"bn": "শরীর পবিত্র", "en": "Body pure"}, {"bn": "ওযু থাকা, প্রয়োজনে গোসল; শরীরে নাপাকি না থাকা", "en": "Having wudu (and ghusl if needed); no impurity on the body"}, {"bn": "সূরা মায়েদা ৫:৬; সহিহ বুখারি ১৩৫", "en": "Al-Ma''idah 5:6; Sahih al-Bukhari 135"}], [{"bn": "কাপড় পবিত্র", "en": "Clothes pure"}, {"bn": "পরনের কাপড়ে নাপাকি না থাকা", "en": "No impurity on what one wears"}, {"bn": "সূরা মুদ্দাসসির ৭৪:৪", "en": "Al-Muddaththir 74:4"}], [{"bn": "জায়গা পবিত্র", "en": "Place pure"}, {"bn": "দাঁড়ানো, হাঁটু, হাত ও সিজদার জায়গা পবিত্র হওয়া", "en": "Where one stands, kneels, places the hands and prostrates must be pure"}, {"bn": "সূরা বাকারা ২:১২৫ (ঘর পবিত্র রাখার আদেশ)", "en": "Al-Baqarah 2:125 (purify My House)"}], [{"bn": "সতর ঢাকা", "en": "Covering the awrah"}, {"bn": "পুরুষ: নাভি থেকে হাঁটুসহ; নারী: মুখমণ্ডল, দুই হাতের কবজি পর্যন্ত (এবং হানাফি মতে দুই পা) ছাড়া পুরো শরীর", "en": "Men: from navel to knees inclusive; women: the whole body except the face, the hands (and in the Hanafi view the feet)"}, {"bn": "সূরা আরাফ ৭:৩১; সুনান আবু দাউদ ৬৪১", "en": "Al-A''raf 7:31; Sunan Abi Dawud 641"}], [{"bn": "কিবলামুখী হওয়া", "en": "Facing the qiblah"}, {"bn": "কাবার দিকে মুখ করা", "en": "Facing towards the Ka''bah"}, {"bn": "সূরা বাকারা ২:১৪৪", "en": "Al-Baqarah 2:144"}], [{"bn": "ওয়াক্ত হওয়া", "en": "The time having begun"}, {"bn": "নামাজের সময় শুরু হওয়া", "en": "The prayer''s time must have started"}, {"bn": "সূরা নিসা ৪:১০৩", "en": "An-Nisa 4:103"}], [{"bn": "নিয়ত করা", "en": "Intention"}, {"bn": "অন্তরে কোন নামাজ পড়ছেন তা ঠিক করা", "en": "Knowing in the heart which prayer one is offering"}, {"bn": "সহিহ বুখারি ১; সহিহ মুসলিম ১৯০৭", "en": "Sahih al-Bukhari 1; Sahih Muslim 1907"}]]}, {"type": "heading", "text": {"bn": "নামাজের ভেতরের ফরজ (আরকান) — ৬টি", "en": "Pillars (inside the prayer): six"}}, {"type": "list", "items": [{"bn": "তাকবিরে তাহরিমা — \"আল্লাহু আকবার\" বলে নামাজ শুরু করা", "en": "Takbir at-tahrimah: beginning with \"Allahu akbar\""}, {"bn": "কিয়াম — দাঁড়িয়ে নামাজ পড়া (ফরজ ও ওয়াজিব নামাজে, সামর্থ্য থাকলে)", "en": "Qiyam: standing (in fard and wajib prayers, if able)"}, {"bn": "কিরাত — কুরআন থেকে কিছু পড়া", "en": "Qira''ah: reciting from the Quran"}, {"bn": "রুকু করা", "en": "Ruku: bowing"}, {"bn": "প্রতি রাকাতে দুটি সিজদা করা", "en": "Sujud: two prostrations in every rakat"}, {"bn": "শেষ বৈঠক — তাশাহহুদ পড়ার পরিমাণ সময় বসা", "en": "The final sitting, for as long as it takes to recite the tashahhud"}]}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৬১; সুনান তিরমিযি ৩ — \"নামাজের চাবি পবিত্রতা, তার শুরু তাকবির আর শেষ সালাম\"; সহিহ বুখারি ৭৫৭; সহিহ মুসলিম ৩৯৭ — ভুলভাবে নামাজ আদায়কারী সাহাবিকে শেখানোর হাদিস", "en": "Sunan Abi Dawud 61; Jami at-Tirmidhi 3: \"The key to prayer is purification, it begins with takbir and ends with salam\"; Sahih al-Bukhari 757; Sahih Muslim 397: the hadith of the man taught to pray properly"}}, {"type": "note", "tone": "info", "text": {"bn": "হানাফি কিতাবে আরেকটি বিষয়কে ফরজ ধরা হয়: নিজের কোনো কাজের মাধ্যমে নামাজ থেকে বের হওয়া — যা সাধারণত সালামের মাধ্যমে হয়। কিছু কিতাবে তাকবিরে তাহরিমাকে বাইরের শর্তের মধ্যেও গণনা করা হয়।", "en": "Hanafi books also count leaving the prayer by one''s own act (normally the salam) as fard. Some count the opening takbir among the conditions rather than the pillars."}}, {"type": "differ", "title": {"bn": "সূরা ফাতিহা, ধীরস্থিরতা ও সালাম কি রুকন (ফরজ), নাকি ওয়াজিব?", "en": "Are Al-Fatihah, calmness and the salam pillars, or wajib?"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "কুরআন থেকে যেকোনো অংশ পড়া ফরজ; সূরা ফাতিহা, রুকু-সিজদায় ধীরস্থিরতা (তাদিলে আরকান) এবং \"সালাম\" শব্দে শেষ করা ওয়াজিব। ভুলে ছুটলে সাহু সিজদা, ইচ্ছাকৃত ছাড়লে নামাজ আবার পড়া জরুরি।", "en": "Reciting any part of the Quran is fard; Al-Fatihah, calmness in ruku and sujud, and ending with the word \"salam\" are wajib. Missed by mistake, sajdah sahw makes up for them; left deliberately, the prayer must be repeated."}, "evidence": {"bn": "\"কুরআন থেকে যতটুকু সহজ হয় পড়ো\" — সূরা মুযযাম্মিল ৭৩:২০; ভুলভাবে নামাজ আদায়কারীকে রাসুলুল্লাহ ﷺ বলেছেন, \"কুরআন থেকে যা সহজ তা পড়ো\" — সহিহ বুখারি ৭৫৭।", "en": "\"Recite what is easy of the Quran\" (Al-Muzzammil 73:20); the Prophet ﷺ told the man who prayed badly, \"recite what is easy for you of the Quran\" (Sahih al-Bukhari 757)."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki and Hanbali"}, "text": {"bn": "সূরা ফাতিহা, প্রতিটি রুকনে ধীরস্থিরতা এবং সালাম — সবই রুকন। এর কোনোটি ছুটলে নামাজ হবে না। শাফেয়ি ও হাম্বলি মতে শেষ বৈঠকে তাশাহহুদ ও দরুদও রুকন।", "en": "Al-Fatihah, calmness in every pillar and the salam are all pillars; without them the prayer is invalid. Shafi''is and Hanbalis also count the final tashahhud and durood as pillars."}, "evidence": {"bn": "\"যে সূরা ফাতিহা পড়ে না তার নামাজ হয় না\" — সহিহ বুখারি ৭৫৬; সহিহ মুসলিম ৩৯৪; ভুলভাবে নামাজ আদায়কারীকে \"তুমি নামাজ পড়োনি\" বলে প্রতিটি রুকনে স্থির হতে বলেছেন — সহিহ বুখারি ৭৫৭।", "en": "\"There is no prayer for one who does not recite Al-Fatihah\" (Sahih al-Bukhari 756; Sahih Muslim 394); the man who prayed badly was told \"you have not prayed\" and taught to be at rest in each pillar (Sahih al-Bukhari 757)."}}]}, {"type": "heading", "text": {"bn": "নামাজের ওয়াজিব (হানাফি মাযহাব অনুযায়ী ১৪টি)", "en": "Wajib acts of salah (14, in the Hanafi madhhab)"}}, {"type": "list", "items": [{"bn": "সূরা ফাতিহা পূর্ণ পড়া", "en": "Reciting Al-Fatihah completely"}, {"bn": "ফাতিহার পর আরেকটি সূরা বা কমপক্ষে ছোট তিন আয়াত পরিমাণ পড়া — ফরজের প্রথম দুই রাকাতে এবং সুন্নত, নফল ও বিতরের সব রাকাতে", "en": "Adding a surah or at least three short ayat after Al-Fatihah: in the first two rakats of fard prayers and in every rakat of sunnah, nafl and witr"}, {"bn": "ফরজ নামাজের প্রথম দুই রাকাতকে কিরাতের জন্য নির্দিষ্ট করা", "en": "Making the first two rakats of fard prayers the ones with recitation"}, {"bn": "সূরা মিলানোর আগে ফাতিহা পড়া", "en": "Reciting Al-Fatihah before the added surah"}, {"bn": "রুকু, সিজদা, রুকুর পর দাঁড়ানো এবং দুই সিজদার মাঝে বসায় ধীরস্থিরতা (তাদিলে আরকান)", "en": "Calmness in ruku, sujud, standing after ruku and sitting between the sujud"}, {"bn": "প্রতিটি কাজ সঠিক ক্রমে করা", "en": "Keeping the correct order of the acts"}, {"bn": "তিন ও চার রাকাতের নামাজে প্রথম বৈঠক", "en": "The first sitting in three- and four-rakat prayers"}, {"bn": "দুই বৈঠকেই তাশাহহুদ (আত্তাহিয়্যাতু) পড়া", "en": "Reciting the tashahhud in both sittings"}, {"bn": "\"আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ\" বলে নামাজ শেষ করা", "en": "Ending the prayer with \"As-salamu ''alaykum wa rahmatullah\""}, {"bn": "ইমামের জন্য ফজর, মাগরিব ও এশার প্রথম দুই রাকাতে উচ্চস্বরে এবং জোহর-আসরে নিচু স্বরে কিরাত", "en": "For the imam: reciting aloud in Fajr and the first two rakats of Maghrib and Isha, and quietly in Zuhr and Asr"}, {"bn": "বিতরে দোয়া কুনুত পড়া", "en": "Reciting the qunut in witr"}, {"bn": "দুই ঈদের নামাজে অতিরিক্ত ছয় তাকবির", "en": "The six extra takbirs of the two Eid prayers"}, {"bn": "সিজদার আয়াত পড়লে সিজদায়ে তিলাওয়াত করা", "en": "Prostrating when an ayah of sajdah is recited"}, {"bn": "ইমামের অনুসরণ করা (মুক্তাদির জন্য)", "en": "Following the imam (for those praying behind him)"}]}, {"type": "note", "tone": "warn", "text": {"bn": "কোনো ওয়াজিব ভুলে ছুটে গেলে নামাজের শেষে সাহু সিজদা দিলে নামাজ পূর্ণ হয়। ইচ্ছাকৃতভাবে ছাড়লে বা সাহু সিজদা না দিলে নামাজটি আবার পড়া জরুরি। ফরজ (রুকন) ছুটে গেলে সাহু সিজদায় কাজ হয় না — নামাজ আবার পড়তে হবে।", "en": "If a wajib is missed by mistake, sajdah sahw at the end completes the prayer. If it is left deliberately, or sahw is not done, the prayer must be repeated. If a pillar (fard) is missed, sajdah sahw does not help: the prayer must be repeated."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'a2cb4792-5425-5429-bd5a-18a41aa84685', id, 'salah-sunnah-makruh-mufsidat', '{"bn": "নামাজের সুন্নত, মাকরুহ ও যেসব কারণে নামাজ ভাঙে", "en": "Salah: Sunnah Acts, Disliked Acts and What Breaks It"}', '{"bn": "নামাজকে সুন্দর করে যেসব সুন্নত, যেসব কাজ নামাজকে ত্রুটিপূর্ণ করে, আর যেসব কারণে নামাজ ভেঙে যায়।", "en": "The sunnah acts that beautify salah, the acts that spoil it, and the things that break it."}', 'detail', '[{"type": "heading", "text": {"bn": "নামাজের গুরুত্বপূর্ণ সুন্নত", "en": "Important sunnah acts"}}, {"type": "list", "items": [{"bn": "তাকবিরে তাহরিমার সময় দুই হাত ওঠানো", "en": "Raising the hands at the opening takbir"}, {"bn": "ডান হাত বাম হাতের উপর রেখে হাত বাঁধা", "en": "Placing the right hand over the left"}, {"bn": "সানা, তাআউয ও বিসমিল্লাহ পড়া", "en": "Reciting the thana, ta''awwudh and Bismillah"}, {"bn": "সূরা ফাতিহার পর আমিন বলা", "en": "Saying Amin after Al-Fatihah"}, {"bn": "এক অবস্থা থেকে আরেক অবস্থায় যাওয়ার সময় তাকবির বলা", "en": "Saying the takbir when moving from one position to another"}, {"bn": "রুকু ও সিজদায় কমপক্ষে তিনবার তাসবিহ পড়া", "en": "Saying the tasbih at least three times in ruku and sujud"}, {"bn": "রুকু থেকে ওঠার সময় তাসমি ও দাঁড়িয়ে তাহমিদ বলা", "en": "Saying the tasmi'' while rising from ruku and the tahmid when standing"}, {"bn": "রুকুতে হাঁটু ধরা, পিঠ ও মাথা সমান রাখা", "en": "Holding the knees in ruku with the back and head level"}, {"bn": "সিজদায় যেতে প্রথমে হাঁটু, তারপর হাত, তারপর নাক ও কপাল রাখা (হানাফি মত)", "en": "Going down to sujud with knees first, then hands, then nose and forehead (Hanafi view)"}, {"bn": "শেষ বৈঠকে তাশাহহুদের পর দরুদ ও দোয়া পড়া", "en": "Reciting durood and a dua after the tashahhud in the final sitting"}, {"bn": "দাঁড়ানো অবস্থায় সিজদার জায়গার দিকে তাকানো", "en": "Looking at the place of prostration while standing"}, {"bn": "সালামের সময় ডানে ও বামে মুখ ফেরানো", "en": "Turning the face right and left at the salam"}]}, {"type": "note", "tone": "info", "text": {"bn": "সুন্নত ছুটে গেলে নামাজ ভাঙে না এবং সাহু সিজদাও লাগে না, তবে সওয়াব কমে যায়। হাত ওঠানো, হাত বাঁধা, আমিন ইত্যাদির পদ্ধতি নিয়ে মতপার্থক্য \"নামাজে মতপার্থক্যের বিষয়গুলো\" অংশে দেখুন।", "en": "Missing a sunnah does not break the prayer and does not need sajdah sahw, but reduces the reward. For differences on raising the hands, hand placement, Amin and so on, see \"Points of Difference in Salah\"."}}, {"type": "heading", "text": {"bn": "যেসব কারণে নামাজ ভেঙে যায় (মুফসিদাত)", "en": "What breaks the prayer (mufsidat)"}}, {"type": "list", "items": [{"bn": "কথা বলা — মানুষের সাথে কথাবার্তা নামাজে চলে না (হানাফি মতে ভুলে বললেও ভাঙে; অন্যদের মতে ভুলে বা না জেনে অল্প কথায় ভাঙে না)", "en": "Speaking: ordinary talk has no place in salah (Hanafis say it breaks even if by mistake; others excuse a little said by mistake or in ignorance)"}, {"bn": "কিছু খাওয়া বা পান করা", "en": "Eating or drinking anything"}, {"bn": "শব্দ করে হাসা (মুচকি হাসিতে নামাজ ভাঙে না)", "en": "Laughing aloud (a silent smile does not break it)"}, {"bn": "ওযু ভেঙে যাওয়া", "en": "Wudu breaking"}, {"bn": "বিনা কারণে বুক কিবলা থেকে ঘুরিয়ে ফেলা", "en": "Turning the chest away from the qiblah without excuse"}, {"bn": "আমলে কাসির — এত বেশি নড়াচড়া যে দেখলে মনে হয় সে নামাজে নেই", "en": "Excessive movement: so much that an onlooker would think one is not praying"}, {"bn": "কোনো রুকন (ফরজ) ছেড়ে দেওয়া", "en": "Leaving out a pillar (fard)"}, {"bn": "সতর এতক্ষণ খোলা থাকা যতক্ষণে একটি রুকন আদায় করা যায় (হানাফি মতে কোনো অঙ্গের এক-চতুর্থাংশ)", "en": "The awrah staying uncovered for as long as a pillar takes (Hanafi: a quarter of a limb)"}, {"bn": "কুরআন এমন ভুল পড়া যাতে অর্থ সম্পূর্ণ বদলে যায়", "en": "A recitation mistake that totally changes the meaning"}, {"bn": "কথায় সালামের জবাব দেওয়া বা হাঁচির জবাবে \"ইয়ারহামুকাল্লাহ\" বলা", "en": "Returning a greeting in words, or saying \"yarhamukallah\" to someone who sneezes"}, {"bn": "ব্যথা বা দুনিয়াবি দুঃখে শব্দ করে \"আহ-উহ\" করা বা কাঁদা (হানাফি মত); আল্লাহর ভয়ে কাঁদলে নামাজ ভাঙে না", "en": "Groaning or crying aloud from pain or worldly grief (Hanafi view); weeping from fear of Allah does not break it"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৫৩৭ — \"এই নামাজে মানুষের কথাবার্তার কিছুই চলে না; এটা তো শুধু তাসবিহ, তাকবির ও কুরআন তিলাওয়াত\"", "en": "Sahih Muslim 537: \"Nothing of people''s talk is fitting in this prayer; it is only glorification, takbir and recitation of the Quran\""}}, {"type": "heading", "text": {"bn": "নামাজে যা মাকরুহ", "en": "What is disliked (makruh) in salah"}}, {"type": "list", "items": [{"bn": "এদিক-ওদিক তাকানো (সহিহ বুখারি ৭৫১) বা আকাশের দিকে তাকানো (সহিহ বুখারি ৭৫০)", "en": "Looking around (Sahih al-Bukhari 751) or looking up at the sky (Sahih al-Bukhari 750)"}, {"bn": "কাপড়, দাড়ি বা শরীর নিয়ে খেলা করা; আঙুল ফোটানো", "en": "Fiddling with clothes, beard or body; cracking the knuckles"}, {"bn": "কোমরে হাত রাখা (সহিহ বুখারি ১২২০)", "en": "Putting the hands on the hips (Sahih al-Bukhari 1220)"}, {"bn": "খাবার সামনে রেখে বা পেশাব-পায়খানার বেগ চেপে নামাজ পড়া (সহিহ মুসলিম ৫৬০)", "en": "Praying with food served and desired, or while holding back the call of nature (Sahih Muslim 560)"}, {"bn": "কাপড় বা চুল গুটিয়ে রাখা, যেমন হাতা গুটানো (সহিহ মুসলিম ৪৯০)", "en": "Tucking up clothes or hair, such as rolled-up sleeves (Sahih Muslim 490)"}, {"bn": "পুরুষদের সিজদায় কুকুরের মতো হাতের কনুই মাটিতে বিছিয়ে দেওয়া (সহিহ বুখারি ৮২২)", "en": "Men spreading the forearms flat on the ground in sujud like a dog (Sahih al-Bukhari 822)"}, {"bn": "রুকু বা সিজদায় কুরআন তিলাওয়াত করা (সহিহ মুসলিম ৪৭৯)", "en": "Reciting the Quran in ruku or sujud (Sahih Muslim 479)"}, {"bn": "হাই আসলে না আটকানো — যথাসম্ভব আটকাবে, না পারলে মুখে হাত রাখবে (সহিহ মুসলিম ২৯৯৫)", "en": "Not holding back a yawn: restrain it, or cover the mouth (Sahih Muslim 2995)"}, {"bn": "বিনা প্রয়োজনে চোখ বন্ধ রাখা", "en": "Closing the eyes without need"}, {"bn": "প্রাণীর ছবির দিকে মুখ করে বা কারো মুখোমুখি হয়ে নামাজ পড়া", "en": "Praying facing a picture of a living being, or facing someone''s face"}, {"bn": "তাড়াহুড়া করে রুকু-সিজদা করা, ধীরস্থির না হওয়া", "en": "Rushing ruku and sujud without becoming still"}]}, {"type": "note", "tone": "tip", "text": {"bn": "নামাজের সময় মোবাইল সাইলেন্ট রাখুন। নামাজে অনিচ্ছায় মোবাইল বেজে উঠলে এক হাতে অল্প নড়াচড়ায় বন্ধ করা যায়; এতে নামাজ ভাঙে না।", "en": "Silence your phone before praying. If it rings, you may switch it off with a small movement of one hand; this does not break the prayer."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '308f1c0b-ede4-5d0a-a0da-7cd89d06c1ff', id, 'salah-niyyah', '{"bn": "নামাজের নিয়ত", "en": "The Intention (Niyyah) for Salah"}', '{"bn": "নিয়ত হলো অন্তরের সংকল্প — মুখে বলা জরুরি নয়। প্রতিটি নামাজের জন্য প্রচলিত বাংলা নিয়তের উদাহরণসহ।", "en": "Niyyah is the resolve of the heart; saying it aloud is not required. With common Bangla phrasings for each prayer as examples."}', 'basic', '[{"type": "text", "text": {"bn": "নিয়ত মানে মনে মনে জানা ও ঠিক করা যে আমি আল্লাহর জন্য অমুক নামাজ পড়ছি। এটি অন্তরের কাজ। নামাজে দাঁড়িয়ে আপনি যদি জানেন যে এখন জোহরের চার রাকাত ফরজ পড়ছেন, তাহলেই নিয়ত হয়ে গেছে — আলাদা কোনো শব্দ মুখে উচ্চারণ করা জরুরি নয়।", "en": "Niyyah means knowing and deciding in your mind that you are offering a particular prayer for Allah. It is an act of the heart. If, as you stand, you know you are praying the four fard rakats of Zuhr, your intention is made; no words need be spoken."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১; সহিহ মুসলিম ১৯০৭ — \"সকল কাজ নিয়তের উপর নির্ভরশীল\"", "en": "Sahih al-Bukhari 1; Sahih Muslim 1907: \"Actions are only by intentions\""}}, {"type": "heading", "text": {"bn": "নিয়তে কী খেয়াল রাখবেন", "en": "What the intention should include"}}, {"type": "list", "items": [{"bn": "ফরজ ও ওয়াজিব নামাজে কোন নামাজ (যেমন আজকের আসরের ফরজ) তা নির্দিষ্ট করা", "en": "For fard and wajib prayers, which prayer it is (e.g. today''s Asr fard)"}, {"bn": "জামাতে পড়লে ইমামের অনুসরণের নিয়ত করা (হানাফি মতে জরুরি)", "en": "In congregation, intending to follow the imam (required in the Hanafi view)"}, {"bn": "সুন্নত ও নফলে সাধারণভাবে নামাজের নিয়তই যথেষ্ট", "en": "For sunnah and nafl, a general intention to pray is enough"}, {"bn": "নিয়ত তাকবিরে তাহরিমার সাথে বা ঠিক আগে হওয়া", "en": "The intention is made with, or just before, the opening takbir"}]}, {"type": "differ", "title": {"bn": "নিয়ত মুখে উচ্চারণ করা", "en": "Saying the intention aloud"}, "views": [{"label": {"bn": "অনেক আলেম (মালেকি মাযহাবসহ)", "en": "Many scholars (including the Maliki school)"}, "text": {"bn": "মুখে নিয়ত বলা রাসুলুল্লাহ ﷺ বা সাহাবিদের থেকে প্রমাণিত নয়; অন্তরের নিয়তই যথেষ্ট, তাই মুখে না বলাই উত্তম।", "en": "Saying the intention aloud is not reported from the Prophet ﷺ or the Companions; the heart''s intention suffices, so it is better not to say it."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ নামাজ শুরু করতেন তাকবির দিয়ে — সুনান আবু দাউদ ৬১; তাঁর নামাজের বিস্তারিত বর্ণনায় মুখে নিয়তের উল্লেখ নেই।", "en": "The Prophet ﷺ began the prayer with the takbir (Sunan Abi Dawud 61); detailed descriptions of his prayer do not mention a spoken intention."}}, {"label": {"bn": "পরবর্তী যুগের কিছু হানাফি ও শাফেয়ি ফকিহ", "en": "Some later Hanafi and Shafi''i jurists"}, "text": {"bn": "অন্তরের নিয়তই আসল; তবে মনকে একাগ্র করতে সাহায্য করলে মুখে বলাকে তারা উত্তম (মুস্তাহসান) বলেছেন।", "en": "The heart''s intention is what counts, but they considered saying it good if it helps the mind focus."}, "evidence": {"bn": "অন্তর ও মুখ একসাথে হলে মনোযোগ দৃঢ় হয় — এটি তাদের ইজতিহাদ; উভয় পক্ষ একমত যে মুখে বলা জরুরি নয়।", "en": "Joining tongue and heart strengthens focus; this is their reasoning, and both sides agree it is not required."}}]}, {"type": "heading", "text": {"bn": "প্রচলিত বাংলা নিয়তের উদাহরণ", "en": "Common Bangla phrasings (examples)"}}, {"type": "note", "tone": "info", "text": {"bn": "নিচের বাক্যগুলো শুধু উদাহরণ — হুবহু এই শব্দ বলা জরুরি নয়। মনে মনে নামাজটি নির্দিষ্ট করাই যথেষ্ট। জামাতে হলে \"এই ইমামের পেছনে\" যোগ করুন।", "en": "The sentences below are only examples; there is no required wording. Knowing the prayer in your heart is enough. In congregation, add \"behind this imam\"."}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "উদাহরণ (বাংলা)", "en": "Example"}], "rows": [[{"bn": "ফজরের সুন্নত", "en": "Fajr sunnah"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে ফজরের দুই রাকাত সুন্নত নামাজ পড়ছি।", "en": "I am praying the two sunnah rakats of Fajr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "ফজরের ফরজ (জামাতে)", "en": "Fajr fard (in congregation)"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে এই ইমামের পেছনে ফজরের দুই রাকাত ফরজ নামাজ পড়ছি।", "en": "I am praying the two fard rakats of Fajr behind this imam, facing the qiblah, for the pleasure of Allah."}], [{"bn": "জোহরের আগের সুন্নত", "en": "Zuhr sunnah (before)"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে জোহরের চার রাকাত সুন্নত নামাজ পড়ছি।", "en": "I am praying the four sunnah rakats of Zuhr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "জোহরের ফরজ", "en": "Zuhr fard"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে জোহরের চার রাকাত ফরজ নামাজ পড়ছি।", "en": "I am praying the four fard rakats of Zuhr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "জোহরের পরের সুন্নত", "en": "Zuhr sunnah (after)"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে জোহরের দুই রাকাত সুন্নত নামাজ পড়ছি।", "en": "I am praying the two sunnah rakats after Zuhr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "আসরের ফরজ", "en": "Asr fard"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে আসরের চার রাকাত ফরজ নামাজ পড়ছি।", "en": "I am praying the four fard rakats of Asr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "মাগরিবের ফরজ", "en": "Maghrib fard"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে মাগরিবের তিন রাকাত ফরজ নামাজ পড়ছি।", "en": "I am praying the three fard rakats of Maghrib, facing the qiblah, for the pleasure of Allah."}], [{"bn": "এশার ফরজ", "en": "Isha fard"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে এশার চার রাকাত ফরজ নামাজ পড়ছি।", "en": "I am praying the four fard rakats of Isha, facing the qiblah, for the pleasure of Allah."}], [{"bn": "বিতর", "en": "Witr"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে তিন রাকাত বিতর নামাজ পড়ছি।", "en": "I am praying the three rakats of witr, facing the qiblah, for the pleasure of Allah."}], [{"bn": "কাজা নামাজ", "en": "A missed prayer"}, {"bn": "আমি আল্লাহর সন্তুষ্টির জন্য কিবলামুখী হয়ে গত (অমুক দিনের) জোহরের চার রাকাত ফরজ নামাজ কাজা পড়ছি।", "en": "I am making up the four fard rakats of the Zuhr of (that day), facing the qiblah, for the pleasure of Allah."}]]}, {"type": "note", "tone": "warn", "text": {"bn": "কিছু বইয়ে \"নাওয়াইতু আন উসাল্লিয়া…\" ধরনের আরবি নিয়ত দেওয়া থাকে। এগুলো রাসুলুল্লাহ ﷺ থেকে বর্ণিত নয়; মুখস্থ করা জরুরি নয়, আর না জানলেও নামাজের কোনো ক্ষতি নেই।", "en": "Some books give Arabic formulas such as \"Nawaytu an usalliya…\". These are not narrated from the Prophet ﷺ; memorising them is not required, and not knowing them does not harm the prayer."}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f3de3915-5321-55da-9f21-ef1ce8368250', id, 'salah-two-rakat-step-by-step', '{"bn": "দুই রাকাত নামাজ: ধাপে ধাপে", "en": "How to Pray Two Rakats: Step by Step"}', '{"bn": "তাকবির থেকে সালাম পর্যন্ত দুই রাকাত নামাজের পূর্ণ পদ্ধতি — প্রতিটি দোয়া ও তাসবিহ আরবি, উচ্চারণ ও অর্থসহ।", "en": "The full method of a two-rakat prayer from takbir to salam, with every recitation in Arabic, pronunciation and meaning."}', 'basic', '[{"type": "text", "text": {"bn": "ফজরের ফরজ, ফজরের সুন্নত, জোহর-মাগরিব-এশার পরের সুন্নত এবং যেকোনো দুই রাকাত নফল — সব এভাবেই পড়া হয়। এখানে বাংলাদেশে প্রচলিত হানাফি পদ্ধতি অনুসরণ করা হয়েছে। হাত ওঠানো, হাত বাঁধার জায়গা, আমিন ইত্যাদি যেসব বিষয়ে অন্য মাযহাবে ভিন্নতা আছে, সেগুলো দলিলসহ \"নামাজে মতপার্থক্যের বিষয়গুলো\" অংশে দেওয়া আছে।", "en": "The Fajr fard, the Fajr sunnah, the sunnahs after Zuhr, Maghrib and Isha, and any two-rakat nafl are all prayed this way. The Hanafi method common in Bangladesh is followed here. Where other madhhabs differ (raising the hands, where to place them, Amin and so on), the views and evidence are in \"Points of Difference in Salah\"."}}, {"type": "note", "tone": "tip", "text": {"bn": "বাংলা ও ইংরেজি উচ্চারণ শুধু সাহায্যের জন্য; আরবির অনেক উচ্চারণ এতে পুরোপুরি ধরা যায় না। সূরা ফাতিহা ও অন্যান্য সূরার সঠিক উচ্চারণ একজন ভালো কারি বা শিক্ষকের কাছ থেকে শিখে নিন।", "en": "The Bangla and English transliterations are only aids; they cannot fully capture Arabic sounds. Learn the correct pronunciation of Al-Fatihah and other surahs from a good teacher."}}, {"type": "heading", "text": {"bn": "নামাজের আগে", "en": "Before the prayer"}}, {"type": "step", "title": {"bn": "প্রস্তুতি", "en": "Prepare"}, "text": {"bn": "ওযু করুন, শরীর-কাপড়-জায়গা পবিত্র কিনা দেখে নিন, সতর ঢাকুন, নামাজের ওয়াক্ত হয়েছে কিনা নিশ্চিত হোন এবং কিবলার দিকে মুখ করে দাঁড়ান। দুই পায়ের মাঝে স্বাভাবিক ফাঁক রাখুন।", "en": "Make wudu; make sure your body, clothes and place are pure; cover the awrah; check that the prayer time has started; and stand facing the qiblah with a natural gap between the feet."}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "মনে মনে ঠিক করুন কোন নামাজ পড়ছেন (যেমন ফজরের দুই রাকাত ফরজ)। মুখে বলা জরুরি নয়।", "en": "Know in your heart which prayer you are offering (e.g. the two fard rakats of Fajr). Saying it aloud is not required."}}, {"type": "heading", "text": {"bn": "প্রথম রাকাত", "en": "The first rakat"}}, {"type": "step", "title": {"bn": "তাকবিরে তাহরিমা", "en": "The opening takbir"}, "text": {"bn": "দুই হাত কান পর্যন্ত ওঠান — হাতের তালু কিবলার দিকে, বুড়ো আঙুল কানের লতির কাছাকাছি — এবং বলুন \"আল্লাহু আকবার\"। এখন থেকে নামাজের বাইরের সব কাজ ও কথা হারাম।", "en": "Raise both hands to the ears, palms facing the qiblah and thumbs near the earlobes, and say \"Allahu akbar\". From now, everything outside the prayer is forbidden."}}, {"type": "arabic", "label": {"bn": "তাকবিরে তাহরিমা", "en": "The opening takbir (takbir at-tahrimah)"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৯১ (কান পর্যন্ত হাত ওঠানো); সহিহ বুখারি ৭৩৫ (কাঁধ পর্যন্ত)", "en": "Sahih Muslim 391 (raising to the ears); Sahih al-Bukhari 735 (to the shoulders)"}}, {"type": "step", "title": {"bn": "হাত বাঁধা ও সানা", "en": "Fold the hands and recite the thana"}, "text": {"bn": "ডান হাতের তালু বাম হাতের কবজির উপর রেখে নাভির নিচে হাত বাঁধুন (হানাফি মত)। দৃষ্টি থাকবে সিজদার জায়গায়। নিচু স্বরে সানা পড়ুন।", "en": "Place the right palm over the left wrist and fold the hands below the navel (Hanafi view). Keep your gaze on the place of prostration. Quietly recite the thana."}}, {"type": "arabic", "label": {"bn": "সানা", "en": "Thana (opening praise)"}, "ar": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَىٰ جَدُّكَ، وَلَا إِلَٰهَ غَيْرُكَ", "pron": {"bn": "সুবহানাকা আল্লাহুম্মা ওয়া বিহামদিকা, ওয়া তাবারাকাসমুকা, ওয়া তাআলা জাদ্দুকা, ওয়া লা ইলাহা গাইরুক।", "en": "Subhanaka Allahumma wa bihamdika, wa tabarakasmuka, wa ta''ala jadduka, wa la ilaha ghayruk."}, "meaning": {"bn": "হে আল্লাহ! আপনি পবিত্র, সকল প্রশংসা আপনার। আপনার নাম বরকতময়, আপনার মর্যাদা অতি উঁচু, আর আপনি ছাড়া কোনো ইলাহ নেই।", "en": "Glory be to You, O Allah, and praise. Blessed is Your Name, exalted is Your majesty, and there is no god but You."}, "ref": {"bn": "সুনান আবু দাউদ ৭৭৬; সুনান তিরমিযি ২৪৩", "en": "Sunan Abi Dawud 776; Jami at-Tirmidhi 243"}}, {"type": "step", "title": {"bn": "তাআউয ও বিসমিল্লাহ", "en": "Ta''awwudh and Bismillah"}, "text": {"bn": "নিচু স্বরে আউযুবিল্লাহ এবং বিসমিল্লাহ পড়ুন।", "en": "Quietly recite the ta''awwudh, then Bismillah."}}, {"type": "arabic", "label": {"bn": "তাআউয", "en": "Ta''awwudh"}, "ar": "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ", "pron": {"bn": "আউযু বিল্লাহি মিনাশ শাইতানির রাজিম।", "en": "A''udhu billahi minash-shaytanir-rajim."}, "meaning": {"bn": "বিতাড়িত শয়তান থেকে আমি আল্লাহর কাছে আশ্রয় চাই।", "en": "I seek refuge with Allah from Satan, the accursed."}, "ref": {"bn": "সূরা নাহল ১৬:৯৮ (কুরআন পড়ার আগে আশ্রয় চাওয়ার নির্দেশ)", "en": "An-Nahl 16:98 (the command to seek refuge before reciting)"}}, {"type": "arabic", "label": {"bn": "তাসমিয়া (বিসমিল্লাহ)", "en": "Tasmiyah (Bismillah)"}, "ar": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "pron": {"bn": "বিসমিল্লাহির রাহমানির রাহিম।", "en": "Bismillahir-rahmanir-rahim."}, "meaning": {"bn": "পরম করুণাময়, অতি দয়ালু আল্লাহর নামে (শুরু করছি)।", "en": "In the name of Allah, the Most Gracious, the Most Merciful."}}, {"type": "step", "title": {"bn": "সূরা ফাতিহা", "en": "Surah Al-Fatihah"}, "text": {"bn": "সূরা ফাতিহা পড়ুন — ধীরে, প্রতিটি আয়াতে থেমে। একা নামাজে ফজর, মাগরিব ও এশায় চাইলে শব্দ করে পড়তে পারেন; জোহর-আসরে নিচু স্বরে।", "en": "Recite Al-Fatihah slowly, pausing at each ayah. Alone, you may recite aloud in Fajr, Maghrib and Isha; in Zuhr and Asr recite quietly."}}, {"type": "arabic", "label": {"bn": "সূরা আল-ফাতিহা", "en": "Surah Al-Fatihah"}, "ar": "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴿٢﴾ الرَّحْمَٰنِ الرَّحِيمِ ﴿٣﴾ مَالِكِ يَوْمِ الدِّينِ ﴿٤﴾ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٥﴾ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ﴿٦﴾ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ﴿٧﴾", "pron": {"bn": "আলহামদু লিল্লাহি রাব্বিল আলামিন। আর-রাহমানির রাহিম। মালিকি ইয়াওমিদ্দিন। ইয়্যাকা না''বুদু ওয়া ইয়্যাকা নাসতাইন। ইহদিনাস সিরাতাল মুসতাকিম। সিরাতাল্লাযিনা আন''আমতা আলাইহিম, গাইরিল মাগদুবি আলাইহিম ওয়ালাদ্দাল্লিন।", "en": "Al-hamdu lillahi rabbil-''alamin. Ar-rahmanir-rahim. Maliki yawmid-din. Iyyaka na''budu wa iyyaka nasta''in. Ihdinas-siratal-mustaqim. Siratal-ladhina an''amta ''alayhim, ghayril-maghdubi ''alayhim wa lad-dallin."}, "meaning": {"bn": "সকল প্রশংসা আল্লাহর, যিনি সমস্ত জগতের রব। যিনি পরম করুণাময়, অতি দয়ালু। যিনি প্রতিদান দিবসের মালিক। আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই কাছে সাহায্য চাই। আমাদের সরল পথ দেখান — তাদের পথ, যাদের আপনি নিয়ামত দিয়েছেন; তাদের পথ নয় যাদের উপর আপনার গজব পড়েছে, আর তাদের পথও নয় যারা পথভ্রষ্ট।", "en": "All praise is for Allah, Lord of all the worlds, the Most Gracious, the Most Merciful, Master of the Day of Judgement. You alone we worship and You alone we ask for help. Guide us to the straight path: the path of those You have blessed, not of those who earned Your anger, nor of those who went astray."}, "ref": {"bn": "সূরা ফাতিহা ১:২–৭ (মুসহাফে বিসমিল্লাহ ১ নম্বর আয়াত)", "en": "Al-Fatihah 1:2–7 (the Basmalah is ayah 1 in the Mushaf)"}}, {"type": "note", "tone": "info", "text": {"bn": "মুসহাফে বিসমিল্লাহ সূরা ফাতিহার প্রথম আয়াত; আগের ধাপে তা পড়া হয়েছে, তাই এখানে \"আলহামদু লিল্লাহ\" থেকে শুরু।", "en": "In the Mushaf the Basmalah is the first ayah of Al-Fatihah; it was said in the previous step, so here we begin from \"Al-hamdu lillah\"."}}, {"type": "step", "title": {"bn": "আমিন", "en": "Amin"}, "text": {"bn": "ফাতিহা শেষ হলে \"আমিন\" বলুন (হানাফি মতে নিচু স্বরে)।", "en": "When Al-Fatihah ends, say \"Amin\" (quietly, in the Hanafi view)."}}, {"type": "arabic", "label": {"bn": "আমিন", "en": "Amin"}, "ar": "آمِينَ", "pron": {"bn": "আমিন", "en": "Amin"}, "meaning": {"bn": "হে আল্লাহ! কবুল করুন।", "en": "O Allah, accept (answer our prayer)."}, "ref": {"bn": "সহিহ বুখারি ৭৮০; সহিহ মুসলিম ৪১০", "en": "Sahih al-Bukhari 780; Sahih Muslim 410"}}, {"type": "step", "title": {"bn": "আরেকটি সূরা মিলানো", "en": "Recite another surah"}, "text": {"bn": "এরপর কুরআন থেকে যেকোনো একটি সূরা বা কমপক্ষে ছোট তিন আয়াত পরিমাণ পড়ুন। উদাহরণ হিসেবে সূরা ইখলাস:", "en": "Then recite any surah, or at least the length of three short ayat. For example, Surah Al-Ikhlas:"}}, {"type": "arabic", "label": {"bn": "সূরা ইখলাস (উদাহরণ)", "en": "Surah Al-Ikhlas (example)"}, "ar": "قُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾", "pron": {"bn": "কুল হুয়াল্লাহু আহাদ। আল্লাহুস সামাদ। লাম ইয়ালিদ ওয়া লাম ইউলাদ। ওয়া লাম ইয়াকুল লাহু কুফুওয়ান আহাদ।", "en": "Qul huwallahu ahad. Allahus-samad. Lam yalid wa lam yulad. Wa lam yakul-lahu kufuwan ahad."}, "meaning": {"bn": "বলুন, তিনিই আল্লাহ, এক ও অদ্বিতীয়। আল্লাহ কারো মুখাপেক্ষী নন, সবাই তাঁর মুখাপেক্ষী। তিনি কাউকে জন্ম দেননি এবং কেউ তাঁকে জন্ম দেয়নি। আর তাঁর সমকক্ষ কেউ নেই।", "en": "Say: He is Allah, the One. Allah, the Self-Sufficient on whom all depend. He neither begets nor was He begotten. And there is none comparable to Him."}, "ref": {"bn": "সূরা ইখলাস ১১২:১–৪", "en": "Al-Ikhlas 112:1–4"}}, {"type": "step", "title": {"bn": "রুকু", "en": "Ruku (bowing)"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে রুকুতে যান। আঙুল ছড়িয়ে দুই হাঁটু ধরুন, পিঠ সোজা রাখুন, মাথা পিঠের সমান রাখুন — উঁচুও না, নিচুও না। ধীরস্থিরভাবে কমপক্ষে তিনবার তাসবিহ পড়ুন।", "en": "Say \"Allahu akbar\" and bow. Grip the knees with the fingers spread, keep the back straight and the head level with it, neither raised nor lowered. Calmly say the tasbih at least three times."}}, {"type": "arabic", "label": {"bn": "রুকুতে যাওয়ার তাকবির", "en": "Takbir for going into ruku"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}}, {"type": "arabic", "label": {"bn": "রুকুর তাসবিহ (কমপক্ষে ৩ বার)", "en": "Ruku tasbih (at least 3 times)"}, "ar": "سُبْحَانَ رَبِّيَ الْعَظِيمِ", "pron": {"bn": "সুবহানা রাব্বিয়াল আযিম।", "en": "Subhana rabbiyal-''azim."}, "meaning": {"bn": "আমার মহান রব পবিত্র।", "en": "Glory be to my Lord, the Magnificent."}, "ref": {"bn": "সহিহ মুসলিম ৭৭২; সুনান আবু দাউদ ৮৭১", "en": "Sahih Muslim 772; Sunan Abi Dawud 871"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৪৯৮ — রুকুতে মাথা না উঁচু, না নিচু", "en": "Sahih Muslim 498: in ruku the head neither raised nor lowered"}}, {"type": "step", "title": {"bn": "রুকু থেকে ওঠা (কাওমা)", "en": "Rising from ruku (qawmah)"}, "text": {"bn": "ওঠার সময় \"সামিআল্লাহু লিমান হামিদাহ\" বলুন। পুরোপুরি সোজা হয়ে দাঁড়িয়ে স্থির হোন এবং \"রাব্বানা ওয়া লাকাল হামদ\" বলুন। জামাতে ইমাম তাসমি বলবেন, মুক্তাদিরা শুধু তাহমিদ বলবেন (হানাফি মত)।", "en": "While rising say \"Sami''allahu liman hamidah\". Stand fully upright, become still, and say \"Rabbana wa lakal-hamd\". In congregation the imam says the tasmi'' and the followers say only the tahmid (Hanafi view)."}}, {"type": "arabic", "label": {"bn": "তাসমি (রুকু থেকে ওঠার সময়)", "en": "Tasmi'' (while rising from ruku)"}, "ar": "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ", "pron": {"bn": "সামিআল্লাহু লিমান হামিদাহ।", "en": "Sami''allahu liman hamidah."}, "meaning": {"bn": "যে আল্লাহর প্রশংসা করে, আল্লাহ তার কথা শোনেন।", "en": "Allah hears the one who praises Him."}, "ref": {"bn": "সহিহ বুখারি ৭৯৬", "en": "Sahih al-Bukhari 796"}}, {"type": "arabic", "label": {"bn": "তাহমিদ (সোজা হয়ে দাঁড়িয়ে)", "en": "Tahmid (once standing straight)"}, "ar": "رَبَّنَا وَلَكَ الْحَمْدُ", "pron": {"bn": "রাব্বানা ওয়া লাকাল হামদ।", "en": "Rabbana wa lakal-hamd."}, "meaning": {"bn": "হে আমাদের রব! সকল প্রশংসা আপনারই।", "en": "Our Lord, and to You belongs all praise."}, "ref": {"bn": "সহিহ বুখারি ৭৯৬", "en": "Sahih al-Bukhari 796"}}, {"type": "arabic", "label": {"bn": "তাহমিদের দীর্ঘ রূপ (ঐচ্ছিক)", "en": "Longer form of tahmid (optional)"}, "ar": "رَبَّنَا وَلَكَ الْحَمْدُ، حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ", "pron": {"bn": "রাব্বানা ওয়া লাকাল হামদু, হামদান কাসিরান তাইয়িবান মুবারাকান ফিহ।", "en": "Rabbana wa lakal-hamdu, hamdan kathiran tayyiban mubarakan fih."}, "meaning": {"bn": "হে আমাদের রব! সকল প্রশংসা আপনার — অনেক অনেক, পবিত্র ও বরকতময় প্রশংসা।", "en": "Our Lord, to You belongs all praise: abundant, pure and blessed praise."}, "ref": {"bn": "সহিহ বুখারি ৭৯৯", "en": "Sahih al-Bukhari 799"}}, {"type": "step", "title": {"bn": "প্রথম সিজদা", "en": "The first sujud"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে সিজদায় যান: প্রথমে দুই হাঁটু, তারপর দুই হাত, তারপর নাক ও কপাল মাটিতে রাখুন। মুখ দুই হাতের মাঝে থাকবে, আঙুলগুলো মিলিয়ে কিবলামুখী। পুরুষরা পেট উরু থেকে এবং বাহু পাঁজর থেকে আলাদা রাখবেন, কনুই মাটি থেকে উঁচুতে। পায়ের আঙুল কিবলার দিকে মোড়ানো থাকবে। কমপক্ষে তিনবার তাসবিহ পড়ুন।", "en": "Say \"Allahu akbar\" and go down: knees first, then hands, then nose and forehead. The face is between the hands, fingers together and pointing to the qiblah. Men keep the belly away from the thighs and the arms away from the sides, elbows off the ground. The toes are bent towards the qiblah. Say the tasbih at least three times."}}, {"type": "arabic", "label": {"bn": "সিজদায় যাওয়ার তাকবির", "en": "Takbir for going into sujud"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}}, {"type": "arabic", "label": {"bn": "সিজদার তাসবিহ (কমপক্ষে ৩ বার)", "en": "Sujud tasbih (at least 3 times)"}, "ar": "سُبْحَانَ رَبِّيَ الْأَعْلَىٰ", "pron": {"bn": "সুবহানা রাব্বিয়াল আ''লা।", "en": "Subhana rabbiyal-a''la."}, "meaning": {"bn": "আমার সর্বোচ্চ রব পবিত্র।", "en": "Glory be to my Lord, the Most High."}, "ref": {"bn": "সহিহ মুসলিম ৭৭২; সুনান আবু দাউদ ৮৭১", "en": "Sahih Muslim 772; Sunan Abi Dawud 871"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮১২; সহিহ মুসলিম ৪৯০ — সাত অঙ্গে সিজদা: কপাল (নাকসহ), দুই হাত, দুই হাঁটু ও দুই পায়ের আঙুল", "en": "Sahih al-Bukhari 812; Sahih Muslim 490: prostrating on seven bones: forehead (with the nose), two hands, two knees and the toes of both feet"}}, {"type": "step", "title": {"bn": "দুই সিজদার মাঝে বসা (জালসা)", "en": "Sitting between the two sujud (jalsah)"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে উঠে বসুন — বাম পা বিছিয়ে তার উপর বসুন, ডান পা খাড়া রাখুন, আঙুল কিবলামুখী; হাত দুটি উরুর উপর। পুরোপুরি স্থির হয়ে বসুন; চাইলে নিচের দোয়াটি পড়ুন।", "en": "Say \"Allahu akbar\" and sit up: sit on the left foot laid flat, with the right foot upright and its toes facing the qiblah, hands on the thighs. Become fully still; you may recite the dua below."}}, {"type": "arabic", "label": {"bn": "দুই সিজদার মাঝের দোয়া", "en": "Dua between the two sujud"}, "ar": "اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَعَافِنِي، وَاهْدِنِي، وَارْزُقْنِي", "pron": {"bn": "আল্লাহুম্মাগফিরলি, ওয়ারহামনি, ওয়া আফিনি, ওয়াহদিনি, ওয়ারযুকনি।", "en": "Allahummaghfir li, warhamni, wa ''afini, wahdini, warzuqni."}, "meaning": {"bn": "হে আল্লাহ! আমাকে ক্ষমা করুন, আমার উপর দয়া করুন, আমাকে নিরাপদ রাখুন, সঠিক পথ দেখান এবং রিজিক দিন।", "en": "O Allah, forgive me, have mercy on me, keep me safe and well, guide me and provide for me."}, "ref": {"bn": "সুনান আবু দাউদ ৮৫০", "en": "Sunan Abi Dawud 850"}}, {"type": "step", "title": {"bn": "দ্বিতীয় সিজদা", "en": "The second sujud"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে আবার আগের মতো সিজদা করুন এবং কমপক্ষে তিনবার \"সুবহানা রাব্বিয়াল আ''লা\" পড়ুন। এর মাধ্যমে প্রথম রাকাত শেষ হলো।", "en": "Say \"Allahu akbar\" and prostrate again as before, saying \"Subhana rabbiyal-a''la\" at least three times. This completes the first rakat."}}, {"type": "heading", "text": {"bn": "দ্বিতীয় রাকাত", "en": "The second rakat"}}, {"type": "step", "title": {"bn": "দাঁড়িয়ে যাওয়া", "en": "Stand up"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে দ্বিতীয় রাকাতের জন্য সোজা দাঁড়িয়ে হাত বাঁধুন। হানাফি মতে মাঝখানে না বসে পায়ের পাতার উপর ভর দিয়ে উঠবেন।", "en": "Say \"Allahu akbar\" and stand straight up for the second rakat, folding the hands. In the Hanafi view one rises on the front of the feet without sitting first."}}, {"type": "note", "tone": "info", "text": {"bn": "শাফেয়ি মাযহাবসহ কিছু আলেমের মতে দ্বিতীয় সিজদার পর দাঁড়ানোর আগে সামান্য বসা (জালসায়ে ইস্তিরাহা) সুন্নত (সহিহ বুখারি ৮২৩)। হানাফি মতে এটি বার্ধক্য বা প্রয়োজনের কারণে ছিল।", "en": "Shafi''is and some others hold that a brief sit before standing (jalsat al-istirahah) is sunnah (Sahih al-Bukhari 823). Hanafis understand it as done due to age or need."}}, {"type": "step", "title": {"bn": "ফাতিহা ও সূরা", "en": "Al-Fatihah and a surah"}, "text": {"bn": "দ্বিতীয় রাকাতে সানা ও আউযুবিল্লাহ পড়বেন না। বিসমিল্লাহ পড়ে সূরা ফাতিহা, আমিন, তারপর আরেকটি সূরা (যেমন সূরা কাওসার বা যেকোনো সূরা) পড়ুন। প্রথম রাকাতের চেয়ে দ্বিতীয় রাকাতের কিরাত একটু ছোট হওয়া সুন্নত।", "en": "In the second rakat do not repeat the thana or ta''awwudh. Say Bismillah, recite Al-Fatihah, say Amin, then another surah (e.g. Al-Kawthar or any surah). It is sunnah for the second rakat''s recitation to be a little shorter than the first."}}, {"type": "step", "title": {"bn": "রুকু ও সিজদা", "en": "Ruku and sujud"}, "text": {"bn": "প্রথম রাকাতের মতোই রুকু, রুকু থেকে ওঠা, দুই সিজদা ও মাঝের বসা আদায় করুন — প্রতিটিতে ধীরস্থিরভাবে।", "en": "Do the ruku, the rising, the two sujud and the sitting between them exactly as in the first rakat, calmly in each."}}, {"type": "heading", "text": {"bn": "শেষ বৈঠক ও সালাম", "en": "The final sitting and salam"}}, {"type": "step", "title": {"bn": "বসা ও তাশাহহুদ", "en": "Sit and recite the tashahhud"}, "text": {"bn": "দ্বিতীয় সিজদার পর \"আল্লাহু আকবার\" বলে জালসার মতো বসুন, হাত দুটি উরুর উপর। আত্তাহিয়্যাতু পড়ুন। \"আশহাদু আল লা ইলাহা\" বলার সময় ডান হাতের শাহাদাত আঙুল উঠিয়ে ইশারা করুন, \"ইল্লাল্লাহ\" বলার সময় নামিয়ে নিন (হানাফি পদ্ধতি)।", "en": "After the second sujud say \"Allahu akbar\" and sit as in the jalsah, hands on the thighs. Recite the tashahhud. At \"ashhadu an la ilaha\" raise the right index finger to point, and lower it at \"illallah\" (Hanafi method)."}}, {"type": "arabic", "label": {"bn": "তাশাহহুদ (আত্তাহিয়্যাতু)", "en": "Tashahhud (At-tahiyyat)"}, "ar": "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَىٰ عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "pron": {"bn": "আত্তাহিয়্যাতু লিল্লাহি ওয়াস সালাওয়াতু ওয়াত তাইয়িবাতু, আসসালামু আলাইকা আইয়্যুহান নাবিয়্যু ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ, আসসালামু আলাইনা ওয়া আলা ইবাদিল্লাহিস সালিহিন। আশহাদু আল লা ইলাহা ইল্লাল্লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ।", "en": "At-tahiyyatu lillahi was-salawatu wat-tayyibat. As-salamu ''alayka ayyuhan-nabiyyu wa rahmatullahi wa barakatuh. As-salamu ''alayna wa ''ala ''ibadillahis-salihin. Ashhadu an la ilaha illallahu, wa ashhadu anna Muhammadan ''abduhu wa rasuluh."}, "meaning": {"bn": "সকল সম্মান, সকল নামাজ-ইবাদত ও সকল পবিত্র বিষয় আল্লাহর জন্য। হে নবী! আপনার প্রতি সালাম এবং আল্লাহর রহমত ও বরকত। সালাম আমাদের প্রতি এবং আল্লাহর সকল নেক বান্দার প্রতি। আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, এবং আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসুল।", "en": "All greetings, prayers and good things are for Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god but Allah, and I bear witness that Muhammad is His servant and Messenger."}, "ref": {"bn": "সহিহ বুখারি ৮৩১; সহিহ মুসলিম ৪০২", "en": "Sahih al-Bukhari 831; Sahih Muslim 402"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৫৮০ — তাশাহহুদে শাহাদাত আঙুল দিয়ে ইশারা", "en": "Sahih Muslim 580: pointing with the index finger in the tashahhud"}}, {"type": "step", "title": {"bn": "দরুদ", "en": "Durood"}, "text": {"bn": "এরপর দরুদে ইবরাহিম পড়ুন।", "en": "Then recite the Durood Ibrahim."}}, {"type": "arabic", "label": {"bn": "দরুদে ইবরাহিম", "en": "Durood Ibrahim (Salat Ibrahimiyyah)"}, "ar": "اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ", "pron": {"bn": "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা সাল্লাইতা আলা ইবরাহিমা ওয়া আলা আলি ইবরাহিম, ইন্নাকা হামিদুম মাজিদ। আল্লাহুম্মা বারিক আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা বারাকতা আলা ইবরাহিমা ওয়া আলা আলি ইবরাহিম, ইন্নাকা হামিদুম মাজিদ।", "en": "Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad, kama sallayta ''ala Ibrahima wa ''ala ali Ibrahim, innaka hamidum majid. Allahumma barik ''ala Muhammadin wa ''ala ali Muhammad, kama barakta ''ala Ibrahima wa ''ala ali Ibrahim, innaka hamidum majid."}, "meaning": {"bn": "হে আল্লাহ! মুহাম্মাদ ﷺ ও তাঁর পরিবারবর্গের প্রতি রহমত বর্ষণ করুন, যেমন আপনি ইবরাহিম (আ.) ও তাঁর পরিবারবর্গের প্রতি রহমত বর্ষণ করেছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত। হে আল্লাহ! মুহাম্মাদ ﷺ ও তাঁর পরিবারবর্গের প্রতি বরকত দিন, যেমন আপনি ইবরাহিম (আ.) ও তাঁর পরিবারবর্গের প্রতি বরকত দিয়েছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত।", "en": "O Allah, send prayers upon Muhammad and the family of Muhammad, as You sent prayers upon Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious."}, "ref": {"bn": "সহিহ বুখারি ৩৩৭০; সহিহ মুসলিম ৪০৬", "en": "Sahih al-Bukhari 3370; Sahih Muslim 406"}}, {"type": "step", "title": {"bn": "দোয়া", "en": "Dua"}, "text": {"bn": "এরপর কুরআন-হাদিসের কোনো দোয়া পড়ুন; সবচেয়ে প্রচলিত হলো দোয়া মাসুরা, যা রাসুলুল্লাহ ﷺ আবু বকর (রা.)-কে নামাজে পড়ার জন্য শিখিয়েছিলেন।", "en": "Then recite a dua from the Quran or Sunnah. The most common is dua ma''thura, which the Prophet ﷺ taught Abu Bakr (RA) to say in his prayer."}}, {"type": "arabic", "label": {"bn": "দোয়া মাসুরা", "en": "Dua ma''thura"}, "ar": "اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ", "pron": {"bn": "আল্লাহুম্মা ইন্নি যালামতু নাফসি যুলমান কাসিরা, ওয়ালা ইয়াগফিরুয যুনুবা ইল্লা আনতা, ফাগফিরলি মাগফিরাতাম মিন ইনদিকা, ওয়ারহামনি, ইন্নাকা আনতাল গাফুরুর রাহিম।", "en": "Allahumma inni zalamtu nafsi zulman kathira, wa la yaghfirudh-dhunuba illa anta, faghfir li maghfiratam min ''indika, warhamni, innaka antal-ghafurur-rahim."}, "meaning": {"bn": "হে আল্লাহ! আমি নিজের উপর অনেক জুলুম করেছি, আর আপনি ছাড়া কেউ গুনাহ ক্ষমা করতে পারে না। তাই আপনার পক্ষ থেকে আমাকে বিশেষ ক্ষমা দান করুন এবং আমার উপর রহম করুন। নিশ্চয়ই আপনি অতি ক্ষমাশীল, পরম দয়ালু।", "en": "O Allah, I have wronged myself greatly, and none forgives sins but You. So grant me forgiveness from Yourself and have mercy on me; You are the Oft-Forgiving, the Most Merciful."}, "ref": {"bn": "সহিহ বুখারি ৮৩৪; সহিহ মুসলিম ২৭০৫", "en": "Sahih al-Bukhari 834; Sahih Muslim 2705"}}, {"type": "step", "title": {"bn": "সালাম ফেরানো", "en": "Give the salam"}, "text": {"bn": "প্রথমে ডান দিকে মুখ ফিরিয়ে বলুন \"আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ\", তারপর বাম দিকে মুখ ফিরিয়ে একই কথা বলুন। এর মাধ্যমে নামাজ শেষ হলো।", "en": "Turn your face to the right and say \"As-salamu ''alaykum wa rahmatullah\", then to the left saying the same. The prayer is complete."}}, {"type": "arabic", "label": {"bn": "সালাম (প্রথমে ডানে, তারপর বামে)", "en": "Salam (right, then left)"}, "ar": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "pron": {"bn": "আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ।", "en": "As-salamu ''alaykum wa rahmatullah."}, "meaning": {"bn": "আপনাদের উপর শান্তি ও আল্লাহর রহমত বর্ষিত হোক।", "en": "Peace be upon you and the mercy of Allah."}, "ref": {"bn": "সহিহ মুসলিম ৫৮২; সুনান আবু দাউদ ৯৯৬", "en": "Sahih Muslim 582; Sunan Abi Dawud 996"}}, {"type": "note", "tone": "tip", "text": {"bn": "সালামের পর তাড়াহুড়া করে উঠে না গিয়ে নামাজের পরের জিকিরগুলো পড়ুন — \"নামাজের পরের জিকির ও দোয়া\" অংশে দেওয়া আছে।", "en": "After the salam, do not rush off: recite the dhikr after prayer, given in \"Dhikr and Duas after Salah\"."}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9f9d5a21-06e2-5755-b6a4-cf272418c8ac', id, 'salah-three-four-rakat', '{"bn": "তিন ও চার রাকাত নামাজ", "en": "Praying Three and Four Rakats"}', '{"bn": "মাগরিবের তিন রাকাত এবং জোহর, আসর ও এশার চার রাকাত — দুই রাকাতের পর প্রথম বৈঠক থেকে শেষ পর্যন্ত কী করবেন।", "en": "The three rakats of Maghrib and the four of Zuhr, Asr and Isha: what to do from the first sitting after two rakats to the end."}', 'basic', '[{"type": "text", "text": {"bn": "তিন বা চার রাকাতের নামাজের প্রথম দুই রাকাত হুবহু \"দুই রাকাত নামাজ\" অংশের মতো। পার্থক্য শুরু হয় দ্বিতীয় রাকাতের দ্বিতীয় সিজদার পর।", "en": "The first two rakats of a three- or four-rakat prayer are exactly as in \"How to Pray Two Rakats\". The difference begins after the second sujud of the second rakat."}}, {"type": "heading", "text": {"bn": "প্রথম বৈঠক (কাদায়ে উলা)", "en": "The first sitting"}}, {"type": "step", "title": {"bn": "বসে শুধু তাশাহহুদ", "en": "Sit and recite only the tashahhud"}, "text": {"bn": "দ্বিতীয় রাকাতের দুই সিজদার পর বসুন এবং শুধু আত্তাহিয়্যাতু \"আবদুহু ওয়া রাসুলুহ\" পর্যন্ত পড়ুন। ফরজ ও সুন্নতে মুয়াক্কাদায় এখানে দরুদ বা দোয়া পড়বেন না।", "en": "After the two sujud of the second rakat, sit and recite only the tashahhud up to \"''abduhu wa rasuluh\". In fard and sunnah muakkadah prayers do not add the durood or dua here."}}, {"type": "arabic", "label": {"bn": "তাশাহহুদ (আত্তাহিয়্যাতু)", "en": "Tashahhud (At-tahiyyat)"}, "ar": "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَىٰ عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "pron": {"bn": "আত্তাহিয়্যাতু লিল্লাহি ওয়াস সালাওয়াতু ওয়াত তাইয়িবাতু, আসসালামু আলাইকা আইয়্যুহান নাবিয়্যু ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ, আসসালামু আলাইনা ওয়া আলা ইবাদিল্লাহিস সালিহিন। আশহাদু আল লা ইলাহা ইল্লাল্লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ।", "en": "At-tahiyyatu lillahi was-salawatu wat-tayyibat. As-salamu ''alayka ayyuhan-nabiyyu wa rahmatullahi wa barakatuh. As-salamu ''alayna wa ''ala ''ibadillahis-salihin. Ashhadu an la ilaha illallahu, wa ashhadu anna Muhammadan ''abduhu wa rasuluh."}, "meaning": {"bn": "সকল সম্মান, সকল নামাজ-ইবাদত ও সকল পবিত্র বিষয় আল্লাহর জন্য। হে নবী! আপনার প্রতি সালাম এবং আল্লাহর রহমত ও বরকত। সালাম আমাদের প্রতি এবং আল্লাহর সকল নেক বান্দার প্রতি। আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, এবং আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসুল।", "en": "All greetings, prayers and good things are for Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god but Allah, and I bear witness that Muhammad is His servant and Messenger."}, "ref": {"bn": "সহিহ বুখারি ৮৩১; সহিহ মুসলিম ৪০২", "en": "Sahih al-Bukhari 831; Sahih Muslim 402"}}, {"type": "note", "tone": "warn", "text": {"bn": "প্রথম বৈঠকে ভুলে \"আল্লাহুম্মা সাল্লি আলা মুহাম্মাদ\" পর্যন্ত বা তার বেশি পড়ে ফেললে হানাফি মতে শেষে সাহু সিজদা দিতে হবে। আর প্রথম বৈঠক ভুলে গিয়ে পুরোপুরি দাঁড়িয়ে গেলে আর বসতে ফিরবেন না; নামাজ শেষে সাহু সিজদা দেবেন (সহিহ বুখারি ১২২৪; সহিহ মুসলিম ৫৭০)।", "en": "If in the first sitting you mistakenly add \"Allahumma salli ''ala Muhammad\" or more, Hanafis require sajdah sahw at the end. If you forget the first sitting and have fully stood up, do not go back; do sajdah sahw at the end (Sahih al-Bukhari 1224; Sahih Muslim 570)."}}, {"type": "step", "title": {"bn": "তৃতীয় রাকাতের জন্য দাঁড়ানো", "en": "Stand for the third rakat"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে সোজা দাঁড়িয়ে হাত বাঁধুন।", "en": "Say \"Allahu akbar\", stand straight up and fold the hands."}}, {"type": "arabic", "label": {"bn": "দাঁড়ানোর তাকবির", "en": "Takbir for standing up"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}}, {"type": "heading", "text": {"bn": "তৃতীয় রাকাত", "en": "The third rakat"}}, {"type": "step", "title": {"bn": "কিরাত", "en": "Recitation"}, "text": {"bn": "বিসমিল্লাহ পড়ে সূরা ফাতিহা পড়ুন। ফরজ নামাজের তৃতীয় ও চতুর্থ রাকাতে ফাতিহার পর অন্য সূরা মেলাবেন না। কিন্তু সুন্নত, নফল ও বিতরের প্রতিটি রাকাতে ফাতিহার পর সূরা মেলানো ওয়াজিব।", "en": "Say Bismillah and recite Al-Fatihah. In the third and fourth rakats of fard prayers do not add another surah. But in every rakat of sunnah, nafl and witr prayers, adding a surah after Al-Fatihah is wajib."}}, {"type": "arabic", "label": {"bn": "সূরা আল-ফাতিহা", "en": "Surah Al-Fatihah"}, "ar": "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴿٢﴾ الرَّحْمَٰنِ الرَّحِيمِ ﴿٣﴾ مَالِكِ يَوْمِ الدِّينِ ﴿٤﴾ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٥﴾ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ﴿٦﴾ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ﴿٧﴾", "pron": {"bn": "আলহামদু লিল্লাহি রাব্বিল আলামিন। আর-রাহমানির রাহিম। মালিকি ইয়াওমিদ্দিন। ইয়্যাকা না''বুদু ওয়া ইয়্যাকা নাসতাইন। ইহদিনাস সিরাতাল মুসতাকিম। সিরাতাল্লাযিনা আন''আমতা আলাইহিম, গাইরিল মাগদুবি আলাইহিম ওয়ালাদ্দাল্লিন।", "en": "Al-hamdu lillahi rabbil-''alamin. Ar-rahmanir-rahim. Maliki yawmid-din. Iyyaka na''budu wa iyyaka nasta''in. Ihdinas-siratal-mustaqim. Siratal-ladhina an''amta ''alayhim, ghayril-maghdubi ''alayhim wa lad-dallin."}, "meaning": {"bn": "সকল প্রশংসা আল্লাহর, যিনি সমস্ত জগতের রব। যিনি পরম করুণাময়, অতি দয়ালু। যিনি প্রতিদান দিবসের মালিক। আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই কাছে সাহায্য চাই। আমাদের সরল পথ দেখান — তাদের পথ, যাদের আপনি নিয়ামত দিয়েছেন; তাদের পথ নয় যাদের উপর আপনার গজব পড়েছে, আর তাদের পথও নয় যারা পথভ্রষ্ট।", "en": "All praise is for Allah, Lord of all the worlds, the Most Gracious, the Most Merciful, Master of the Day of Judgement. You alone we worship and You alone we ask for help. Guide us to the straight path: the path of those You have blessed, not of those who earned Your anger, nor of those who went astray."}, "ref": {"bn": "সূরা ফাতিহা ১:২–৭ (মুসহাফে বিসমিল্লাহ ১ নম্বর আয়াত)", "en": "Al-Fatihah 1:2–7 (the Basmalah is ayah 1 in the Mushaf)"}}, {"type": "differ", "title": {"bn": "ফরজের শেষ দুই রাকাতে সূরা ফাতিহা", "en": "Al-Fatihah in the last two rakats of fard"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "শেষ দুই রাকাতে ফাতিহা পড়া সুন্নত ও উত্তম; কেউ না পড়ে তিনবার \"সুবহানাল্লাহ\" পরিমাণ চুপ থাকলে বা তাসবিহ পড়লেও নামাজ হয়ে যায়।", "en": "Reciting Al-Fatihah in the last two rakats is sunnah and best; if one instead stays silent or says tasbih for about three \"subhanallah\"s, the prayer is still valid."}, "evidence": {"bn": "আলি ও ইবনে মাসউদ (রা.) থেকে বর্ণিত — প্রথম দুই রাকাতে কিরাত পড়ো, শেষ দুই রাকাতে তাসবিহ (মুসান্নাফ ইবনে আবি শাইবা)।", "en": "Reported from Ali and Ibn Mas''ud (RA): recite in the first two rakats and glorify Allah in the last two (Musannaf Ibn Abi Shaybah)."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki and Hanbali"}, "text": {"bn": "প্রতিটি রাকাতেই সূরা ফাতিহা পড়া ফরজ (রুকন)।", "en": "Al-Fatihah is obligatory (a pillar) in every rakat."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ জোহরের শেষ দুই রাকাতে শুধু ফাতিহা পড়তেন — সহিহ বুখারি ৭৭৬; \"যে ফাতিহা পড়ে না তার নামাজ হয় না\" — সহিহ বুখারি ৭৫৬; ভুলভাবে নামাজ আদায়কারীকে প্রতি রাকাতে একই রকম করতে বলেছেন — সহিহ বুখারি ৭৫৭।", "en": "The Prophet ﷺ recited only Al-Fatihah in the last two rakats of Zuhr (Sahih al-Bukhari 776); \"no prayer for one who does not recite Al-Fatihah\" (Sahih al-Bukhari 756); the man who prayed badly was told to do the same in every rakat (Sahih al-Bukhari 757)."}}], "check": true}, {"type": "step", "title": {"bn": "রুকু ও দুই সিজদা", "en": "Ruku and two sujud"}, "text": {"bn": "আগের মতোই রুকু, কাওমা, দুই সিজদা ও জালসা আদায় করুন।", "en": "Do the ruku, rising, two sujud and the sitting between them as before."}}, {"type": "heading", "text": {"bn": "মাগরিব (তিন রাকাত) হলে", "en": "If it is Maghrib (three rakats)"}}, {"type": "step", "title": {"bn": "শেষ বৈঠক", "en": "The final sitting"}, "text": {"bn": "তৃতীয় রাকাতের দুই সিজদার পর বসে তাশাহহুদ, দরুদে ইবরাহিম ও দোয়া মাসুরা পড়ে ডানে-বামে সালাম ফেরান — ঠিক দুই রাকাতের শেষ বৈঠকের মতো।", "en": "After the two sujud of the third rakat, sit and recite the tashahhud, Durood Ibrahim and dua ma''thura, then give salam right and left, exactly as at the end of a two-rakat prayer."}}, {"type": "heading", "text": {"bn": "জোহর, আসর ও এশা (চার রাকাত) হলে", "en": "If it is Zuhr, Asr or Isha (four rakats)"}}, {"type": "step", "title": {"bn": "চতুর্থ রাকাত", "en": "The fourth rakat"}, "text": {"bn": "তৃতীয় রাকাতের পর না বসে \"আল্লাহু আকবার\" বলে দাঁড়িয়ে যান। চতুর্থ রাকাত তৃতীয় রাকাতের মতোই পড়ুন (ফরজে শুধু ফাতিহা)।", "en": "After the third rakat do not sit; say \"Allahu akbar\" and stand. Pray the fourth rakat like the third (only Al-Fatihah in fard)."}}, {"type": "step", "title": {"bn": "শেষ বৈঠক ও সালাম", "en": "The final sitting and salam"}, "text": {"bn": "চতুর্থ রাকাতের দুই সিজদার পর বসে তাশাহহুদ, দরুদ ও দোয়া পড়ে সালাম ফেরান।", "en": "After the two sujud of the fourth rakat, sit, recite the tashahhud, durood and dua, and give salam."}}, {"type": "arabic", "label": {"bn": "দরুদে ইবরাহিম", "en": "Durood Ibrahim (Salat Ibrahimiyyah)"}, "ar": "اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ", "pron": {"bn": "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা সাল্লাইতা আলা ইবরাহিমা ওয়া আলা আলি ইবরাহিম, ইন্নাকা হামিদুম মাজিদ। আল্লাহুম্মা বারিক আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা বারাকতা আলা ইবরাহিমা ওয়া আলা আলি ইবরাহিম, ইন্নাকা হামিদুম মাজিদ।", "en": "Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad, kama sallayta ''ala Ibrahima wa ''ala ali Ibrahim, innaka hamidum majid. Allahumma barik ''ala Muhammadin wa ''ala ali Muhammad, kama barakta ''ala Ibrahima wa ''ala ali Ibrahim, innaka hamidum majid."}, "meaning": {"bn": "হে আল্লাহ! মুহাম্মাদ ﷺ ও তাঁর পরিবারবর্গের প্রতি রহমত বর্ষণ করুন, যেমন আপনি ইবরাহিম (আ.) ও তাঁর পরিবারবর্গের প্রতি রহমত বর্ষণ করেছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত। হে আল্লাহ! মুহাম্মাদ ﷺ ও তাঁর পরিবারবর্গের প্রতি বরকত দিন, যেমন আপনি ইবরাহিম (আ.) ও তাঁর পরিবারবর্গের প্রতি বরকত দিয়েছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত।", "en": "O Allah, send prayers upon Muhammad and the family of Muhammad, as You sent prayers upon Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious."}, "ref": {"bn": "সহিহ বুখারি ৩৩৭০; সহিহ মুসলিম ৪০৬", "en": "Sahih al-Bukhari 3370; Sahih Muslim 406"}}, {"type": "arabic", "label": {"bn": "দোয়া মাসুরা", "en": "Dua ma''thura"}, "ar": "اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ", "pron": {"bn": "আল্লাহুম্মা ইন্নি যালামতু নাফসি যুলমান কাসিরা, ওয়ালা ইয়াগফিরুয যুনুবা ইল্লা আনতা, ফাগফিরলি মাগফিরাতাম মিন ইনদিকা, ওয়ারহামনি, ইন্নাকা আনতাল গাফুরুর রাহিম।", "en": "Allahumma inni zalamtu nafsi zulman kathira, wa la yaghfirudh-dhunuba illa anta, faghfir li maghfiratam min ''indika, warhamni, innaka antal-ghafurur-rahim."}, "meaning": {"bn": "হে আল্লাহ! আমি নিজের উপর অনেক জুলুম করেছি, আর আপনি ছাড়া কেউ গুনাহ ক্ষমা করতে পারে না। তাই আপনার পক্ষ থেকে আমাকে বিশেষ ক্ষমা দান করুন এবং আমার উপর রহম করুন। নিশ্চয়ই আপনি অতি ক্ষমাশীল, পরম দয়ালু।", "en": "O Allah, I have wronged myself greatly, and none forgives sins but You. So grant me forgiveness from Yourself and have mercy on me; You are the Oft-Forgiving, the Most Merciful."}, "ref": {"bn": "সহিহ বুখারি ৮৩৪; সহিহ মুসলিম ২৭০৫", "en": "Sahih al-Bukhari 834; Sahih Muslim 2705"}}, {"type": "arabic", "label": {"bn": "সালাম (প্রথমে ডানে, তারপর বামে)", "en": "Salam (right, then left)"}, "ar": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "pron": {"bn": "আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ।", "en": "As-salamu ''alaykum wa rahmatullah."}, "meaning": {"bn": "আপনাদের উপর শান্তি ও আল্লাহর রহমত বর্ষিত হোক।", "en": "Peace be upon you and the mercy of Allah."}, "ref": {"bn": "সহিহ মুসলিম ৫৮২; সুনান আবু দাউদ ৯৯৬", "en": "Sahih Muslim 582; Sunan Abi Dawud 996"}}, {"type": "heading", "text": {"bn": "এক নজরে", "en": "At a glance"}}, {"type": "table", "head": [{"bn": "রাকাত", "en": "Rakat"}, {"bn": "ফরজ নামাজে", "en": "In fard prayers"}, {"bn": "সুন্নত, নফল ও বিতরে", "en": "In sunnah, nafl and witr"}], "rows": [[{"bn": "১ম", "en": "1st"}, {"bn": "সানা, আউযুবিল্লাহ, বিসমিল্লাহ, ফাতিহা + সূরা", "en": "Thana, ta''awwudh, Bismillah, Al-Fatihah + surah"}, {"bn": "সানা, আউযুবিল্লাহ, বিসমিল্লাহ, ফাতিহা + সূরা", "en": "Thana, ta''awwudh, Bismillah, Al-Fatihah + surah"}], [{"bn": "২য়", "en": "2nd"}, {"bn": "বিসমিল্লাহ, ফাতিহা + সূরা; তারপর প্রথম বৈঠক (৩–৪ রাকাতে)", "en": "Bismillah, Al-Fatihah + surah; then the first sitting (in 3–4 rakat prayers)"}, {"bn": "বিসমিল্লাহ, ফাতিহা + সূরা; তারপর বৈঠক", "en": "Bismillah, Al-Fatihah + surah; then sitting"}], [{"bn": "৩য়", "en": "3rd"}, {"bn": "বিসমিল্লাহ, শুধু ফাতিহা", "en": "Bismillah, Al-Fatihah only"}, {"bn": "বিসমিল্লাহ, ফাতিহা + সূরা", "en": "Bismillah, Al-Fatihah + surah"}], [{"bn": "৪র্থ", "en": "4th"}, {"bn": "বিসমিল্লাহ, শুধু ফাতিহা; তারপর শেষ বৈঠক", "en": "Bismillah, Al-Fatihah only; then the final sitting"}, {"bn": "বিসমিল্লাহ, ফাতিহা + সূরা; তারপর শেষ বৈঠক", "en": "Bismillah, Al-Fatihah + surah; then the final sitting"}]]}, {"type": "heading", "text": {"bn": "কোন নামাজে শব্দ করে কিরাত", "en": "Which prayers are recited aloud"}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "ইমামের কিরাত", "en": "The imam''s recitation"}], "rows": [[{"bn": "ফজর", "en": "Fajr"}, {"bn": "দুই রাকাতেই শব্দ করে", "en": "Aloud in both rakats"}], [{"bn": "জোহর ও আসর", "en": "Zuhr and Asr"}, {"bn": "সব রাকাতে নিচু স্বরে", "en": "Quietly in all rakats"}], [{"bn": "মাগরিব", "en": "Maghrib"}, {"bn": "প্রথম দুই রাকাতে শব্দ করে, তৃতীয়তে নিচু স্বরে", "en": "Aloud in the first two, quietly in the third"}], [{"bn": "এশা", "en": "Isha"}, {"bn": "প্রথম দুই রাকাতে শব্দ করে, শেষ দুই রাকাতে নিচু স্বরে", "en": "Aloud in the first two, quietly in the last two"}], [{"bn": "জুমা, দুই ঈদ, তারাবিহ, রমজানে জামাতের বিতর", "en": "Jumu''ah, the two Eids, tarawih, witr in congregation in Ramadan"}, {"bn": "শব্দ করে", "en": "Aloud"}]]}, {"type": "note", "tone": "info", "text": {"bn": "একা নামাজ পড়লে জোহর-আসরে অবশ্যই নিচু স্বরে পড়বেন; ফজর, মাগরিব ও এশায় চাইলে শব্দ করে বা নিচু স্বরে পড়তে পারেন (হানাফি মত)। দিনের সুন্নত-নফলে নিচু স্বরে, রাতের নফলে দুটোই চলে।", "en": "Praying alone, recite quietly in Zuhr and Asr; in Fajr, Maghrib and Isha you may recite aloud or quietly (Hanafi view). Daytime sunnah and nafl are quiet; at night either is fine."}}, {"type": "note", "tone": "info", "text": {"bn": "হানাফি কিতাবে আছে: চার রাকাত সুন্নতে মুয়াক্কাদায় (যেমন জোহরের আগের চার রাকাত) প্রথম বৈঠকে শুধু তাশাহহুদ পড়বে। আর আসর ও এশার আগের চার রাকাতের মতো গায়রে মুয়াক্কাদা নামাজে প্রথম বৈঠকে দরুদ-দোয়াও পড়া যায় এবং তৃতীয় রাকাতে সানা দিয়ে শুরু করা মুস্তাহাব।", "en": "Hanafi books say: in four-rakat sunnah muakkadah (such as the four before Zuhr) only the tashahhud is recited in the first sitting. In ghair muakkadah ones (such as the four before Asr and Isha) the durood and dua may also be recited in the first sitting, and it is recommended to begin the third rakat with the thana."}}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '23f835fe-4dd6-50c9-a4c4-cc1dfc07e55f', id, 'short-surahs-takathur-to-kawthar', '{"bn": "নামাজের ছোট সূরা (১): তাকাসুর থেকে কাওসার", "en": "Short Surahs for Salah (1): At-Takathur to Al-Kawthar"}', '{"bn": "কুরআনের শেষ দিকের সাতটি ছোট সূরা — আরবি, উচ্চারণ ও অর্থসহ, মুসহাফের ক্রমে।", "en": "Seven short surahs from the end of the Quran, in Mushaf order, with Arabic, pronunciation and meaning."}', 'basic', '[{"type": "text", "text": {"bn": "নামাজে সূরা ফাতিহার পর যেকোনো সূরা বা কমপক্ষে ছোট তিন আয়াত পড়তে হয়। কুরআনের শেষ দিকের এই ছোট সূরাগুলো (সূরা ১০২–১১৪) সবচেয়ে বেশি মুখস্থ করা হয়। এই অংশে প্রথম সাতটি, পরের অংশে বাকি ছয়টি।", "en": "In salah, any surah or at least three short ayat are recited after Al-Fatihah. These short surahs at the end of the Quran (102–114) are the most commonly memorised. This guide has the first seven; the next has the remaining six."}}, {"type": "note", "tone": "tip", "text": {"bn": "দুই রাকাতে দুটি সূরা পড়লে মুসহাফের ক্রম রক্ষা করা উত্তম — যেমন প্রথম রাকাতে সূরা আসর, দ্বিতীয় রাকাতে সূরা কাওসার। উল্টো ক্রমে পড়লে নামাজ নষ্ট হয় না, তবে ইচ্ছাকৃতভাবে করা হানাফি মতে মাকরুহ।", "en": "When reciting two surahs in two rakats, it is better to keep the Mushaf order, e.g. Al-''Asr in the first and Al-Kawthar in the second. Reversing the order does not invalidate the prayer, though doing it deliberately is disliked in the Hanafi view."}}, {"type": "arabic", "label": {"bn": "সূরা তাকাসুর", "en": "Surah At-Takathur"}, "ar": "أَلْهَاكُمُ التَّكَاثُرُ ﴿١﴾ حَتَّىٰ زُرْتُمُ الْمَقَابِرَ ﴿٢﴾ كَلَّا سَوْفَ تَعْلَمُونَ ﴿٣﴾ ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ ﴿٤﴾ كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ ﴿٥﴾ لَتَرَوُنَّ الْجَحِيمَ ﴿٦﴾ ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ ﴿٧﴾ ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ ﴿٨﴾", "pron": {"bn": "আলহাকুমুত তাকাসুর। হাত্তা যুরতুমুল মাকাবির। কাল্লা সাওফা তা''লামুন। সুম্মা কাল্লা সাওফা তা''লামুন। কাল্লা লাও তা''লামুনা ইলমাল ইয়াকিন। লাতারাউন্নাল জাহিম। সুম্মা লাতারাউন্নাহা আইনাল ইয়াকিন। সুম্মা লাতুসআলুন্না ইয়াওমাইযিন আনিন নাইম।", "en": "Alhakumut-takathur. Hatta zurtumul-maqabir. Kalla sawfa ta''lamun. Thumma kalla sawfa ta''lamun. Kalla law ta''lamuna ''ilmal-yaqin. Latarawunnal-jahim. Thumma latarawunnaha ''aynal-yaqin. Thumma latus''alunna yawma''idhin ''anin-na''im."}, "meaning": {"bn": "বেশি পাওয়ার প্রতিযোগিতা তোমাদের (আল্লাহ থেকে) উদাসীন করে রেখেছে, যতক্ষণ না তোমরা কবরে পৌঁছে যাও। কখনো নয়! শীঘ্রই তোমরা জানতে পারবে। আবারও বলি, কখনো নয়! শীঘ্রই তোমরা জানতে পারবে। কখনো নয়! যদি তোমরা নিশ্চিত জ্ঞানে জানতে! তোমরা অবশ্যই জাহান্নাম দেখবে। তারপর তোমরা তা নিশ্চিত চোখে দেখবে। তারপর সেদিন তোমাদের অবশ্যই নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।", "en": "Competition for more distracts you, until you reach the graves. No! You will soon know. Again no! You will soon know. No! If only you knew with certain knowledge. You will surely see the Blazing Fire. Then you will surely see it with the eye of certainty. Then on that Day you will surely be asked about the blessings."}, "ref": {"bn": "সূরা তাকাসুর ১০২:১–৮", "en": "At-Takathur 102:1–8"}}, {"type": "arabic", "label": {"bn": "সূরা আসর", "en": "Surah Al-''Asr"}, "ar": "وَالْعَصْرِ ﴿١﴾ إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ ﴿٢﴾ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ ﴿٣﴾", "pron": {"bn": "ওয়াল আসর। ইন্নাল ইনসানা লাফি খুসর। ইল্লাল্লাযিনা আমানু ওয়া আমিলুস সালিহাতি ওয়া তাওয়াসাও বিল হাক্কি ওয়া তাওয়াসাও বিস সাবর।", "en": "Wal-''asr. Innal-insana lafi khusr. Illal-ladhina amanu wa ''amilus-salihati wa tawasaw bil-haqqi wa tawasaw bis-sabr."}, "meaning": {"bn": "সময়ের শপথ! নিশ্চয়ই মানুষ ক্ষতির মধ্যে আছে — তারা ছাড়া, যারা ঈমান এনেছে, সৎকাজ করেছে, পরস্পরকে সত্যের উপদেশ দিয়েছে এবং পরস্পরকে ধৈর্যের উপদেশ দিয়েছে।", "en": "By time! Surely mankind is in loss, except those who believe, do righteous deeds, and urge one another to the truth and urge one another to patience."}, "ref": {"bn": "সূরা আসর ১০৩:১–৩", "en": "Al-''Asr 103:1–3"}}, {"type": "arabic", "label": {"bn": "সূরা হুমাযাহ", "en": "Surah Al-Humazah"}, "ar": "وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ ﴿١﴾ الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ ﴿٢﴾ يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ ﴿٣﴾ كَلَّا ۖ لَيُنْبَذَنَّ فِي الْحُطَمَةِ ﴿٤﴾ وَمَا أَدْرَاكَ مَا الْحُطَمَةُ ﴿٥﴾ نَارُ اللَّهِ الْمُوقَدَةُ ﴿٦﴾ الَّتِي تَطَّلِعُ عَلَى الْأَفْئِدَةِ ﴿٧﴾ إِنَّهَا عَلَيْهِمْ مُؤْصَدَةٌ ﴿٨﴾ فِي عَمَدٍ مُمَدَّدَةٍ ﴿٩﴾", "pron": {"bn": "ওয়াইলুল লিকুল্লি হুমাযাতিল লুমাযাহ। আল্লাযি জামাআ মালাও ওয়া আদ্দাদাহ। ইয়াহসাবু আন্না মালাহু আখলাদাহ। কাল্লা, লাইউমবাযান্না ফিল হুতামাহ। ওয়ামা আদরাকা মাল হুতামাহ। নারুল্লাহিল মুকাদাহ। আল্লাতি তাত্তালিউ আলাল আফইদাহ। ইন্নাহা আলাইহিম মু''সাদাহ। ফি আমাদিম মুমাদ্দাদাহ।", "en": "Waylul-likulli humazatil-lumazah. Alladhi jama''a malan wa ''addadah. Yahsabu anna malahu akhladah. Kalla, layunbadhanna fil-hutamah. Wa ma adraka mal-hutamah. Narullahil-muqadah. Allati tattali''u ''alal-af''idah. Innaha ''alayhim mu''sadah. Fi ''amadim-mumaddadah."}, "meaning": {"bn": "দুর্ভোগ প্রত্যেক এমন ব্যক্তির জন্য, যে সামনে-পেছনে মানুষের নিন্দা করে; যে সম্পদ জমা করে আর বারবার গুনে রাখে। সে মনে করে তার সম্পদ তাকে চিরকাল বাঁচিয়ে রাখবে। কখনো নয়! তাকে অবশ্যই \"হুতামা\"য় নিক্ষেপ করা হবে। আপনি কি জানেন হুতামা কী? তা আল্লাহর প্রজ্বলিত আগুন, যা হৃদয় পর্যন্ত পৌঁছে যায়। নিশ্চয়ই তা তাদের উপর ঘিরে বন্ধ করে দেওয়া হবে — লম্বা লম্বা স্তম্ভে।", "en": "Woe to every slanderer and backbiter, who gathers wealth and keeps counting it, thinking his wealth will make him live forever. No! He will surely be thrown into the Crusher. And what will make you know what the Crusher is? It is the kindled Fire of Allah, which rises over the hearts. It will be closed over them, in extended columns."}, "ref": {"bn": "সূরা হুমাযাহ ১০৪:১–৯", "en": "Al-Humazah 104:1–9"}}, {"type": "arabic", "label": {"bn": "সূরা ফিল", "en": "Surah Al-Fil"}, "ar": "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ ﴿١﴾ أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ ﴿٢﴾ وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ ﴿٣﴾ تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ ﴿٤﴾ فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ ﴿٥﴾", "pron": {"bn": "আলাম তারা কাইফা ফাআলা রাব্বুকা বিআসহাবিল ফিল। আলাম ইয়াজআল কাইদাহুম ফি তাদলিল। ওয়া আরসালা আলাইহিম তাইরান আবাবিল। তারমিহিম বিহিজারাতিম মিন সিজ্জিল। ফাজাআলাহুম কাআসফিম মা''কুল।", "en": "Alam tara kayfa fa''ala rabbuka bi-ashabil-fil. Alam yaj''al kaydahum fi tadlil. Wa arsala ''alayhim tayran ababil. Tarmihim bihijaratim min sijjil. Faja''alahum ka''asfim ma''kul."}, "meaning": {"bn": "আপনি কি দেখেননি, আপনার রব হাতিওয়ালাদের সাথে কী করেছিলেন? তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি? তিনি তাদের উপর ঝাঁকে ঝাঁকে পাখি পাঠালেন, যারা তাদের উপর পোড়ামাটির পাথর ছুড়ছিল। ফলে তিনি তাদের করে দিলেন (পশুর) চিবানো ভুসির মতো।", "en": "Have you not seen how your Lord dealt with the people of the elephant? Did He not make their plan go astray? He sent against them birds in flocks, pelting them with stones of baked clay, and made them like chewed-up straw."}, "ref": {"bn": "সূরা ফিল ১০৫:১–৫", "en": "Al-Fil 105:1–5"}}, {"type": "arabic", "label": {"bn": "সূরা কুরাইশ", "en": "Surah Quraysh"}, "ar": "لِإِيلَافِ قُرَيْشٍ ﴿١﴾ إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ ﴿٢﴾ فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ ﴿٣﴾ الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ ﴿٤﴾", "pron": {"bn": "লিঈলাফি কুরাইশ। ঈলাফিহিম রিহলাতাশ শিতায়ি ওয়াস সাইফ। ফালইয়া''বুদু রাব্বা হাযাল বাইত। আল্লাযি আত''আমাহুম মিন জু'', ওয়া আমানাহুম মিন খাওফ।", "en": "Li-ilafi Quraysh. Ilafihim rihlatash-shita''i was-sayf. Falya''budu rabba hadhal-bayt. Alladhi at''amahum min ju'', wa amanahum min khawf."}, "meaning": {"bn": "কুরাইশের অভ্যস্ততার জন্য — শীত ও গ্রীষ্মের সফরে তাদের অভ্যস্ততার জন্য — তারা যেন এই ঘরের (কাবার) রবের ইবাদত করে, যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপদ রেখেছেন।", "en": "For the security of Quraysh, their security in the journeys of winter and summer, let them worship the Lord of this House, who fed them against hunger and made them safe from fear."}, "ref": {"bn": "সূরা কুরাইশ ১০৬:১–৪", "en": "Quraysh 106:1–4"}}, {"type": "arabic", "label": {"bn": "সূরা মাউন", "en": "Surah Al-Ma''un"}, "ar": "أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ ﴿١﴾ فَذَٰلِكَ الَّذِي يَدُعُّ الْيَتِيمَ ﴿٢﴾ وَلَا يَحُضُّ عَلَىٰ طَعَامِ الْمِسْكِينِ ﴿٣﴾ فَوَيْلٌ لِلْمُصَلِّينَ ﴿٤﴾ الَّذِينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَ ﴿٥﴾ الَّذِينَ هُمْ يُرَاءُونَ ﴿٦﴾ وَيَمْنَعُونَ الْمَاعُونَ ﴿٧﴾", "pron": {"bn": "আরাআইতাল্লাযি ইউকাযযিবু বিদ্দিন। ফাযালিকাল্লাযি ইয়াদু''উল ইয়াতিম। ওয়ালা ইয়াহুদ্দু আলা তাআমিল মিসকিন। ফাওয়াইলুল লিল মুসাল্লিন। আল্লাযিনা হুম আন সালাতিহিম সাহুন। আল্লাযিনা হুম ইউরাউন। ওয়া ইয়ামনাউনাল মাউন।", "en": "Ara''aytal-ladhi yukadhdhibu bid-din. Fadhalikal-ladhi yadu''''ul-yatim. Wa la yahuddu ''ala ta''amil-miskin. Fawaylul-lil-musallin. Alladhina hum ''an salatihim sahun. Alladhina hum yura''un. Wa yamna''unal-ma''un."}, "meaning": {"bn": "আপনি কি তাকে দেখেছেন, যে প্রতিদান দিবসকে অস্বীকার করে? সে-ই তো এতিমকে রূঢ়ভাবে তাড়িয়ে দেয় এবং মিসকিনকে খাবার দিতে উৎসাহ দেয় না। অতএব দুর্ভোগ সেই নামাজিদের জন্য, যারা নিজেদের নামাজের ব্যাপারে উদাসীন, যারা লোক দেখানোর জন্য কাজ করে, এবং ছোটখাটো প্রয়োজনীয় জিনিস দিতেও নিষেধ করে।", "en": "Have you seen the one who denies the Judgement? That is the one who pushes away the orphan and does not urge the feeding of the poor. So woe to those who pray, who are heedless of their prayer, who only show off, and who withhold small kindnesses."}, "ref": {"bn": "সূরা মাউন ১০৭:১–৭", "en": "Al-Ma''un 107:1–7"}}, {"type": "arabic", "label": {"bn": "সূরা কাওসার", "en": "Surah Al-Kawthar"}, "ar": "إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ﴿١﴾ فَصَلِّ لِرَبِّكَ وَانْحَرْ ﴿٢﴾ إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ ﴿٣﴾", "pron": {"bn": "ইন্না আ''তাইনাকাল কাওসার। ফাসাল্লি লিরাব্বিকা ওয়ানহার। ইন্না শানিআকা হুয়াল আবতার।", "en": "Inna a''taynakal-kawthar. Fasalli lirabbika wanhar. Inna shani''aka huwal-abtar."}, "meaning": {"bn": "নিশ্চয়ই আমি আপনাকে কাওসার দান করেছি। অতএব আপনার রবের উদ্দেশে নামাজ পড়ুন এবং কুরবানি করুন। নিশ্চয়ই আপনার শত্রুই শিকড়কাটা (নির্বংশ)।", "en": "Indeed, We have given you al-Kawthar. So pray to your Lord and sacrifice. Indeed, it is your enemy who is cut off."}, "ref": {"bn": "সূরা কাওসার ১০৮:১–৩", "en": "Al-Kawthar 108:1–3"}}, {"type": "note", "tone": "tip", "text": {"bn": "উচ্চারণ শুধু সহায়ক। সঠিক মাখরাজ ও তাজবিদসহ তিলাওয়াত একজন শিক্ষকের কাছে শুনে শুনে শিখুন — এই অ্যাপের কুরআন অংশে তিলাওয়াত শুনেও অনুশীলন করতে পারেন।", "en": "Transliteration is only an aid. Learn proper articulation and tajwid by listening to a teacher; you can also practise with the recitations in the Quran section of this app."}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'bd79a8c8-4be8-5306-ac5c-e12151ff7ab7', id, 'short-surahs-kafirun-to-nas', '{"bn": "নামাজের ছোট সূরা (২): কাফিরুন থেকে নাস", "en": "Short Surahs for Salah (2): Al-Kafirun to An-Nas"}', '{"bn": "কুরআনের শেষ ছয়টি সূরা — আরবি, উচ্চারণ ও অর্থসহ, সাথে সহিহ হাদিসে বর্ণিত কিছু ফজিলত।", "en": "The last six surahs of the Quran with Arabic, pronunciation and meaning, plus some virtues from authentic hadith."}', 'basic', '[{"type": "arabic", "label": {"bn": "সূরা কাফিরুন", "en": "Surah Al-Kafirun"}, "ar": "قُلْ يَا أَيُّهَا الْكَافِرُونَ ﴿١﴾ لَا أَعْبُدُ مَا تَعْبُدُونَ ﴿٢﴾ وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٣﴾ وَلَا أَنَا عَابِدٌ مَا عَبَدْتُمْ ﴿٤﴾ وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٥﴾ لَكُمْ دِينُكُمْ وَلِيَ دِينِ ﴿٦﴾", "pron": {"bn": "কুল ইয়া আইয়্যুহাল কাফিরুন। লা আ''বুদু মা তা''বুদুন। ওয়ালা আনতুম আবিদুনা মা আ''বুদ। ওয়ালা আনা আবিদুম মা আবাদতুম। ওয়ালা আনতুম আবিদুনা মা আ''বুদ। লাকুম দিনুকুম ওয়ালিয়া দিন।", "en": "Qul ya ayyuhal-kafirun. La a''budu ma ta''budun. Wa la antum ''abiduna ma a''bud. Wa la ana ''abidum ma ''abadtum. Wa la antum ''abiduna ma a''bud. Lakum dinukum wa liya din."}, "meaning": {"bn": "বলুন, হে কাফিররা! তোমরা যার ইবাদত করো, আমি তার ইবাদত করি না। আর আমি যাঁর ইবাদত করি, তোমরা তাঁর ইবাদতকারী নও। আর তোমরা যার ইবাদত করেছ, আমি তার ইবাদতকারী হব না। আর আমি যাঁর ইবাদত করি, তোমরা তাঁর ইবাদতকারী নও। তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন।", "en": "Say: O disbelievers, I do not worship what you worship, nor do you worship what I worship. Nor will I worship what you have worshipped, nor will you worship what I worship. To you your religion, and to me mine."}, "ref": {"bn": "সূরা কাফিরুন ১০৯:১–৬", "en": "Al-Kafirun 109:1–6"}}, {"type": "note", "tone": "info", "text": {"bn": "রাসুলুল্লাহ ﷺ ফজরের দুই রাকাত সুন্নতে সূরা কাফিরুন ও সূরা ইখলাস পড়তেন (সহিহ মুসলিম ৭২৬)।", "en": "The Prophet ﷺ recited Al-Kafirun and Al-Ikhlas in the two sunnah rakats of Fajr (Sahih Muslim 726)."}}, {"type": "arabic", "label": {"bn": "সূরা নাসর", "en": "Surah An-Nasr"}, "ar": "إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ﴿١﴾ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا ﴿٢﴾ فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ ۚ إِنَّهُ كَانَ تَوَّابًا ﴿٣﴾", "pron": {"bn": "ইযা জাআ নাসরুল্লাহি ওয়াল ফাতহ। ওয়া রাআইতান নাসা ইয়াদখুলুনা ফি দিনিল্লাহি আফওয়াজা। ফাসাব্বিহ বিহামদি রাব্বিকা ওয়াসতাগফিরহ, ইন্নাহু কানা তাওয়াবা।", "en": "Idha ja''a nasrullahi wal-fath. Wa ra''aytan-nasa yadkhuluna fi dinillahi afwaja. Fasabbih bihamdi rabbika wastaghfirh, innahu kana tawwaba."}, "meaning": {"bn": "যখন আল্লাহর সাহায্য ও বিজয় আসবে, এবং আপনি দেখবেন মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে, তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান। নিশ্চয়ই তিনি তওবা কবুলকারী।", "en": "When the help of Allah and victory come, and you see people entering Allah''s religion in crowds, then glorify your Lord with praise and seek His forgiveness. Indeed, He ever accepts repentance."}, "ref": {"bn": "সূরা নাসর ১১০:১–৩", "en": "An-Nasr 110:1–3"}}, {"type": "arabic", "label": {"bn": "সূরা লাহাব (মাসাদ)", "en": "Surah Al-Masad"}, "ar": "تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ ﴿١﴾ مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ ﴿٢﴾ سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ ﴿٣﴾ وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ ﴿٤﴾ فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ ﴿٥﴾", "pron": {"bn": "তাব্বাত ইয়াদা আবি লাহাবিও ওয়া তাব্ব। মা আগনা আনহু মালুহু ওয়ামা কাসাব। সাইয়াসলা নারান যাতা লাহাব। ওয়ামরাআতুহু হাম্মালাতাল হাতাব। ফি জিদিহা হাবলুম মিম মাসাদ।", "en": "Tabbat yada Abi Lahabin wa tabb. Ma aghna ''anhu maluhu wa ma kasab. Sayasla naran dhata lahab. Wamra''atuhu hammalatal-hatab. Fi jidiha hablum mim masad."}, "meaning": {"bn": "আবু লাহাবের দুই হাত ধ্বংস হোক, এবং সে নিজেও ধ্বংস হয়েছে। তার সম্পদ ও তার উপার্জন তার কোনো কাজে আসেনি। শীঘ্রই সে লেলিহান আগুনে প্রবেশ করবে, এবং তার স্ত্রীও — যে কাঠ বহন করত (কুৎসা ছড়াত)। তার গলায় থাকবে খেজুর-আঁশের পাকানো রশি।", "en": "Perish the hands of Abu Lahab, and perish he! His wealth and what he earned did not avail him. He will burn in a Fire of blazing flame, and his wife too, the carrier of firewood, with a rope of twisted fibre around her neck."}, "ref": {"bn": "সূরা লাহাব (মাসাদ) ১১১:১–৫", "en": "Al-Masad 111:1–5"}}, {"type": "arabic", "label": {"bn": "সূরা ইখলাস", "en": "Surah Al-Ikhlas"}, "ar": "قُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾", "pron": {"bn": "কুল হুয়াল্লাহু আহাদ। আল্লাহুস সামাদ। লাম ইয়ালিদ ওয়া লাম ইউলাদ। ওয়া লাম ইয়াকুল লাহু কুফুওয়ান আহাদ।", "en": "Qul huwallahu ahad. Allahus-samad. Lam yalid wa lam yulad. Wa lam yakul-lahu kufuwan ahad."}, "meaning": {"bn": "বলুন, তিনিই আল্লাহ, এক ও অদ্বিতীয়। আল্লাহ কারো মুখাপেক্ষী নন, সবাই তাঁর মুখাপেক্ষী। তিনি কাউকে জন্ম দেননি এবং কেউ তাঁকে জন্ম দেয়নি। আর তাঁর সমকক্ষ কেউ নেই।", "en": "Say: He is Allah, the One. Allah, the Self-Sufficient on whom all depend. He neither begets nor was He begotten. And there is none comparable to Him."}, "ref": {"bn": "সূরা ইখলাস ১১২:১–৪", "en": "Al-Ikhlas 112:1–4"}}, {"type": "note", "tone": "info", "text": {"bn": "সূরা ইখলাস কুরআনের এক-তৃতীয়াংশের সমান (সহিহ বুখারি ৫০১৩; সহিহ মুসলিম ৮১১)।", "en": "Surah Al-Ikhlas equals a third of the Quran (Sahih al-Bukhari 5013; Sahih Muslim 811)."}}, {"type": "arabic", "label": {"bn": "সূরা ফালাক", "en": "Surah Al-Falaq"}, "ar": "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾ مِنْ شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾", "pron": {"bn": "কুল আউযু বিরাব্বিল ফালাক। মিন শাররি মা খালাক। ওয়া মিন শাররি গাসিকিন ইযা ওয়াকাব। ওয়া মিন শাররিন নাফফাসাতি ফিল উকাদ। ওয়া মিন শাররি হাসিদিন ইযা হাসাদ।", "en": "Qul a''udhu birabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-''uqad. Wa min sharri hasidin idha hasad."}, "meaning": {"bn": "বলুন, আমি আশ্রয় চাই ভোরের রবের কাছে — তিনি যা সৃষ্টি করেছেন তার অনিষ্ট থেকে, অন্ধকার রাতের অনিষ্ট থেকে যখন তা ছেয়ে যায়, গিঁটে ফুঁ দেওয়া জাদুকারিণীদের অনিষ্ট থেকে, এবং হিংসুকের অনিষ্ট থেকে যখন সে হিংসা করে।", "en": "Say: I seek refuge with the Lord of daybreak, from the evil of what He created, from the evil of darkness when it settles, from the evil of those who blow on knots, and from the evil of an envier when he envies."}, "ref": {"bn": "সূরা ফালাক ১১৩:১–৫", "en": "Al-Falaq 113:1–5"}}, {"type": "arabic", "label": {"bn": "সূরা নাস", "en": "Surah An-Nas"}, "ar": "قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾ مَلِكِ النَّاسِ ﴿٢﴾ إِلَٰهِ النَّاسِ ﴿٣﴾ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾", "pron": {"bn": "কুল আউযু বিরাব্বিন নাস। মালিকিন নাস। ইলাহিন নাস। মিন শাররিল ওয়াসওয়াসিল খান্নাস। আল্লাযি ইউওয়াসউইসু ফি সুদুরিন নাস। মিনাল জিন্নাতি ওয়ান নাস।", "en": "Qul a''udhu birabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas."}, "meaning": {"bn": "বলুন, আমি আশ্রয় চাই মানুষের রবের কাছে, মানুষের অধিপতির কাছে, মানুষের ইলাহের কাছে — সেই কুমন্ত্রণাদাতার অনিষ্ট থেকে, যে (আল্লাহর স্মরণে) পিছিয়ে যায়, যে মানুষের অন্তরে কুমন্ত্রণা দেয় — জিনদের মধ্য থেকে হোক বা মানুষের মধ্য থেকে।", "en": "Say: I seek refuge with the Lord of mankind, the King of mankind, the God of mankind, from the evil of the whisperer who withdraws, who whispers into the hearts of mankind, from among the jinn and mankind."}, "ref": {"bn": "সূরা নাস ১১৪:১–৬", "en": "An-Nas 114:1–6"}}, {"type": "note", "tone": "info", "text": {"bn": "সূরা ফালাক ও নাস সম্পর্কে রাসুলুল্লাহ ﷺ বলেছেন, এমন আয়াত আর কখনো দেখা যায়নি (সহিহ মুসলিম ৮১৪)। প্রতি নামাজের পর এই সূরাগুলো (মুআওয়িযাত) পড়ার কথাও হাদিসে আছে (সুনান আবু দাউদ ১৫২৩)।", "en": "The Prophet ﷺ said of Al-Falaq and An-Nas that verses like them had never been seen (Sahih Muslim 814). Reciting these protective surahs after every prayer is also in the hadith (Sunan Abi Dawud 1523)."}}]', 'in_review', 90 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'fffa2555-7286-546d-9016-2b51e73e245a', id, 'salah-after-dhikr', '{"bn": "নামাজের পরের জিকির ও দোয়া", "en": "Dhikr and Duas after Salah"}', '{"bn": "সালাম ফেরানোর পর রাসুলুল্লাহ ﷺ যেসব জিকির ও দোয়া পড়তেন — ইস্তিগফার, আয়াতুল কুরসি, তাসবিহ ইত্যাদি।", "en": "The dhikr and duas the Prophet ﷺ said after the salam: istighfar, Ayat al-Kursi, tasbih and more."}', 'basic', '[{"type": "text", "text": {"bn": "ফরজ নামাজের সালাম ফেরানোর পর কিছুক্ষণ বসে আল্লাহর জিকির করা সুন্নত। নিচের জিকিরগুলো সহিহ হাদিস থেকে নেওয়া; সবগুলো একসাথে না পারলে যতটুকু পারেন নিয়মিত পড়ুন।", "en": "After the salam of a fard prayer it is sunnah to sit a little and remember Allah. The dhikr below come from authentic hadith; if you cannot do them all, keep regularly to what you can."}}, {"type": "arabic", "label": {"bn": "ইস্তিগফার — ৩ বার", "en": "Istighfar: 3 times"}, "ar": "أَسْتَغْفِرُ اللَّهَ", "pron": {"bn": "আসতাগফিরুল্লাহ", "en": "Astaghfirullah"}, "meaning": {"bn": "আমি আল্লাহর কাছে ক্ষমা চাই।", "en": "I seek Allah''s forgiveness."}, "ref": {"bn": "সহিহ মুসলিম ৫৯১", "en": "Sahih Muslim 591"}}, {"type": "arabic", "label": {"bn": "ইস্তিগফারের পর", "en": "After the istighfar"}, "ar": "اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ", "pron": {"bn": "আল্লাহুম্মা আনতাস সালাম, ওয়া মিনকাস সালাম, তাবারাকতা ইয়া যাল জালালি ওয়াল ইকরাম।", "en": "Allahumma antas-salam, wa minkas-salam, tabarakta ya dhal-jalali wal-ikram."}, "meaning": {"bn": "হে আল্লাহ! আপনিই শান্তি, আপনার কাছ থেকেই শান্তি। হে মহিমা ও সম্মানের অধিকারী! আপনি বরকতময়।", "en": "O Allah, You are Peace and from You is peace. Blessed are You, O Possessor of majesty and honour."}, "ref": {"bn": "সহিহ মুসলিম ৫৯১", "en": "Sahih Muslim 591"}}, {"type": "arabic", "ar": "لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ", "pron": {"bn": "লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়া হুয়া আলা কুল্লি শাইয়িন কাদির। আল্লাহুম্মা লা মানিআ লিমা আ''তাইতা, ওয়ালা মু''তিয়া লিমা মানা''তা, ওয়ালা ইয়ানফাউ যাল জাদ্দি মিনকাল জাদ্দ।", "en": "La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir. Allahumma la mani''a lima a''tayta, wa la mu''tiya lima mana''ta, wa la yanfa''u dhal-jaddi minkal-jadd."}, "meaning": {"bn": "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; রাজত্ব তাঁরই, প্রশংসাও তাঁরই, তিনি সবকিছুর উপর ক্ষমতাবান। হে আল্লাহ! আপনি যা দেন তা কেউ আটকাতে পারে না, আর আপনি যা আটকান তা কেউ দিতে পারে না; আর কোনো সম্পদশালীর সম্পদ আপনার কাছে তার কোনো উপকারে আসে না।", "en": "There is no god but Allah alone, with no partner; His is the dominion and His the praise, and He has power over all things. O Allah, none can withhold what You give, none can give what You withhold, and the wealth of the wealthy is of no avail against You."}, "ref": {"bn": "সহিহ বুখারি ৮৪৪; সহিহ মুসলিম ৫৯৩", "en": "Sahih al-Bukhari 844; Sahih Muslim 593"}}, {"type": "heading", "text": {"bn": "তাসবিহ, তাহমিদ ও তাকবির", "en": "Tasbih, tahmid and takbir"}}, {"type": "arabic", "label": {"bn": "৩৩ বার", "en": "33 times"}, "ar": "سُبْحَانَ اللَّهِ", "pron": {"bn": "সুবহানাল্লাহ", "en": "Subhanallah"}, "meaning": {"bn": "আল্লাহ পবিত্র।", "en": "Glory be to Allah."}}, {"type": "arabic", "label": {"bn": "৩৩ বার", "en": "33 times"}, "ar": "الْحَمْدُ لِلَّهِ", "pron": {"bn": "আলহামদুলিল্লাহ", "en": "Alhamdulillah"}, "meaning": {"bn": "সকল প্রশংসা আল্লাহর।", "en": "All praise is for Allah."}}, {"type": "arabic", "label": {"bn": "৩৪ বার", "en": "34 times"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}, "ref": {"bn": "সহিহ মুসলিম ৫৯৬", "en": "Sahih Muslim 596"}}, {"type": "note", "tone": "info", "text": {"bn": "আরেকটি সহিহ পদ্ধতি: সুবহানাল্লাহ, আলহামদুলিল্লাহ ও আল্লাহু আকবার ৩৩ বার করে, তারপর একবার \"লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়া হুয়া আলা কুল্লি শাইয়িন কাদির\" বলে ১০০ পূর্ণ করা। হাদিসে আছে, এতে সমুদ্রের ফেনার সমান গুনাহও মাফ হয় (সহিহ মুসলিম ৫৯৭)।", "en": "Another authentic way: 33 each of Subhanallah, Alhamdulillah and Allahu akbar, then completing 100 with \"La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir\". The hadith says sins are forgiven even if like the foam of the sea (Sahih Muslim 597)."}}, {"type": "heading", "text": {"bn": "আয়াতুল কুরসি", "en": "Ayat al-Kursi"}}, {"type": "arabic", "label": {"bn": "আয়াতুল কুরসি — প্রতি ফরজ নামাজের পর", "en": "Ayat al-Kursi: after every fard prayer"}, "ar": "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ", "pron": {"bn": "আল্লাহু লা ইলাহা ইল্লা হুয়াল হাইয়্যুল কাইয়্যুম। লা তা''খুযুহু সিনাতুও ওয়ালা নাওম। লাহু মা ফিস সামাওয়াতি ওয়ামা ফিল আরদ। মান যাল্লাযি ইয়াশফাউ ইনদাহু ইল্লা বিইযনিহ। ইয়া''লামু মা বাইনা আইদিহিম ওয়ামা খালফাহুম। ওয়ালা ইউহিতুনা বিশাইয়িম মিন ইলমিহি ইল্লা বিমা শাআ। ওয়াসিআ কুরসিইয়্যুহুস সামাওয়াতি ওয়াল আরদ। ওয়ালা ইয়াউদুহু হিফযুহুমা, ওয়া হুয়াল আলিইয়্যুল আযিম।", "en": "Allahu la ilaha illa huwal-hayyul-qayyum. La ta''khudhuhu sinatun wa la nawm. Lahu ma fis-samawati wa ma fil-ard. Man dhal-ladhi yashfa''u ''indahu illa bi-idhnih. Ya''lamu ma bayna aydihim wa ma khalfahum. Wa la yuhituna bishay''im min ''ilmihi illa bima sha''. Wasi''a kursiyyuhus-samawati wal-ard. Wa la ya''uduhu hifzuhuma, wa huwal-''aliyyul-''azim."}, "meaning": {"bn": "আল্লাহ, তিনি ছাড়া কোনো ইলাহ নেই; তিনি চিরঞ্জীব, সবকিছুর ধারক। তাঁকে তন্দ্রাও স্পর্শ করে না, নিদ্রাও না। আসমান ও জমিনে যা কিছু আছে সব তাঁরই। কে আছে যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করবে? তাদের সামনে ও পেছনে যা আছে তিনি সব জানেন। তিনি যতটুকু চান, তার বাইরে তাঁর জ্ঞানের কিছুই তারা আয়ত্ত করতে পারে না। তাঁর কুরসি আসমান ও জমিন পরিব্যাপ্ত। এ দুটির রক্ষণাবেক্ষণ তাঁকে ক্লান্ত করে না। তিনি সর্বোচ্চ, মহান।", "en": "Allah: there is no god but Him, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him. To Him belongs whatever is in the heavens and the earth. Who can intercede with Him except by His permission? He knows what is before them and behind them, and they encompass nothing of His knowledge except what He wills. His Kursi extends over the heavens and the earth, and preserving them does not tire Him. He is the Most High, the Most Great."}, "ref": {"bn": "সূরা বাকারা ২:২৫৫", "en": "Al-Baqarah 2:255"}}, {"type": "ref", "text": {"bn": "প্রতি ফরজ নামাজের পর আয়াতুল কুরসি পড়ার ফজিলত: আবু উমামা (রা.) থেকে বর্ণিত — সুনানে নাসায়ি আল-কুবরা (ইবনে হিব্বান ও অন্যরা সহিহ বলেছেন)", "en": "The virtue of Ayat al-Kursi after every obligatory prayer: narrated by Abu Umamah (RA) in as-Sunan al-Kubra of an-Nasa''i (graded authentic by Ibn Hibban and others)"}, "check": true}, {"type": "heading", "text": {"bn": "আরও কিছু দোয়া", "en": "More duas"}}, {"type": "arabic", "label": {"bn": "প্রতি নামাজের শেষে — মুআয (রা.)-কে শেখানো", "en": "At the end of every prayer: taught to Mu''adh (RA)"}, "ar": "اللَّهُمَّ أَعِنِّي عَلَىٰ ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ", "pron": {"bn": "আল্লাহুম্মা আইন্নি আলা যিকরিকা ওয়া শুকরিকা ওয়া হুসনি ইবাদাতিক।", "en": "Allahumma a''inni ''ala dhikrika wa shukrika wa husni ''ibadatik."}, "meaning": {"bn": "হে আল্লাহ! আপনার জিকির, আপনার শুকরিয়া এবং সুন্দরভাবে আপনার ইবাদত করতে আমাকে সাহায্য করুন।", "en": "O Allah, help me to remember You, to thank You, and to worship You well."}, "ref": {"bn": "সুনান আবু দাউদ ১৫২২", "en": "Sunan Abi Dawud 1522"}}, {"type": "text", "text": {"bn": "প্রতি নামাজের পর সূরা ইখলাস, ফালাক ও নাস (মুআওয়িযাত) পড়ার কথা হাদিসে আছে (সুনান আবু দাউদ ১৫২৩)। সূরাগুলো \"নামাজের ছোট সূরা (২)\" অংশে আরবি ও অর্থসহ দেওয়া আছে।", "en": "Reciting Al-Ikhlas, Al-Falaq and An-Nas after every prayer is in the hadith (Sunan Abi Dawud 1523). They are in \"Short Surahs for Salah (2)\" with Arabic and meaning."}}, {"type": "note", "tone": "info", "text": {"bn": "ফরজ নামাজের পর দোয়া কবুলের আশাব্যঞ্জক সময় বলে হাদিসে এসেছে (সুনান তিরমিযি), তাই নিজের ভাষায় আল্লাহর কাছে চাইতে পারেন। ফরজের পর ইমাম-মুক্তাদি সবাই মিলে নিয়মিত হাত তুলে সম্মিলিত মুনাজাত করা নিয়ে আলেমদের মধ্যে মতপার্থক্য আছে; ব্যক্তিগতভাবে দোয়া করা সবার মতেই জায়েজ।", "en": "The hadith mentions the end of obligatory prayers as a time when dua is hoped to be answered (Jami at-Tirmidhi), so ask Allah in your own words. Scholars differ on a regular collective dua with raised hands by imam and congregation after every fard; individual dua is permitted by all."}, "check": true}]', 'in_review', 100 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '97892482-552a-5fa8-b888-3fb2556d4498', id, 'salah-women', '{"bn": "নারীদের নামাজ", "en": "Women''s Salah"}', '{"bn": "নারী-পুরুষের নামাজ মূলত এক; যেসব বিষয়ে পার্থক্য আছে এবং যেসব বিষয়ে আলেমদের মতপার্থক্য — নিরপেক্ষভাবে।", "en": "Men''s and women''s salah are essentially the same; the points that differ, and where scholars hold different views, presented neutrally."}', 'detail', '[{"type": "text", "text": {"bn": "নারী ও পুরুষের নামাজের ফরজ, ওয়াজিব, রাকাত সংখ্যা এবং পড়ার দোয়া-সূরা সব এক। \"দুই রাকাত নামাজ\" অংশে যা আছে, নারীরাও তা-ই পড়বেন। পার্থক্য মূলত সতর ঢাকা ও পর্দা সংক্রান্ত, আর কিছু দাঁড়ানো-বসার ভঙ্গিতে — যেখানে আলেমদের মতপার্থক্য আছে।", "en": "The fard and wajib acts, the number of rakats and the recitations are the same for men and women; women pray what is in \"How to Pray Two Rakats\". The differences concern covering and modesty, and some postures, where scholars differ."}}, {"type": "heading", "text": {"bn": "যেসব বিষয়ে আলেমরা একমত", "en": "Points that are agreed"}}, {"type": "list", "items": [{"bn": "নামাজে নারীর সতর: মুখমণ্ডল ও দুই হাত ছাড়া পুরো শরীর (হানাফি মতে দুই পা-ও সতরের বাইরে)। মাথার চুল ঢাকা জরুরি।", "en": "A woman''s awrah in salah is the whole body except the face and hands (Hanafis also exclude the feet). The hair must be covered."}, {"bn": "নারীদের জন্য ঘরে নামাজ পড়া উত্তম, তবে মসজিদে যাওয়া নিষেধ নয়।", "en": "Praying at home is better for women, but they are not forbidden from the mosque."}, {"bn": "জামাতে নারীদের কাতার পুরুষদের পেছনে।", "en": "In congregation, women''s rows are behind the men''s."}, {"bn": "ইমাম ভুল করলে পুরুষরা \"সুবহানাল্লাহ\" বলবে, নারীরা হাতের উপর হাত মেরে শব্দ করবে।", "en": "To alert the imam to a mistake, men say \"Subhanallah\" and women clap one hand on the other."}, {"bn": "জুমার নামাজ নারীদের উপর ফরজ নয়; তারা ঘরে জোহর পড়বেন (জুমায় অংশ নিলে তা-ও আদায় হয়ে যায়)।", "en": "Jumu''ah is not obligatory for women; they pray Zuhr at home (if they attend Jumu''ah, it counts)."}, {"bn": "হায়েজ-নিফাসের সময় নামাজ মাফ, পরে কাজা করতে হয় না।", "en": "Prayer is excused during menses and post-natal bleeding and is not made up."}]}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৬৪১ (ওড়না ছাড়া প্রাপ্তবয়স্ক নারীর নামাজ কবুল হয় না); সুনান আবু দাউদ ৫৬৭ ও সহিহ বুখারি ৯০০ (মসজিদে যাওয়া); সহিহ মুসলিম ৪৪০ (কাতার); সহিহ বুখারি ১২০৩ (তাসবিহ ও হাততালি); সুনান আবু দাউদ ১০৬৭ (জুমা)", "en": "Sunan Abi Dawud 641 (no prayer of an adult woman without a head covering); Sunan Abi Dawud 567 and Sahih al-Bukhari 900 (the mosque); Sahih Muslim 440 (rows); Sahih al-Bukhari 1203 (tasbih and clapping); Sunan Abi Dawud 1067 (Jumu''ah)"}}, {"type": "differ", "title": {"bn": "নামাজের ভঙ্গিতে নারী-পুরুষের পার্থক্য আছে কি?", "en": "Do women''s postures in salah differ from men''s?"}, "views": [{"label": {"bn": "হানাফি (এবং চার মাযহাবের অনেক ফকিহ — বিস্তারিত ভিন্নতাসহ)", "en": "Hanafi (and many jurists of the four madhhabs, with differing details)"}, "text": {"bn": "নারীরা পর্দা ও সংযমের জন্য শরীর গুটিয়ে নামাজ পড়বেন। হানাফি পদ্ধতি: তাকবিরে তাহরিমায় হাত কাঁধ পর্যন্ত ওঠানো; বুকের উপর হাত রাখা; রুকুতে সামান্য ঝোঁকা, আঙুল মিলিয়ে রাখা; সিজদায় পেট উরুর সাথে ও বাহু পাঁজরের সাথে মিলিয়ে, কনুইসহ হাত মাটিতে বিছিয়ে জড়োসড়ো হয়ে থাকা; বৈঠকে দুই পা ডান দিকে বের করে বাম নিতম্বের উপর বসা।", "en": "Women pray in a more compact way for modesty. The Hanafi method: raising the hands to the shoulders at the opening takbir; placing the hands on the chest; bending less in ruku with fingers together; in sujud keeping the belly against the thighs and the arms against the sides, forearms on the ground, body drawn together; in the sitting, both feet out to the right, sitting on the left hip."}, "evidence": {"bn": "রাসুলুল্লাহ ﷺ নামাজরত দুই নারীকে সিজদায় শরীর মাটির সাথে মিলিয়ে রাখতে বলেছেন — ইয়াযিদ ইবনে আবি হাবিবের মুরসাল বর্ণনা (মারাসিলে আবু দাউদ; সুনানুল কুবরা, বায়হাকি); আলি ও ইবনে আব্বাস (রা.)-সহ কয়েকজন সাহাবি ও তাবেয়ির বক্তব্য (মুসান্নাফ ইবনে আবি শাইবা); নারীর জন্য পর্দার সাধারণ নীতি, যাতে সবাই একমত।", "en": "The Prophet ﷺ told two women praying to draw their bodies to the ground in sujud: a mursal report of Yazid ibn Abi Habib (Marasil Abi Dawud; al-Bayhaqi''s as-Sunan al-Kubra); statements of Ali, Ibn Abbas (RA) and other early authorities (Musannaf Ibn Abi Shaybah); and the agreed general principle of modesty for women."}}, {"label": {"bn": "অনেক মুহাদ্দিস ও আহলে হাদিস আলেম", "en": "Many hadith scholars and Ahl al-Hadith scholars"}, "text": {"bn": "সতর ও আওয়াজ সংক্রান্ত প্রমাণিত পার্থক্য ছাড়া নারী-পুরুষের নামাজের ভঙ্গি একই; নারীরাও পুরুষদের মতো হাত ওঠাবেন, বাঁধবেন, রুকু-সিজদা করবেন ও বসবেন।", "en": "Apart from the established differences in covering and voice, the postures are the same: women raise and place the hands, bow, prostrate and sit as men do."}, "evidence": {"bn": "\"তোমরা আমাকে যেভাবে নামাজ পড়তে দেখেছ, সেভাবে পড়ো\" — সহিহ বুখারি ৬৩১, যা নারী-পুরুষ সবার জন্য সাধারণ; উম্মুদ দারদা (রহ.) পুরুষের মতো বসতেন, আর তিনি ফকিহ ছিলেন — সহিহ বুখারি (তাশাহহুদে বসার অধ্যায়ে মুআল্লাক বর্ণনা); তারা পার্থক্যের বর্ণনাগুলোকে মুরসাল বা দুর্বল মনে করেন।", "en": "\"Pray as you have seen me praying\" (Sahih al-Bukhari 631), addressed to all; Umm ad-Darda, a jurist, sat in prayer as men sit (Sahih al-Bukhari, an unconnected report in the chapter on sitting in the tashahhud); they regard the reports of difference as mursal or weak."}}], "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "যে মতই অনুসরণ করুন, নামাজ সহিহ হবে। আপনার আস্থাভাজন আলেম যেভাবে শেখান সেভাবে পড়ুন, এবং এ নিয়ে অন্যের সাথে বিবাদে জড়াবেন না। মনোযোগ, সময়মতো আদায় ও সতর ঠিক রাখা — এগুলোই বেশি গুরুত্বপূর্ণ।", "en": "Whichever view you follow, your prayer is valid. Pray as your trusted scholar teaches and do not quarrel with others over it. Focus, praying on time and proper covering matter far more."}}, {"type": "note", "tone": "info", "text": {"bn": "যেখানে গায়রে মাহরাম পুরুষ শুনতে পায়, সেখানে নারীরা কিরাত শব্দ করে পড়বেন না — এটাই অধিকাংশ আলেমের মত। নারীরা নারীদের জামাত করলে ইমাম সামনে না দাঁড়িয়ে প্রথম কাতারের মাঝখানে দাঁড়াবেন।", "en": "Women do not recite aloud where non-mahram men can hear; this is the view of most scholars. When women pray in a women-only congregation, the woman leading stands in the middle of the first row rather than in front."}}]', 'in_review', 110 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '45e3cce3-bacf-5944-baa8-990c74627445', id, 'salah-points-of-difference', '{"bn": "নামাজে মতপার্থক্যের বিষয়গুলো", "en": "Points of Difference in Salah"}', '{"bn": "হাত ওঠানো (রাফয়ে ইয়াদাইন), হাত বাঁধার জায়গা, আমিন জোরে না আস্তে, ইমামের পেছনে ফাতিহা পড়া ও সিজদায় যাওয়ার ভঙ্গি — প্রতিটি মত দলিলসহ।", "en": "Raising the hands, where to place them, Amin aloud or quietly, reciting Al-Fatihah behind the imam, and how to go down to sujud: each view with its evidence."}', 'detail', '[{"type": "text", "text": {"bn": "নিচের বিষয়গুলোতে প্রতিটি মতের পক্ষেই হাদিস ও সাহাবিদের আমল রয়েছে। এগুলো সুন্নাহর ভেতরের পার্থক্য — কোনো মত অনুসরণ করলে নামাজ বাতিল হয় না। তাই এগুলোকে বিভেদের কারণ বানানো উচিত নয়।", "en": "On each of the points below, every view rests on hadith and the practice of Companions. These are differences within the Sunnah; following any of them does not invalidate the prayer, and they should never become a cause of division."}}, {"type": "differ", "title": {"bn": "রাফয়ে ইয়াদাইন: রুকুর আগে-পরে হাত ওঠানো", "en": "Raf'' al-yadayn: raising the hands before and after ruku"}, "views": [{"label": {"bn": "হানাফি ও মালেকি (প্রসিদ্ধ মত)", "en": "Hanafi and Maliki (well-known view)"}, "text": {"bn": "শুধু তাকবিরে তাহরিমার সময় হাত ওঠানো হবে; রুকুতে যাওয়া বা রুকু থেকে ওঠার সময় নয়।", "en": "The hands are raised only at the opening takbir, not when going into or rising from ruku."}, "evidence": {"bn": "ইবনে মাসউদ (রা.) রাসুলুল্লাহ ﷺ-এর নামাজ দেখিয়ে শুধু প্রথমবার হাত তুলেছেন — সুনান তিরমিযি ২৫৭ (তিরমিযি হাসান বলেছেন); সুনান আবু দাউদ ৭৪৮; বারা ইবনে আযিব (রা.)-এর বর্ণনা — সুনান আবু দাউদ ৭৪৯; কুফার সাহাবিদের আমল।", "en": "Ibn Mas''ud (RA) demonstrated the Prophet''s prayer and raised his hands only the first time (Jami at-Tirmidhi 257, graded hasan by at-Tirmidhi; Sunan Abi Dawud 748); the report of al-Bara'' ibn ''Azib (RA) (Sunan Abi Dawud 749); the practice of the Companions in Kufa."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি (এবং আহলে হাদিস)", "en": "Shafi''i and Hanbali (and Ahl al-Hadith)"}, "text": {"bn": "তাকবিরে তাহরিমা ছাড়াও রুকুতে যাওয়ার সময় ও রুকু থেকে ওঠার সময় হাত ওঠানো সুন্নত; অনেকের মতে দ্বিতীয় রাকাত শেষে তৃতীয় রাকাতের জন্য দাঁড়ানোর সময়ও।", "en": "Besides the opening takbir, the hands are raised when going into ruku and when rising from it; many add when standing up for the third rakat."}, "evidence": {"bn": "ইবনে উমর (রা.): রাসুলুল্লাহ ﷺ নামাজ শুরু, রুকুতে যাওয়া ও রুকু থেকে ওঠার সময় কাঁধ পর্যন্ত হাত তুলতেন — সহিহ বুখারি ৭৩৫; সহিহ মুসলিম ৩৯০; দুই রাকাতের পর দাঁড়ানোর সময়ও — সহিহ বুখারি ৭৩৯।", "en": "Ibn Umar (RA): the Prophet ﷺ raised his hands to his shoulders when starting the prayer, going into ruku and rising from it (Sahih al-Bukhari 735; Sahih Muslim 390), and also on standing after two rakats (Sahih al-Bukhari 739)."}}]}, {"type": "differ", "title": {"bn": "হাত কোথায় বাঁধবেন", "en": "Where to place the hands"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "পুরুষরা ডান হাত বাম হাতের উপর রেখে নাভির নিচে বাঁধবেন; নারীরা বুকের উপর।", "en": "Men place the right hand over the left below the navel; women on the chest."}, "evidence": {"bn": "আলি (রা.)-এর বক্তব্য: \"নামাজে হাতের উপর হাত নাভির নিচে রাখা সুন্নত\" — সুনান আবু দাউদ ৭৫৬ (এর সনদ দুর্বল বলা হয়েছে); মুসান্নাফ ইবনে আবি শাইবায় তাবেয়িদের বর্ণনা। হাম্বলি মাযহাবের প্রসিদ্ধ মতও নাভির নিচে।", "en": "Ali (RA): \"It is sunnah to place hand on hand below the navel in prayer\" (Sunan Abi Dawud 756, whose chain has been called weak); reports from the Successors in Musannaf Ibn Abi Shaybah. The well-known Hanbali view is also below the navel."}}, {"label": {"bn": "শাফেয়ি ও কিছু মুহাদ্দিস", "en": "Shafi''i and some hadith scholars"}, "text": {"bn": "বুকের নিচে, নাভির উপরে (শাফেয়ি); কিছু মুহাদ্দিসের মতে বুকের উপর।", "en": "Below the chest and above the navel (Shafi''i); some hadith scholars say on the chest."}, "evidence": {"bn": "ওয়ায়েল ইবনে হুজর (রা.): রাসুলুল্লাহ ﷺ বুকের উপর হাত রেখেছেন — সহিহ ইবনে খুযাইমা ৪৭৯; হুলব আত-তায়ি (রা.)-এর বর্ণনা — মুসনাদে আহমাদ।", "en": "Wa''il ibn Hujr (RA): the Prophet ﷺ placed his hands on his chest (Sahih Ibn Khuzaymah 479); the report of Hulb at-Ta''i (RA) (Musnad Ahmad)."}}, {"label": {"bn": "মালেকি (প্রসিদ্ধ মত)", "en": "Maliki (well-known view)"}, "text": {"bn": "ফরজ নামাজে হাত না বেঁধে দুই পাশে ছেড়ে রাখা (সাদল); নফলে বাঁধা যায়।", "en": "In fard prayers the hands are left at the sides (sadl); they may be folded in voluntary prayers."}, "evidence": {"bn": "ইমাম মালিকের সময়ে মদিনাবাসীর আমল বলে মালেকিরা উল্লেখ করেন (আল-মুদাওয়ানা)।", "en": "Malikis cite the practice of the people of Madinah in Imam Malik''s time (al-Mudawwanah)."}}], "check": true}, {"type": "ref", "text": {"bn": "ডান হাত বাম হাতের উপর রাখার মূল বিধান (যা অধিকাংশের মত): সহিহ বুখারি ৭৪০ (সাহল ইবনে সাদ রা.)", "en": "The basic practice of placing the right hand over the left (the majority view): Sahih al-Bukhari 740 (Sahl ibn Sa''d RA)"}}, {"type": "differ", "title": {"bn": "আমিন জোরে বলবেন না আস্তে", "en": "Saying Amin aloud or quietly"}, "views": [{"label": {"bn": "হানাফি (মালেকিরাও আস্তে)", "en": "Hanafi (Malikis also say it quietly)"}, "text": {"bn": "ইমাম ও মুক্তাদি সবাই আমিন আস্তে বলবেন, শব্দ করে নয়।", "en": "Imam and followers all say Amin quietly."}, "evidence": {"bn": "আমিন একটি দোয়া, আর দোয়ার মূলনীতি নিচু স্বরে: \"তোমাদের রবকে ডাকো বিনয়ের সাথে ও গোপনে\" — সূরা আরাফ ৭:৫৫; ওয়ায়েল (রা.)-এর হাদিসের শুবার বর্ণনায় \"আওয়াজ নিচু করলেন\" (মুসনাদে আহমাদ; তিরমিযি ২৪৮-এর আলোচনায় উল্লিখিত); উমর ও ইবনে মাসউদ (রা.)-এর আমল।", "en": "Amin is a dua, and the principle in dua is quietness: \"Call upon your Lord humbly and privately\" (Al-A''raf 7:55); in Shu''bah''s version of Wa''il''s hadith, \"he lowered his voice\" (Musnad Ahmad; mentioned in at-Tirmidhi''s discussion under 248); the practice of Umar and Ibn Mas''ud (RA)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি (এবং আহলে হাদিস)", "en": "Shafi''i and Hanbali (and Ahl al-Hadith)"}, "text": {"bn": "যেসব নামাজে কিরাত শব্দ করে পড়া হয়, সেখানে ইমাম ও মুক্তাদি আমিন শব্দ করে বলবেন।", "en": "In prayers recited aloud, the imam and followers say Amin aloud."}, "evidence": {"bn": "ওয়ায়েল ইবনে হুজর (রা.): রাসুলুল্লাহ ﷺ \"ওয়ালাদ্দাল্লিন\" বলে আওয়াজ টেনে আমিন বললেন — সুনান তিরমিযি ২৪৮; সুনান আবু দাউদ ৯৩২; \"ইমাম আমিন বললে তোমরাও আমিন বলো; যার আমিন ফেরেশতাদের আমিনের সাথে মিলে যায়, তার আগের গুনাহ মাফ\" — সহিহ বুখারি ৭৮০।", "en": "Wa''il ibn Hujr (RA): after \"wa lad-dallin\" the Prophet ﷺ said Amin, drawing out his voice (Jami at-Tirmidhi 248; Sunan Abi Dawud 932); \"When the imam says Amin, say Amin; whoever''s Amin coincides with the angels'', his past sins are forgiven\" (Sahih al-Bukhari 780)."}}], "check": true}, {"type": "differ", "title": {"bn": "ইমামের পেছনে সূরা ফাতিহা পড়া", "en": "Reciting Al-Fatihah behind the imam"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "মুক্তাদি কোনো নামাজেই — জোরে বা আস্তে কিরাতের নামাজে — ফাতিহা পড়বেন না; চুপ থেকে শুনবেন। ইমামের কিরাতই মুক্তাদির কিরাত।", "en": "The follower does not recite Al-Fatihah in any prayer, loud or quiet; he listens silently. The imam''s recitation counts for him."}, "evidence": {"bn": "\"যখন কুরআন পড়া হয়, মনোযোগ দিয়ে শোনো এবং চুপ থাকো\" — সূরা আরাফ ৭:২০৪; \"ইমাম যখন কিরাত পড়েন, তোমরা চুপ থাকো\" — সহিহ মুসলিম ৪০৪; \"যার ইমাম আছে, ইমামের কিরাতই তার কিরাত\" — সুনান ইবনে মাজাহ ৮৫০ (এর মান নিয়ে মুহাদ্দিসদের মতভেদ আছে)।", "en": "\"When the Quran is recited, listen to it and be silent\" (Al-A''raf 7:204); \"When he (the imam) recites, be silent\" (Sahih Muslim 404); \"Whoever has an imam, the imam''s recitation is his recitation\" (Sunan Ibn Majah 850, whose grading is disputed)."}}, {"label": {"bn": "শাফেয়ি (এবং আহলে হাদিস)", "en": "Shafi''i (and Ahl al-Hadith)"}, "text": {"bn": "মুক্তাদির জন্যও প্রতি রাকাতে ফাতিহা পড়া ফরজ — জোরে কিরাতের নামাজেও, ইমামের থামার ফাঁকে বা নিচু স্বরে।", "en": "Al-Fatihah is obligatory on the follower too, in every rakat, even in loud prayers: in the imam''s pauses or quietly."}, "evidence": {"bn": "\"যে ফাতিহা পড়ে না তার নামাজ হয় না\" — সহিহ বুখারি ৭৫৬; \"ইমামের পেছনে থাকলেও তা মনে মনে পড়ো\" — সহিহ মুসলিম ৩৯৫; \"উম্মুল কুরআন ছাড়া আর কিছু পড়ো না\" — সুনান আবু দাউদ (উবাদা রা.)।", "en": "\"There is no prayer for one who does not recite Al-Fatihah\" (Sahih al-Bukhari 756); \"Recite it to yourself\" even behind the imam (Sahih Muslim 395); \"Do not recite anything except Umm al-Quran\" (Sunan Abi Dawud, from Ubadah RA)."}}, {"label": {"bn": "মালেকি ও হাম্বলি", "en": "Maliki and Hanbali"}, "text": {"bn": "আস্তে কিরাতের নামাজে (জোহর, আসর এবং অন্য নামাজের নিচু স্বরের রাকাত) মুক্তাদি ফাতিহা পড়বেন; জোরে কিরাতের সময় চুপ থেকে শুনবেন।", "en": "In quiet prayers (Zuhr, Asr, and the quiet rakats of others) the follower recites Al-Fatihah; when the imam recites aloud, he listens."}, "evidence": {"bn": "সূরা আরাফ ৭:২০৪ ও সহিহ বুখারি ৭৫৬ — দুটোর সমন্বয়; সাহাবিরা জোরে কিরাতের নামাজে রাসুলুল্লাহ ﷺ-এর পেছনে কিরাত পড়া ছেড়ে দিয়েছিলেন — সুনান আবু দাউদ।", "en": "Combining Al-A''raf 7:204 with Sahih al-Bukhari 756; the Companions stopped reciting behind the Prophet ﷺ in loud prayers (Sunan Abi Dawud)."}}], "check": true}, {"type": "differ", "title": {"bn": "সিজদায় যাওয়ার সময় আগে হাঁটু না আগে হাত", "en": "Going down to sujud: knees first or hands first"}, "views": [{"label": {"bn": "হানাফি, শাফেয়ি ও হাম্বলি (প্রসিদ্ধ মত)", "en": "Hanafi, Shafi''i and Hanbali (well-known view)"}, "text": {"bn": "প্রথমে হাঁটু, তারপর হাত মাটিতে রাখা; ওঠার সময় আগে হাত, পরে হাঁটু।", "en": "Knees first, then hands; when rising, hands first, then knees."}, "evidence": {"bn": "ওয়ায়েল ইবনে হুজর (রা.): রাসুলুল্লাহ ﷺ সিজদায় যেতে হাতের আগে হাঁটু রাখতেন — সুনান আবু দাউদ; সুনান তিরমিযি।", "en": "Wa''il ibn Hujr (RA): the Prophet ﷺ placed his knees before his hands when going into sujud (Sunan Abi Dawud; Jami at-Tirmidhi)."}}, {"label": {"bn": "মালেকি (এবং হাম্বলিদের একটি মত)", "en": "Maliki (and one Hanbali view)"}, "text": {"bn": "প্রথমে হাত, তারপর হাঁটু।", "en": "Hands first, then knees."}, "evidence": {"bn": "\"তোমাদের কেউ যেন উটের মতো না বসে; সে যেন হাঁটুর আগে হাত রাখে\" — আবু হুরায়রা (রা.), সুনান আবু দাউদ।", "en": "\"None of you should kneel as a camel kneels; let him put his hands before his knees\" (Abu Hurayrah RA, Sunan Abi Dawud)."}}], "check": true}, {"type": "differ", "title": {"bn": "বিতরের পদ্ধতি", "en": "How witr is prayed"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "বিতর সবসময় তিন রাকাত, এক সালামে, দ্বিতীয় রাকাতে বৈঠকসহ — মাগরিবের মতো। তৃতীয় রাকাতে রুকুর আগে তাকবির দিয়ে কুনুত, সারা বছর।", "en": "Witr is always three rakats with one salam and a sitting after the second, like Maghrib. Qunut is in the third rakat before ruku, after a takbir, all year round."}, "evidence": {"bn": "আয়েশা (রা.): রাসুলুল্লাহ ﷺ চার রাকাত, তারপর চার রাকাত, তারপর তিন রাকাত পড়তেন — সহিহ বুখারি ১১৪৭; সহিহ মুসলিম ৭৩৮। রুকুর আগে কুনুত — উবাই ইবনে কাব (রা.)-এর বর্ণনা (সুনান নাসায়ি) এবং ইবনে মাসউদ (রা.)-এর আমল।", "en": "Aisha (RA): the Prophet ﷺ prayed four, then four, then three (Sahih al-Bukhari 1147; Sahih Muslim 738). Qunut before ruku: the report of Ubayy ibn Ka''b (RA) (Sunan an-Nasa''i) and the practice of Ibn Mas''ud (RA)."}}, {"label": {"bn": "শাফেয়ি, হাম্বলি ও মালেকি", "en": "Shafi''i, Hanbali and Maliki"}, "text": {"bn": "বিতর এক রাকাতও হতে পারে, আবার তিন, পাঁচ, সাত বা তার বেশি বেজোড় রাকাতও। তিন রাকাত পড়লে সাধারণত দুই রাকাতে সালাম ফিরিয়ে আলাদা এক রাকাত, অথবা মাঝে না বসে একটানা তিন রাকাত। কুনুত সাধারণত রুকুর পরে হাত তুলে; শাফেয়ি মতে শুধু রমজানের শেষ অর্ধেকে।", "en": "Witr may be one rakat, or three, five, seven or more odd rakats. Three are usually prayed as two with a salam and then one, or three straight through without the middle sitting. Qunut is usually after ruku with raised hands; for Shafi''is only in the second half of Ramadan."}, "evidence": {"bn": "\"রাতের নামাজ দুই দুই রাকাত; ফজর হয়ে যাওয়ার ভয় হলে এক রাকাত বিতর পড়ে নাও\" — সহিহ বুখারি ৯৯০; সহিহ মুসলিম ৭৪৯; \"বিতর শেষ রাতের এক রাকাত\" — সহিহ মুসলিম ৭৫২; \"যে চায় পাঁচ, যে চায় তিন, যে চায় এক রাকাত বিতর পড়ুক\" — সুনান আবু দাউদ ১৪২২।", "en": "\"Night prayer is in twos; if you fear dawn, pray one rakat of witr\" (Sahih al-Bukhari 990; Sahih Muslim 749); \"Witr is one rakat at the end of the night\" (Sahih Muslim 752); \"Whoever wishes may pray witr with five, three or one\" (Sunan Abi Dawud 1422)."}}], "check": true}, {"type": "note", "tone": "info", "text": {"bn": "বিতরের বিস্তারিত নিয়ম ও দোয়া কুনুত \"বিশেষ নামাজ\" বিভাগে, আর নারীদের নামাজের ভঙ্গি নিয়ে মতপার্থক্য \"নারীদের নামাজ\" অংশে দেখুন।", "en": "The full method of witr and the dua qunut are in the Special Prayers section; for women''s postures see \"Women''s Salah\"."}}]', 'in_review', 120 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '0f4c431e-25d1-5c29-be99-5122518cfb45', id, 'salah-jamaat-masbuq', '{"bn": "জামাতে নামাজ ও মাসবুক", "en": "Congregational Prayer and Joining Late (Masbuq)"}', '{"bn": "জামাতের গুরুত্ব ও হুকুম, কাতার ও ইমামের অনুসরণের নিয়ম, এবং দেরিতে জামাতে শরিক হলে ছুটে যাওয়া রাকাত কীভাবে পূরণ করবেন।", "en": "The importance and ruling of congregation, rows and following the imam, and how to make up rakats when you join late."}', 'detail', '[{"type": "text", "text": {"bn": "জামাতে নামাজ একা নামাজের চেয়ে সাতাশ গুণ বেশি মর্যাদাপূর্ণ। পুরুষদের জন্য ফরজ নামাজ মসজিদে জামাতে পড়ার ব্যাপারে রাসুলুল্লাহ ﷺ খুব জোর দিয়েছেন; এমনকি এক অন্ধ সাহাবিকেও আজান শুনতে পেলে আসতে বলেছেন।", "en": "Prayer in congregation is twenty-seven times more rewarding than praying alone. The Prophet ﷺ strongly stressed that men pray the fard prayers in congregation in the mosque; he told even a blind Companion who could hear the adhan to come."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৪৫; সহিহ মুসলিম ৬৫০ (২৭ গুণ); সহিহ মুসলিম ৬৫৩ (অন্ধ সাহাবি)", "en": "Sahih al-Bukhari 645; Sahih Muslim 650 (27 times); Sahih Muslim 653 (the blind Companion)"}}, {"type": "differ", "title": {"bn": "পুরুষদের জন্য জামাতের হুকুম", "en": "The ruling on congregation for men"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "সুন্নতে মুয়াক্কাদা — ওয়াজিবের কাছাকাছি; অনেক হানাফি আলেম একে ওয়াজিব বলেছেন। বিনা ওজরে নিয়মিত ছেড়ে দেওয়া গুনাহ।", "en": "An emphasised sunnah, close to wajib; many Hanafi scholars call it wajib. Habitually leaving it without excuse is sinful."}, "evidence": {"bn": "একা নামাজও সহিহ, তবে জামাতের মর্যাদা ২৭ গুণ — সহিহ বুখারি ৬৪৫; এতে বোঝা যায় একা নামাজ বাতিল নয়।", "en": "Praying alone is valid, while congregation is 27 times greater (Sahih al-Bukhari 645), which shows the individual prayer is not void."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "ফরজে কিফায়া — এলাকায় কিছু লোক জামাত কায়েম করলে বাকিদের দায় আদায় হয়।", "en": "A communal obligation: if some in the area establish it, the rest are relieved."}, "evidence": {"bn": "জনপদে জামাত কায়েম না হলে শয়তান প্রভাব বিস্তার করে — এ অর্থের হাদিস (সুনান আবু দাউদ)।", "en": "The hadith that Satan prevails over a settlement where congregational prayer is not established (Sunan Abi Dawud)."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "প্রত্যেক সক্ষম পুরুষের উপর ওয়াজিব (ফরজে আইন), তবে একা পড়লেও নামাজ হয়ে যায়।", "en": "Obligatory on every able man, though a prayer prayed alone is still valid."}, "evidence": {"bn": "জামাতে না আসা লোকদের ঘর জ্বালিয়ে দেওয়ার ইচ্ছা প্রকাশ — সহিহ বুখারি ৬৪৪; অন্ধ সাহাবিকেও ছাড় দেননি — সহিহ মুসলিম ৬৫৩।", "en": "The Prophet ﷺ expressed the wish to burn the houses of those who stay away (Sahih al-Bukhari 644); he did not excuse even the blind Companion (Sahih Muslim 653)."}}], "check": true}, {"type": "heading", "text": {"bn": "জামাতের মূল নিয়ম", "en": "Basic rules of congregation"}}, {"type": "list", "items": [{"bn": "কাতার সোজা ও মিলিত রাখা — কাঁধে কাঁধ, ফাঁক না রাখা; আগে সামনের কাতার পূর্ণ করা। (সহিহ বুখারি ৭২৩)", "en": "Keep the rows straight and close, shoulder to shoulder with no gaps; fill the front rows first. (Sahih al-Bukhari 723)"}, {"bn": "একজন মুক্তাদি হলে ইমামের ডান পাশে দাঁড়াবেন; দুই বা তার বেশি হলে পেছনে কাতার করবেন।", "en": "A single follower stands at the imam''s right; two or more form a row behind."}, {"bn": "ইমাম হওয়ার বেশি হকদার যিনি কুরআন বেশি ভালো পড়েন ও জানেন। (সহিহ মুসলিম ৬৭৩)", "en": "The one most entitled to lead is the one who best knows and recites the Quran. (Sahih Muslim 673)"}, {"bn": "ইমামের অনুসরণ করুন — ইমামের আগে রুকু-সিজদায় যাবেন না বা উঠবেন না; ইমামের আগে মাথা তোলার ব্যাপারে কঠোর সতর্কবাণী আছে। (সহিহ বুখারি ৭২২, ৬৯১)", "en": "Follow the imam: never go down or rise before him; there is a stern warning for raising the head before the imam. (Sahih al-Bukhari 722, 691)"}, {"bn": "ইমাম ভুল করলে পুরুষরা \"সুবহানাল্লাহ\" বলবেন, নারীরা হাততালি দেবেন। (সহিহ বুখারি ১২০৩)", "en": "If the imam errs, men say \"Subhanallah\" and women clap. (Sahih al-Bukhari 1203)"}, {"bn": "ইকামত হয়ে গেলে নতুন করে সুন্নত শুরু না করে জামাতে শরিক হোন; তাড়াহুড়া না করে শান্তভাবে হেঁটে আসুন। (সহিহ বুখারি ৬৩৬)", "en": "Once the iqamah is called, join the congregation rather than starting a sunnah; walk calmly, do not rush. (Sahih al-Bukhari 636)"}]}, {"type": "note", "tone": "info", "text": {"bn": "হানাফি মতে মুক্তাদি তাকবিরে তাহরিমার পর সানা পড়বেন, তারপর চুপ থাকবেন (কিরাত পড়বেন না); রুকু-সিজদার তাসবিহ, \"রাব্বানা লাকাল হামদ\", তাশাহহুদ, দরুদ ও দোয়া নিজে পড়বেন। ইমামের পেছনে ফাতিহা পড়ার মতপার্থক্য \"নামাজে মতপার্থক্যের বিষয়গুলো\" অংশে আছে।", "en": "In the Hanafi view the follower recites the thana after the opening takbir and then stays silent (no recitation); he says the ruku and sujud tasbih, \"Rabbana lakal-hamd\", the tashahhud, durood and dua himself. For the difference on reciting Al-Fatihah behind the imam see \"Points of Difference in Salah\"."}}, {"type": "heading", "text": {"bn": "মাসবুক: দেরিতে জামাতে শরিক হলে", "en": "Masbuq: joining the congregation late"}}, {"type": "text", "text": {"bn": "যে ব্যক্তি এক বা একাধিক রাকাত ছুটে যাওয়ার পর জামাতে শরিক হন, তাকে মাসবুক বলে। রাসুলুল্লাহ ﷺ বলেছেন: \"যতটুকু পাও পড়ো, আর যা ছুটে গেছে পূর্ণ করো।\"", "en": "One who joins after one or more rakats have passed is called masbuq. The Prophet ﷺ said: \"Pray what you catch, and complete what you missed.\""}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৩৬; সহিহ মুসলিম ৬০২", "en": "Sahih al-Bukhari 636; Sahih Muslim 602"}}, {"type": "step", "title": {"bn": "দাঁড়িয়ে তাকবিরে তাহরিমা", "en": "Opening takbir while standing"}, "text": {"bn": "ইমাম যে অবস্থায়ই থাকুন, সোজা দাঁড়ানো অবস্থায় তাকবিরে তাহরিমা বলে নিয়ত বাঁধুন। তারপর আরেকবার \"আল্লাহু আকবার\" বলে ইমাম যে অবস্থায় আছেন (রুকু, সিজদা বা বৈঠক) সে অবস্থায় চলে যান।", "en": "Whatever position the imam is in, say the opening takbir standing upright. Then say \"Allahu akbar\" again and join the imam in his position (ruku, sujud or sitting)."}}, {"type": "step", "title": {"bn": "রাকাত কখন গণ্য হয়", "en": "When a rakat counts"}, "text": {"bn": "ইমাম রুকু থেকে ওঠার আগে আপনি রুকুতে শরিক হতে পারলে সেই রাকাত পেয়েছেন বলে গণ্য হবে (অধিকাংশ আলেমের মত)। রুকুর পরে শরিক হলে সেই রাকাত গণ্য হবে না, পরে পূরণ করতে হবে।", "en": "If you join the imam in ruku before he rises from it, you have caught that rakat (the majority view). If you join after the ruku, that rakat does not count and must be made up."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ — \"যে রুকু পেল সে রাকাত পেল\"", "en": "Sunan Abi Dawud: \"Whoever catches the ruku has caught the rakat\""}, "check": true}, {"type": "step", "title": {"bn": "ইমামের সালামের সময়", "en": "At the imam''s salam"}, "text": {"bn": "শেষ বৈঠকে শুধু তাশাহহুদ ধীরে ধীরে পড়ুন (হানাফি মত)। ইমামের সাথে সালাম ফেরাবেন না; ইমাম দুই দিকে সালাম ফেরানোর পর \"আল্লাহু আকবার\" বলে দাঁড়িয়ে যান।", "en": "In the final sitting recite only the tashahhud, slowly (Hanafi view). Do not give salam with the imam; after he has given both salams, say \"Allahu akbar\" and stand up."}}, {"type": "step", "title": {"bn": "ছুটে যাওয়া রাকাত পূরণ", "en": "Make up the missed rakats"}, "text": {"bn": "হানাফি মতে ছুটে যাওয়া রাকাতগুলো কিরাতের দিক থেকে নামাজের শুরুর রাকাত হিসেবে পড়বেন — অর্থাৎ ফাতিহার সাথে সূরা মেলাবেন; আর বৈঠকের হিসাব হবে মোট রাকাত গুনে।", "en": "In the Hanafi view, the missed rakats are prayed as the beginning of the prayer for recitation (so a surah is added after Al-Fatihah), while the sittings follow the overall count of rakats."}}, {"type": "table", "head": [{"bn": "অবস্থা", "en": "Situation"}, {"bn": "কীভাবে পূরণ করবেন (হানাফি মত)", "en": "How to make up (Hanafi view)"}], "rows": [[{"bn": "চার রাকাতের নামাজে ১ রাকাত ছুটেছে", "en": "Missed 1 rakat of a 4-rakat prayer"}, {"bn": "দাঁড়িয়ে ফাতিহা + সূরা পড়ে রুকু-সিজদা করে শেষ বৈঠক ও সালাম।", "en": "Stand, recite Al-Fatihah + surah, ruku and sujud, then the final sitting and salam."}], [{"bn": "চার রাকাতের নামাজে ২ রাকাত ছুটেছে", "en": "Missed 2 rakats of a 4-rakat prayer"}, {"bn": "দুই রাকাতই ফাতিহা + সূরা দিয়ে, মাঝে না বসে; তারপর শেষ বৈঠক।", "en": "Both rakats with Al-Fatihah + surah, no sitting between; then the final sitting."}], [{"bn": "চার রাকাতের নামাজে ৩ রাকাত ছুটেছে", "en": "Missed 3 rakats of a 4-rakat prayer"}, {"bn": "প্রথম রাকাত ফাতিহা + সূরা, তারপর বসে তাশাহহুদ; দ্বিতীয় রাকাত ফাতিহা + সূরা; তৃতীয় রাকাত শুধু ফাতিহা; তারপর শেষ বৈঠক।", "en": "First rakat Al-Fatihah + surah, then sit for the tashahhud; second rakat Al-Fatihah + surah; third rakat Al-Fatihah only; then the final sitting."}], [{"bn": "মাগরিবে ২ রাকাত ছুটেছে", "en": "Missed 2 rakats of Maghrib"}, {"bn": "প্রথম রাকাত ফাতিহা + সূরা, তারপর বসে তাশাহহুদ; দ্বিতীয় রাকাত ফাতিহা + সূরা; তারপর শেষ বৈঠক।", "en": "First rakat Al-Fatihah + surah, then sit for the tashahhud; second rakat Al-Fatihah + surah; then the final sitting."}], [{"bn": "ইমামকে শেষ বৈঠকে পেয়েছেন", "en": "Joined the imam in the final sitting"}, {"bn": "ইমামের সালামের পর দাঁড়িয়ে পুরো নামাজ সাধারণ নিয়মে পড়বেন; জামাতের সওয়াব পাওয়ার আশা আছে।", "en": "After the imam''s salam, stand and pray the whole prayer normally; you may hope for the reward of the congregation."}]]}, {"type": "note", "tone": "info", "text": {"bn": "শাফেয়ি মাযহাবসহ কিছু আলেমের মতে ইমামের সাথে যে রাকাতগুলো পেয়েছেন সেগুলোই আপনার নামাজের শুরু, আর পরে যা পড়বেন তা শেষ অংশ; তাই পরের রাকাতগুলোর কিরাতের নিয়ম ভিন্ন হয়। ইমাম সাহু সিজদা দিলে মাসবুকও তাঁর সাথে সিজদা করবেন, কিন্তু সালাম ফেরাবেন না।", "en": "In the Shafi''i view and others, the rakats caught with the imam are the start of your prayer and what you pray afterwards is its end, so the recitation rules for the later rakats differ. If the imam does sajdah sahw, the masbuq prostrates with him but does not give salam."}}]', 'in_review', 130 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'ecbc8c6e-1856-5921-8b35-bc7991280594', id, 'sajdah-sahw', '{"bn": "সাহু সিজদা (ভুলের সিজদা)", "en": "Sajdah Sahw (Prostration of Forgetfulness)"}', '{"bn": "নামাজে ভুল হলে কখন সাহু সিজদা লাগে, কখন লাগে না, হানাফি পদ্ধতি, অন্য মাযহাবের মত এবং রাকাত নিয়ে সন্দেহ হলে কী করবেন।", "en": "When a mistake in salah calls for sajdah sahw and when it does not, the Hanafi method, other views, and what to do when unsure how many rakats you prayed."}', 'detail', '[{"type": "text", "text": {"bn": "নামাজে ভুলবশত কিছু বাদ পড়লে বা বেড়ে গেলে নামাজের শেষে দুটি অতিরিক্ত সিজদা দিয়ে তা পূরণ করা হয় — একে সাহু সিজদা বলে। রাসুলুল্লাহ ﷺ নিজেও নামাজে ভুল করে সাহু সিজদা দিয়ে উম্মতকে শিখিয়েছেন।", "en": "When something is left out or added by mistake in salah, it is repaired with two extra prostrations at the end: sajdah sahw. The Prophet ﷺ himself made such mistakes and taught the Ummah by performing sajdah sahw."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১২২৪; সহিহ মুসলিম ৫৭০ (প্রথম বৈঠক ভুলে যাওয়া); সহিহ বুখারি ১২২৯; সহিহ মুসলিম ৫৭৩ (যুল-ইয়াদাইনের ঘটনা)", "en": "Sahih al-Bukhari 1224; Sahih Muslim 570 (forgetting the first sitting); Sahih al-Bukhari 1229; Sahih Muslim 573 (the incident of Dhul-Yadayn)"}}, {"type": "heading", "text": {"bn": "কখন সাহু সিজদা লাগে (হানাফি মত)", "en": "When sajdah sahw is needed (Hanafi view)"}}, {"type": "list", "items": [{"bn": "কোনো ওয়াজিব ভুলে ছুটে গেলে — যেমন প্রথম বৈঠক, ফাতিহা, সূরা মেলানো, দোয়া কুনুত", "en": "A wajib is missed by mistake, e.g. the first sitting, Al-Fatihah, adding a surah, or the qunut"}, {"bn": "কোনো ফরজ বা ওয়াজিব আদায়ে দেরি হলে — যেমন প্রথম বৈঠকে তাশাহহুদের পর দরুদের অংশ পড়ে ফেলা", "en": "A fard or wajib is delayed, e.g. adding part of the durood after the tashahhud in the first sitting"}, {"bn": "কোনো রুকন ভুলে দুবার করলে — যেমন তিনটি সিজদা বা দুটি রুকু", "en": "A pillar is repeated by mistake, e.g. three sujud or two ruku"}, {"bn": "ক্রম উল্টে গেলে — যেমন ফাতিহার আগে সূরা পড়া", "en": "The order is reversed, e.g. reciting the surah before Al-Fatihah"}, {"bn": "জোরে পড়ার জায়গায় আস্তে বা আস্তে পড়ার জায়গায় জোরে পড়লে (ইমামের জন্য)", "en": "Reciting quietly where it should be aloud, or aloud where it should be quiet (for the imam)"}]}, {"type": "note", "tone": "warn", "text": {"bn": "কোনো ফরজ (রুকন) বাদ পড়লে — যেমন একটি সিজদা একেবারেই না করা — সাহু সিজদায় নামাজ পূর্ণ হয় না; নামাজ শেষ হওয়ার আগে মনে পড়লে তা আদায় করে শেষে সাহু সিজদা দেবেন, নইলে নামাজ আবার পড়তে হবে। শুধু সুন্নত ছুটলে (যেমন সানা) সাহু সিজদা লাগে না। ইচ্ছাকৃত ভুলে সাহু সিজদা যথেষ্ট নয়।", "en": "If a pillar is missed, e.g. a sujud left out entirely, sajdah sahw alone does not repair it: if remembered before the prayer ends, perform it and do sahw at the end; otherwise repeat the prayer. Missing only a sunnah (such as the thana) needs no sahw. Sahw does not cover deliberate omissions."}}, {"type": "heading", "text": {"bn": "হানাফি পদ্ধতি", "en": "The Hanafi method"}}, {"type": "step", "title": {"bn": "তাশাহহুদ পড়া", "en": "Recite the tashahhud"}, "text": {"bn": "শেষ বৈঠকে শুধু আত্তাহিয়্যাতু পড়ুন।", "en": "In the final sitting recite only the tashahhud."}}, {"type": "step", "title": {"bn": "ডান দিকে এক সালাম", "en": "One salam to the right"}, "text": {"bn": "শুধু ডান দিকে একবার সালাম ফেরান।", "en": "Give one salam, to the right only."}}, {"type": "step", "title": {"bn": "দুটি সিজদা", "en": "Two prostrations"}, "text": {"bn": "\"আল্লাহু আকবার\" বলে সাধারণ নিয়মে দুটি সিজদা করুন, প্রতিটিতে \"সুবহানা রাব্বিয়াল আ''লা\" পড়ুন, মাঝে বসুন।", "en": "Say \"Allahu akbar\" and make two ordinary prostrations, saying \"Subhana rabbiyal-a''la\" in each, sitting between them."}}, {"type": "step", "title": {"bn": "আবার বৈঠক ও সালাম", "en": "Sit again and finish"}, "text": {"bn": "সিজদার পর বসে আবার আত্তাহিয়্যাতু, দরুদ ও দোয়া পড়ে দুই দিকে সালাম ফেরান।", "en": "After the prostrations, sit, recite the tashahhud, durood and dua again, and give salam to both sides."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৪০১ — \"…তারপর সালাম ফেরাবে, তারপর দুটি সিজদা করবে\" (ইবনে মাসউদ রা.)", "en": "Sahih al-Bukhari 401: \"…then let him give salam, then make two prostrations\" (Ibn Mas''ud RA)"}}, {"type": "differ", "title": {"bn": "সাহু সিজদা সালামের আগে না পরে", "en": "Sajdah sahw before or after the salam"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "সব ক্ষেত্রে সালামের পরে — ডান দিকে এক সালাম দিয়ে, তারপর তাশাহহুদ ও সালাম।", "en": "Always after the salam: one salam to the right, then the prostrations, then tashahhud and salam."}, "evidence": {"bn": "ইবনে মাসউদ (রা.)-এর হাদিস — সহিহ বুখারি ৪০১; \"প্রত্যেক ভুলের জন্য সালামের পর দুটি সিজদা\" — সাওবান (রা.), সুনান আবু দাউদ।", "en": "The hadith of Ibn Mas''ud (RA) (Sahih al-Bukhari 401); \"For every mistake, two prostrations after the salam\" (Thawban RA, Sunan Abi Dawud)."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "সব ক্ষেত্রে সালামের আগে — শেষ বৈঠকের দোয়ার পর দুটি সিজদা, তারপর সালাম।", "en": "Always before the salam: two prostrations after the final sitting''s dua, then salam."}, "evidence": {"bn": "প্রথম বৈঠক ভুলে যাওয়ার পর রাসুলুল্লাহ ﷺ সালামের আগে সিজদা করেছেন — সহিহ বুখারি ১২২৪; রাকাত নিয়ে সন্দেহ হলে সালামের আগে সিজদা — সহিহ মুসলিম ৫৭১।", "en": "After forgetting the first sitting the Prophet ﷺ prostrated before the salam (Sahih al-Bukhari 1224); in doubt about rakats, prostrate before the salam (Sahih Muslim 571)."}}, {"label": {"bn": "মালেকি ও হাম্বলি", "en": "Maliki and Hanbali"}, "text": {"bn": "মালেকি: কিছু কম হলে সালামের আগে, বেশি হলে পরে। হাম্বলি: যে ঘটনায় রাসুলুল্লাহ ﷺ যেভাবে করেছেন সেভাবে, বাকিগুলোতে সাধারণত সালামের আগে।", "en": "Maliki: before the salam for an omission, after it for an addition. Hanbali: as the Prophet ﷺ did in each specific case, otherwise generally before the salam."}, "evidence": {"bn": "উভয় ধরনের হাদিসের সমন্বয়: সালামের আগে — সহিহ বুখারি ১২২৪; সালামের পরে — সহিহ বুখারি ১২২৯ (যুল-ইয়াদাইন) ও ৪০১।", "en": "Reconciling both sets of hadith: before the salam (Sahih al-Bukhari 1224); after it (Sahih al-Bukhari 1229, Dhul-Yadayn, and 401)."}}]}, {"type": "note", "tone": "info", "text": {"bn": "সব মতেই নামাজ সহিহ হয়ে যায়; পার্থক্য শুধু উত্তম পদ্ধতি নিয়ে।", "en": "In every view the prayer is valid; the difference is only about the preferred method."}}, {"type": "heading", "text": {"bn": "রাকাত নিয়ে সন্দেহ হলে", "en": "If unsure how many rakats you prayed"}}, {"type": "text", "text": {"bn": "রাসুলুল্লাহ ﷺ বলেছেন, সন্দেহ হলে নিশ্চিত সংখ্যার উপর ভিত্তি করবে (অর্থাৎ কম সংখ্যা ধরবে) এবং সালামের আগে দুটি সিজদা করবে (সহিহ মুসলিম ৫৭১)। আরেক হাদিসে আছে, যেটা সঠিক মনে হয় সেটা খুঁজে নিয়ে তার উপর পূর্ণ করবে, তারপর দুটি সিজদা করবে (সহিহ বুখারি ৪০১)।", "en": "The Prophet ﷺ said that when in doubt one should build on what is certain (i.e. the lower number) and prostrate twice before the salam (Sahih Muslim 571). Another hadith says to strive for what seems correct, complete the prayer on that basis, then make two prostrations (Sahih al-Bukhari 401)."}}, {"type": "list", "items": [{"bn": "হানাফি মত: জীবনে প্রথমবার বা কদাচিৎ এমন সন্দেহ হলে নামাজ নতুন করে পড়বেন।", "en": "Hanafi view: if such doubt is a first or rare occurrence, restart the prayer."}, {"bn": "প্রায়ই সন্দেহ হলে যেদিকে মনের প্রবল ধারণা, সেটা ধরবেন; কোনো দিকে ধারণা না থাকলে কম সংখ্যা ধরে নামাজ পূর্ণ করে সাহু সিজদা দেবেন।", "en": "If it happens often, go with your strongest impression; if you have none, take the lower number, complete the prayer and do sajdah sahw."}, {"bn": "নামাজ শেষ হওয়ার পর সন্দেহ হলে তা গুরুত্ব দেবেন না, যদি না নিশ্চিত হন যে কিছু বাদ পড়েছে।", "en": "Doubts that arise after the prayer has ended are ignored, unless you are certain something was missed."}]}, {"type": "note", "tone": "info", "text": {"bn": "জামাতে ইমামের পেছনে নিজের ভুলের জন্য মুক্তাদিকে সাহু সিজদা দিতে হয় না। ইমাম সাহু সিজদা দিলে মুক্তাদিরা তাঁর অনুসরণ করবেন।", "en": "A follower behind the imam does not do sajdah sahw for his own mistakes. When the imam does sajdah sahw, the followers follow him."}}]', 'in_review', 140 FROM is_guide_topics WHERE slug = 'salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9790e45e-2f4f-51bc-9504-2163762671fe', id, 'jumuah-prayer', '{"bn": "জুমার নামাজ", "en": "Jumu''ah (Friday) Prayer"}', '{"bn": "জুমার নামাজ কার ওপর ফরজ, কত রাকাত, খুতবার আদব আর জুমার দিনের সুন্নতগুলো এক জায়গায়।", "en": "Who must pray Jumu''ah, its rak''ahs, the khutbah, and the sunnahs of Friday."}', 'basic', '[{"type": "text", "text": {"bn": "জুমার দিন সপ্তাহের শ্রেষ্ঠ দিন। জুমার নামাজ সেদিনের জোহরের জায়গায় পড়া হয়: আগে খুতবা, তারপর জামাতের সাথে দুই রাকাত ফরজ। যার ওপর জুমা ফরজ, জুমা পড়লে তাকে আর জোহর পড়তে হয় না।", "en": "Friday is the best day of the week. Jumu''ah replaces Dhuhr on Friday: a khutbah, then two fard rak''ahs in congregation. Whoever prays Jumu''ah does not also pray Dhuhr."}}, {"type": "arabic", "label": {"bn": "কুরআনের নির্দেশ", "en": "The Quranic command"}, "ar": "يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ", "pron": {"bn": "ইয়া আইয়ুহাল্লাযীনা আমানূ ইযা নূদিয়া লিসসালাতি মিই ইয়াওমিল জুমু''আতি ফাসআও ইলা যিকরিল্লাহি ওয়া যারুল বাই''। যালিকুম খাইরুল লাকুম ইন কুনতুম তা''লামূন।", "en": "Ya ayyuhalladhina amanu idha nudiya lis-salati min yawmil-jumu''ati fas''aw ila dhikrillahi wa dharul-bay''. Dhalikum khayrul lakum in kuntum ta''lamun."}, "meaning": {"bn": "হে মুমিনগণ, জুমার দিন যখন নামাজের জন্য আহ্বান করা হয়, তখন তোমরা আল্লাহর স্মরণের দিকে ধাবিত হও এবং বেচাকেনা ছেড়ে দাও। এটাই তোমাদের জন্য উত্তম, যদি তোমরা জানতে।", "en": "O you who believe, when the call is made for prayer on Friday, hasten to the remembrance of Allah and leave off trade. That is better for you, if you only knew."}, "ref": {"bn": "সূরা জুমু''আ ৬২:৯", "en": "Al-Jumu''ah 62:9"}}, {"type": "heading", "text": {"bn": "কার ওপর জুমা ফরজ", "en": "Who must attend"}}, {"type": "list", "items": [{"bn": "প্রাপ্তবয়স্ক ও সুস্থ মস্তিষ্কের মুসলিম পুরুষ", "en": "An adult, sane Muslim man"}, {"bn": "মুকিম, অর্থাৎ যিনি সফরে নেই", "en": "Resident (not travelling)"}, {"bn": "সুস্থ, যার মসজিদে যেতে বাধা নেই", "en": "Healthy, with nothing preventing him from going"}]}, {"type": "text", "text": {"bn": "নারী, শিশু, অসুস্থ ব্যক্তি ও মুসাফিরের ওপর জুমা ফরজ নয়; তারা ঘরে চার রাকাত জোহর পড়বেন। তবে তারা মসজিদে গিয়ে জুমা পড়লে সেটাই যথেষ্ট, আলাদা জোহর লাগবে না।", "en": "Women, children, the sick and travellers are exempt; they pray four rak''ahs of Dhuhr. If they do attend Jumu''ah, it counts and no Dhuhr is needed."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ১০৬৭ (তারিক ইবনে শিহাব রা.: চার শ্রেণি ছাড়া প্রত্যেক মুসলিমের ওপর জামাতে জুমা ফরজ)", "en": "Sunan Abi Dawud 1067 (Jumu''ah is a duty on every Muslim in congregation except four)"}}, {"type": "note", "tone": "warn", "text": {"bn": "অবহেলা করে পরপর তিন জুমা ছেড়ে দিলে আল্লাহ তার অন্তরে মোহর মেরে দেন। (সুনান আবু দাউদ ১০৫২)", "en": "Whoever leaves three Jumu''ahs out of negligence, Allah seals his heart. (Sunan Abi Dawud 1052)"}}, {"type": "heading", "text": {"bn": "জুমার দিনের নামাজের ক্রম", "en": "Order of prayers on Friday"}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "রাকাত", "en": "Rak''ahs"}, {"bn": "হুকুম", "en": "Ruling"}], "rows": [[{"bn": "জুমার আগের সুন্নত", "en": "Sunnah before Jumu''ah"}, {"bn": "৪", "en": "4"}, {"bn": "হানাফি মতে সুন্নতে মুয়াক্কাদা (নিচে মতভেদ দেখুন)", "en": "Sunnah mu''akkadah in the Hanafi school (see the difference below)"}], [{"bn": "খুতবা (দুইটি)", "en": "Khutbah (two parts)"}, {"bn": "—", "en": "—"}, {"bn": "জুমা সহিহ হওয়ার শর্ত", "en": "A condition for Jumu''ah to be valid"}], [{"bn": "জুমার ফরজ", "en": "Jumu''ah fard"}, {"bn": "২", "en": "2"}, {"bn": "ফরজ, জামাতের সাথে; ইমাম জোরে কিরাত পড়েন", "en": "Fard, in congregation; the imam recites aloud"}], [{"bn": "জুমার পরের সুন্নত", "en": "Sunnah after Jumu''ah"}, {"bn": "৪ (কেউ কেউ এরপর আরও ২)", "en": "4 (some add 2 more)"}, {"bn": "সুন্নত", "en": "Sunnah"}]]}, {"type": "differ", "title": {"bn": "জুমার আগে ও পরে সুন্নত কত রাকাত", "en": "Sunnah prayers before and after Jumu''ah"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "জুমার আগে চার রাকাত ও পরে চার রাকাত সুন্নতে মুয়াক্কাদা। ইমাম আবু ইউসুফ (রহ.)-এর মতে পরে মোট ছয় রাকাত (চার, তারপর দুই)।", "en": "Four rak''ahs before and four after, both sunnah mu''akkadah. Imam Abu Yusuf held six after (four, then two)."}, "evidence": {"bn": "পরের চার রাকাত: সহিহ মুসলিম ৮৮১ (জুমার পরে চার রাকাত পড়ার নির্দেশ)। আগের চার রাকাত: ইবনে মাসউদ (রা.) জুমার আগে চার ও পরে চার রাকাত পড়তেন, ইমাম তিরমিজি তা উল্লেখ করেছেন (জামে তিরমিজি ৫২৩-এর আলোচনা); আলী (রা.) পরে দুই তারপর চার পড়তে বলেছেন।", "en": "After: Sahih Muslim 881 (pray four after Jumu''ah). Before: Ibn Mas''ud prayed four before and four after, as al-Tirmidhi notes (discussion under Jami'' al-Tirmidhi 523); ''Ali instructed two then four after."}}, {"label": {"bn": "শাফেয়ি, হাম্বলি ও অন্যান্য অনেকে", "en": "Shafi''i, Hanbali and many others"}, "text": {"bn": "জুমার আগে নির্দিষ্ট সংখ্যার সুন্নত নেই; ইমাম খুতবার জন্য বের হওয়া পর্যন্ত যত রাকাত ইচ্ছা নফল পড়া যায়। পরে মসজিদে চার রাকাত, অথবা ঘরে গিয়ে দুই রাকাত।", "en": "No fixed sunnah before Jumu''ah; pray as many voluntary rak''ahs as one likes until the imam comes out. After: four in the mosque or two at home."}, "evidence": {"bn": "সহিহ বুখারি ৮৮৩ (‘তারপর তার জন্য যা লেখা আছে তা পড়ে’); সহিহ মুসলিম ৮৮১ (পরে চার); সহিহ বুখারি ৯৩৭ (নবীজি সা. জুমার পরে ঘরে দুই রাকাত পড়তেন)।", "en": "Sahih al-Bukhari 883 (''then prays what was written for him''); Sahih Muslim 881 (four after); Sahih al-Bukhari 937 (the Prophet prayed two at home after Jumu''ah)."}}]}, {"type": "heading", "text": {"bn": "খুতবা ও তার আদব", "en": "The khutbah and its etiquette"}}, {"type": "list", "items": [{"bn": "ইমাম দুইটি খুতবা দেন, মাঝে অল্প সময় বসেন; খুতবায় কুরআন পড়া হয় ও উপদেশ দেওয়া হয় (সহিহ মুসলিম ৮৬২)।", "en": "The imam gives two khutbahs with a short sitting between them, reciting Quran and admonishing (Sahih Muslim 862)."}, {"bn": "খুতবা চুপ করে মনোযোগ দিয়ে শুনতে হয়। খুতবার সময় পাশের জনকে ‘চুপ করো’ বলাও অনর্থক কাজ (লাগব) বলে গণ্য (সহিহ বুখারি ৯৩৪)।", "en": "Listen silently. Even telling a neighbour ''be quiet'' during the khutbah is idle talk (Sahih al-Bukhari 934)."}, {"bn": "খুতবার সময় কথা বলা, মোবাইল দেখা, খাওয়া-দাওয়া ইত্যাদি থেকে বিরত থাকুন।", "en": "Do not talk, use the phone or eat during the khutbah."}, {"bn": "দেরিতে এলে মানুষের ঘাড় ডিঙিয়ে সামনে যাবেন না; নবীজি (সা.) এমন একজনকে বলেছিলেন, ‘বসে পড়ো, তুমি কষ্ট দিয়েছ’ (সুনান আবু দাউদ ১১১৮)।", "en": "If late, do not step over people''s necks; the Prophet told such a man, ''Sit down, you have caused harm'' (Sunan Abi Dawud 1118)."}]}, {"type": "differ", "title": {"bn": "খুতবা চলাকালে মসজিদে ঢুকলে দুই রাকাত পড়বে কি", "en": "Praying two rak''ahs on entering during the khutbah"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "ইমাম খুতবার জন্য বের হয়ে গেলে আর নামাজ শুরু করবে না; বসে খুতবা শুনবে।", "en": "Once the imam has come out for the khutbah, do not start a prayer; sit and listen."}, "evidence": {"bn": "খুতবা শোনার নির্দেশ ও খুতবার সময় সামান্য কথাও নিষেধ হওয়া (সহিহ বুখারি ৯৩৪); ঘাড় ডিঙানো ব্যক্তিকে নবীজি (সা.) বসে যেতে বলেছিলেন (সুনান আবু দাউদ ১১১৮)।", "en": "The command to listen and the ban on even small talk (Sahih al-Bukhari 934); the Prophet told the man who stepped over people to sit (Sunan Abi Dawud 1118)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "সংক্ষেপে দুই রাকাত তাহিয়্যাতুল মসজিদ পড়ে বসবে।", "en": "Pray two short rak''ahs of tahiyyat al-masjid, then sit."}, "evidence": {"bn": "খুতবার সময় এক সাহাবি এসে বসে পড়লে নবীজি (সা.) তাকে দুই রাকাত সংক্ষেপে পড়তে বলেন (সহিহ বুখারি ৯৩০; সহিহ মুসলিম ৮৭৫)।", "en": "A man came during the khutbah and sat; the Prophet told him to pray two short rak''ahs (Sahih al-Bukhari 930; Sahih Muslim 875)."}}]}, {"type": "differ", "title": {"bn": "খুতবার ভাষা", "en": "Language of the khutbah"}, "views": [{"label": {"bn": "আরবিতে খুতবা (বাংলাদেশে প্রচলিত হানাফি আমল)", "en": "Khutbah in Arabic (common Hanafi practice in Bangladesh)"}, "text": {"bn": "মূল দুই খুতবা আরবিতেই দিতে হবে। মানুষকে বোঝানোর জন্য আজানের আগে বা খুতবার আগে মাতৃভাষায় আলাদা বয়ান করা হয়।", "en": "The two khutbahs themselves are given in Arabic; a talk in the local language is given separately before the adhan/khutbah."}, "evidence": {"bn": "নবীজি (সা.) ও সাহাবিরা সবসময় আরবিতে খুতবা দিয়েছেন, অনারব দেশে গিয়েও; খুতবা একটি ইবাদত, যা সুন্নাহর পদ্ধতিতে আদায় করা হয়।", "en": "The Prophet and the Companions always gave the khutbah in Arabic, even in non-Arab lands; the khutbah is an act of worship done in the sunnah way."}}, {"label": {"bn": "স্থানীয় ভাষায় খুতবা জায়েজ (কিছু আলেমের মত)", "en": "Local language allowed (view of some scholars)"}, "text": {"bn": "আরবিতে হামদ, দরুদ ও কুরআনের আয়াত পড়ে বাকি উপদেশ শ্রোতাদের ভাষায় দেওয়া যায়।", "en": "After praise, durood and Quran in Arabic, the admonition may be in the listeners'' language."}, "evidence": {"bn": "খুতবার উদ্দেশ্য উপদেশ দেওয়া (সহিহ মুসলিম ৮৬২); আল্লাহ প্রত্যেক রাসুলকে তার জাতির ভাষায় পাঠিয়েছেন (সূরা ইবরাহিম ১৪:৪)।", "en": "The khutbah''s purpose is admonition (Sahih Muslim 862); Allah sent every messenger in his people''s language (Ibrahim 14:4)."}}]}, {"type": "heading", "text": {"bn": "জুমা ছুটে গেলে বা দেরিতে পেলে", "en": "If you miss or join late"}}, {"type": "text", "text": {"bn": "জুমার জামাত পুরো ছুটে গেলে জুমা একা পড়া যায় না; চার রাকাত জোহর পড়তে হবে।", "en": "If you miss the Jumu''ah congregation entirely, you cannot pray Jumu''ah alone; pray four rak''ahs of Dhuhr."}}, {"type": "differ", "title": {"bn": "কতটুকু পেলে জুমা পাওয়া গণ্য হবে", "en": "How much must be caught to count as Jumu''ah"}, "views": [{"label": {"bn": "ইমাম আবু হানিফা ও আবু ইউসুফ (রহ.)", "en": "Imam Abu Hanifah and Abu Yusuf"}, "text": {"bn": "ইমামকে সালামের আগে যেকোনো অবস্থায়, এমনকি শেষ বৈঠকে পেলেও, দুই রাকাত জুমাই পূর্ণ করবে।", "en": "Joining the imam at any point before the salam, even in the last sitting, you complete two rak''ahs of Jumu''ah."}, "evidence": {"bn": "‘যতটুকু পাও পড়ো, আর যা ছুটে গেছে তা পূর্ণ করো’ (সহিহ বুখারি ৬৩৬)।", "en": "''Pray what you catch and complete what you missed'' (Sahih al-Bukhari 636)."}}, {"label": {"bn": "ইমাম মুহাম্মাদ (রহ.) ও শাফেয়ি, মালেকি, হাম্বলি", "en": "Imam Muhammad, and the Shafi''i, Maliki, Hanbali schools"}, "text": {"bn": "দ্বিতীয় রাকাতের রুকু পেলে জুমা পেয়েছে, আরেক রাকাত মিলিয়ে নেবে; রুকুর পরে যোগ দিলে চার রাকাত জোহর পড়বে।", "en": "If you catch the ruku'' of the second rak''ah, add one rak''ah for Jumu''ah; if you join after it, pray four of Dhuhr."}, "evidence": {"bn": "‘যে জুমার এক রাকাত পেল, সে যেন তার সাথে আরেক রাকাত মিলায়’ (সুনান ইবনে মাজাহ ১১২১; সুনান নাসায়ি ৫৫৭)।", "en": "''Whoever catches one rak''ah of Jumu''ah, let him add another to it'' (Sunan Ibn Majah 1121; Sunan al-Nasa''i 557)."}}]}, {"type": "heading", "text": {"bn": "জুমার দিনের সুন্নত ও আমল", "en": "Sunnahs and good deeds of Friday"}}, {"type": "list", "items": [{"bn": "গোসল করা (সহিহ বুখারি ৮৭৭, ৮৭৯)", "en": "Take a bath (ghusl) (Sahih al-Bukhari 877, 879)"}, {"bn": "পরিচ্ছন্ন ও ভালো কাপড় পরা, তেল বা সুগন্ধি লাগানো, যথাসাধ্য পবিত্রতা অর্জন (সহিহ বুখারি ৮৮৩)", "en": "Wear clean, good clothes, use oil or perfume, purify yourself as you can (Sahih al-Bukhari 883)"}, {"bn": "আগে আগে মসজিদে যাওয়া এবং ইমামের কাছাকাছি বসা", "en": "Go to the mosque early and sit near the imam"}, {"bn": "দুজনের মাঝে ফাঁক করে না বসা, চুপ করে খুতবা শোনা (সহিহ বুখারি ৮৮৩)", "en": "Do not squeeze between two people; listen quietly (Sahih al-Bukhari 883)"}, {"bn": "বেশি বেশি দরুদ পড়া (সুনান আবু দাউদ ১০৪৭)", "en": "Send abundant durood on the Prophet (Sunan Abi Dawud 1047)"}, {"bn": "দোয়া করা: জুমার দিনে একটি সময় আছে, তখন মুমিন যা চায় আল্লাহ দেন (সহিহ বুখারি ৯৩৫)", "en": "Make dua: there is an hour on Friday when Allah grants what a believer asks (Sahih al-Bukhari 935)"}, {"bn": "সূরা কাহফ তিলাওয়াত করা", "en": "Recite Surah al-Kahf"}, {"bn": "আজান হলে বেচাকেনা ও কাজ বন্ধ করে মসজিদে যাওয়া (সূরা জুমু''আ ৬২:৯)", "en": "Stop trade and work at the adhan and go to the mosque (Al-Jumu''ah 62:9)"}]}, {"type": "note", "tone": "info", "text": {"bn": "জুমার দিনে সূরা কাহফ পড়ার ফজিলতের হাদিস (আবু সাইদ খুদরি রা. থেকে) মুস্তাদরাকে হাকিম ও বায়হাকিতে আছে; অনেক মুহাদ্দিস একে সহিহ বলেছেন, কেউ কেউ মারফু হওয়া নিয়ে আপত্তি করেছেন।", "en": "The hadith on reading al-Kahf on Friday (from Abu Sa''id al-Khudri) is in al-Hakim''s Mustadrak and al-Bayhaqi; many scholars graded it sahih, some questioned whether it is the Prophet''s own words."}, "check": true}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e079fbc8-d1ce-54be-b7ae-d12312ba9b31', id, 'eid-prayer', '{"bn": "ঈদের নামাজ", "en": "Eid Prayer"}', '{"bn": "ঈদুল ফিতর ও ঈদুল আজহার নামাজ দুই রাকাত, অতিরিক্ত তাকবিরসহ। নিয়ম, তাকবিরের সংখ্যা নিয়ে মতভেদ ও ঈদের সুন্নত।", "en": "Eid al-Fitr and Eid al-Adha prayer: two rak''ahs with extra takbirs, the views on their number, and the sunnahs of Eid."}', 'basic', '[{"type": "text", "text": {"bn": "ঈদের নামাজ দুই রাকাত, জামাতের সাথে, আজান ও ইকামত ছাড়া (সহিহ মুসলিম ৮৮৭)। নামাজ আগে, খুতবা পরে (সহিহ বুখারি ৯৬৩)। সময়: সূর্য উঠে কিছুটা ওপরে ওঠার পর থেকে দুপুরের (জাওয়াল) আগ পর্যন্ত।", "en": "Eid prayer is two rak''ahs in congregation, without adhan or iqamah (Sahih Muslim 887). The prayer comes first, then the khutbah (Sahih al-Bukhari 963). Time: from when the sun has risen a little until just before noon (zawal)."}}, {"type": "differ", "title": {"bn": "ঈদের নামাজের হুকুম", "en": "Ruling of the Eid prayer"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "যাদের ওপর জুমা ফরজ, তাদের ওপর ঈদের নামাজ ওয়াজিব।", "en": "Wajib on those for whom Jumu''ah is obligatory."}, "evidence": {"bn": "নবীজি (সা.) কখনো ঈদের নামাজ ছাড়েননি; নারীদেরও ঈদগাহে যেতে বলেছেন (সহিহ বুখারি ৯৭৪; সহিহ মুসলিম ৮৯০)।", "en": "The Prophet never left it and told even women to come out (Sahih al-Bukhari 974; Sahih Muslim 890)."}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "সুন্নতে মুয়াক্কাদা।", "en": "A confirmed sunnah."}, "evidence": {"bn": "দিনে-রাতে পাঁচ ওয়াক্ত ছাড়া আর কোনো নামাজ ফরজ নয় (সহিহ বুখারি ৪৬)।", "en": "No prayer is obligatory beyond the five daily prayers (Sahih al-Bukhari 46)."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "ফরজে কিফায়া (সমাজের কিছু লোক আদায় করলে সবার পক্ষ থেকে আদায় হয়)।", "en": "A communal obligation (fard kifayah)."}, "evidence": {"bn": "নবীজি (সা.)-এর নিয়মিত আমল এবং এটি ইসলামের প্রকাশ্য নিদর্শন।", "en": "The Prophet''s constant practice, and it is a public symbol of Islam."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনে মনে করাই যথেষ্ট, মুখে বলা জরুরি নয়। উদাহরণ (প্রচলিত বাংলা): ‘আমি ঈদুল ফিতরের দুই রাকাত ওয়াজিব নামাজ, অতিরিক্ত ছয় তাকবিরসহ, এই ইমামের পেছনে আদায় করছি।’", "en": "Niyyah is the intention in the heart; saying it aloud is not required. Example (common Bangla phrasing): ''I am praying the two wajib rak''ahs of Eid al-Fitr with six extra takbirs behind this imam.''"}}, {"type": "heading", "text": {"bn": "হানাফি পদ্ধতি (বাংলাদেশে প্রচলিত)", "en": "Hanafi method (common in Bangladesh)"}}, {"type": "step", "title": {"bn": "তাকবিরে তাহরিমা", "en": "Opening takbir"}, "text": {"bn": "নিয়ত করে ‘আল্লাহু আকবার’ বলে হাত বাঁধুন এবং সানা পড়ুন।", "en": "Make the intention, say ''Allahu Akbar'', fold your hands and recite the thana."}}, {"type": "step", "title": {"bn": "প্রথম রাকাতে তিন অতিরিক্ত তাকবির", "en": "Three extra takbirs in the first rak''ah"}, "text": {"bn": "ইমামের সাথে তিনবার ‘আল্লাহু আকবার’ বলুন। প্রথম ও দ্বিতীয় তাকবিরে কান পর্যন্ত হাত তুলে ছেড়ে দিন; তৃতীয় তাকবিরে হাত তুলে বেঁধে নিন। প্রতি দুই তাকবিরের মাঝে প্রায় তিন তাসবিহ পরিমাণ থামুন।", "en": "Say ''Allahu Akbar'' three times with the imam. On the first and second, raise your hands to the ears and let them hang; on the third, raise them and fold them. Pause about three tasbihs between takbirs."}}, {"type": "step", "title": {"bn": "কিরাত", "en": "Recitation"}, "text": {"bn": "ইমাম সূরা ফাতিহা ও আরেকটি সূরা জোরে পড়বেন; মুক্তাদি চুপ করে শুনবেন। তারপর স্বাভাবিকভাবে রুকু ও দুই সিজদা।", "en": "The imam recites al-Fatihah and a surah aloud; followers listen silently. Then ruku'' and two sajdahs as usual."}}, {"type": "step", "title": {"bn": "দ্বিতীয় রাকাতে কিরাতের পর তিন তাকবির", "en": "Second rak''ah: three takbirs after recitation"}, "text": {"bn": "দ্বিতীয় রাকাতে ইমাম আগে কিরাত পড়বেন। তারপর তিনবার তাকবির, প্রতিবার কান পর্যন্ত হাত তুলে ছেড়ে দেবেন।", "en": "In the second rak''ah the imam recites first. Then three takbirs, each time raising the hands and letting them hang."}}, {"type": "step", "title": {"bn": "চতুর্থ তাকবিরে রুকু", "en": "Fourth takbir into ruku''"}, "text": {"bn": "চতুর্থবার হাত না তুলে ‘আল্লাহু আকবার’ বলে রুকুতে যান; তারপর সিজদা, বৈঠক ও সালাম দিয়ে নামাজ শেষ করুন।", "en": "On the fourth takbir go into ruku'' without raising the hands; then complete the sajdahs, sitting and salam."}}, {"type": "step", "title": {"bn": "খুতবা শোনা", "en": "Listen to the khutbah"}, "text": {"bn": "নামাজের পর ইমাম খুতবা দেবেন; চুপ করে শুনুন। ঈদের খুতবা শোনা সুন্নত।", "en": "After the prayer the imam gives the khutbah; listen quietly."}}, {"type": "note", "tone": "info", "text": {"bn": "সুন্নত হলো প্রথম রাকাতে সূরা আ''লা ও দ্বিতীয় রাকাতে সূরা গাশিয়া (সহিহ মুসলিম ৮৭৮), অথবা সূরা কাফ ও সূরা কামার (সহিহ মুসলিম ৮৯১) পড়া।", "en": "It is sunnah to recite al-A''la and al-Ghashiyah (Sahih Muslim 878), or Qaf and al-Qamar (Sahih Muslim 891)."}}, {"type": "differ", "title": {"bn": "অতিরিক্ত তাকবিরের সংখ্যা", "en": "Number of extra takbirs"}, "views": [{"label": {"bn": "হানাফি: মোট ছয়", "en": "Hanafi: six in total"}, "text": {"bn": "প্রথম রাকাতে সানার পর কিরাতের আগে তিন; দ্বিতীয় রাকাতে কিরাতের পর রুকুর আগে তিন।", "en": "Three in the first rak''ah after the thana and before recitation; three in the second after recitation and before ruku''."}, "evidence": {"bn": "আবু মুসা আশআরি ও হুযাইফা (রা.) বলেন, নবীজি (সা.) ঈদে জানাযার তাকবিরের মতো চার তাকবির দিতেন (তাকবিরে তাহরিমা/রুকুর তাকবিরসহ) (সুনান আবু দাউদ ১১৫৩); ইবনে মাসউদ (রা.)-এর আমলও এমন বর্ণিত।", "en": "Abu Musa and Hudhayfah said the Prophet made four takbirs on Eid like the funeral takbirs (counting the opening/ruku'' takbir) (Sunan Abi Dawud 1153); the same is reported from Ibn Mas''ud."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি: মোট বারো", "en": "Shafi''i, Maliki, Hanbali: twelve"}, "text": {"bn": "প্রথম রাকাতে কিরাতের আগে সাত (মালেকি ও হাম্বলিদের হিসাবে তাকবিরে তাহরিমাসহ, শাফেয়িদের হিসাবে তা বাদে), দ্বিতীয় রাকাতে কিরাতের আগে পাঁচ।", "en": "Seven before recitation in the first rak''ah (including the opening takbir for Maliki/Hanbali, excluding it for Shafi''i) and five before recitation in the second."}, "evidence": {"bn": "সুনান আবু দাউদ ১১৪৯ (আয়েশা রা.), ১১৫১ (আবদুল্লাহ ইবনে আমর রা.); জামে তিরমিজি ৫৩৬; সুনান ইবনে মাজাহ ১২৭৯।", "en": "Sunan Abi Dawud 1149 (''A''ishah), 1151 (''Abdullah ibn ''Amr); Jami'' al-Tirmidhi 536; Sunan Ibn Majah 1279."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "যে ইমামের পেছনে পড়ছেন, তাকবিরের সংখ্যায় তাকে অনুসরণ করুন। দুটি পদ্ধতিই সাহাবিদের থেকে বর্ণিত।", "en": "Follow your imam in the number of takbirs; both ways are reported from the Companions."}}, {"type": "heading", "text": {"bn": "ঈদের দিনের সুন্নত", "en": "Sunnahs of Eid day"}}, {"type": "list", "items": [{"bn": "গোসল করা, সবচেয়ে ভালো কাপড় পরা, সুগন্ধি লাগানো", "en": "Bathe, wear your best clothes, use perfume"}, {"bn": "ঈদুল ফিতরে নামাজে যাওয়ার আগে বেজোড় সংখ্যক খেজুর বা কিছু খাওয়া (সহিহ বুখারি ৯৫৩)", "en": "On Eid al-Fitr, eat an odd number of dates before going (Sahih al-Bukhari 953)"}, {"bn": "ঈদুল আজহায় নামাজের আগে না খেয়ে নামাজের পর খাওয়া (জামে তিরমিজি ৫৪২)", "en": "On Eid al-Adha, eat after the prayer (Jami'' al-Tirmidhi 542)"}, {"bn": "ঈদুল ফিতরের নামাজের আগে সদকাতুল ফিতর আদায় করা", "en": "Pay zakat al-fitr before the Eid al-Fitr prayer"}, {"bn": "এক পথে যাওয়া, অন্য পথে ফেরা (সহিহ বুখারি ৯৮৬)", "en": "Go by one route and return by another (Sahih al-Bukhari 986)"}, {"bn": "ঈদগাহে যাওয়ার পথে তাকবির বলা; ইমাম আবু হানিফা (রহ.)-এর মতে ঈদুল ফিতরে নিচু স্বরে ও ঈদুল আজহায় উঁচু স্বরে, অন্য অনেক আলেমের মতে দুই ঈদেই উঁচু স্বরে", "en": "Say takbir on the way: per Imam Abu Hanifah quietly on Eid al-Fitr and aloud on Eid al-Adha; many other scholars say aloud on both"}]}, {"type": "heading", "text": {"bn": "তাকবিরে তাশরিক", "en": "Takbir al-tashriq"}}, {"type": "arabic", "label": {"bn": "তাকবিরে তাশরিক", "en": "Takbir al-tashriq"}, "ar": "اللّٰهُ أَكْبَرُ اللّٰهُ أَكْبَرُ، لَا إِلٰهَ إِلَّا اللّٰهُ، وَاللّٰهُ أَكْبَرُ اللّٰهُ أَكْبَرُ، وَلِلّٰهِ الْحَمْدُ", "pron": {"bn": "আল্লাহু আকবার আল্লাহু আকবার, লা ইলাহা ইল্লাল্লাহু, ওয়াল্লাহু আকবার আল্লাহু আকবার, ওয়া লিল্লাহিল হামদ।", "en": "Allahu akbar, Allahu akbar, la ilaha illallah, wallahu akbar, Allahu akbar, wa lillahil-hamd."}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়, আল্লাহ সবচেয়ে বড়; আল্লাহ ছাড়া কোনো ইলাহ নেই; আল্লাহ সবচেয়ে বড়, আল্লাহ সবচেয়ে বড়; আর সকল প্রশংসা আল্লাহরই।", "en": "Allah is the Greatest, Allah is the Greatest; there is no god but Allah; Allah is the Greatest, Allah is the Greatest, and all praise is for Allah."}, "ref": {"bn": "ইবনে মাসউদ (রা.) থেকে বর্ণিত, মুসান্নাফ ইবনে আবি শাইবা", "en": "Reported from Ibn Mas''ud, Musannaf Ibn Abi Shaybah"}, "check": true}, {"type": "text", "text": {"bn": "হানাফি মতে ৯ জিলহজের ফজর থেকে ১৩ জিলহজের আসর পর্যন্ত প্রত্যেক ফরজ নামাজের পর একবার এই তাকবির বলা ওয়াজিব; পুরুষেরা জোরে, নারীরা নিচু স্বরে বলবেন। অন্য মাজহাবে এটি সুন্নত, এবং সময়সীমা নিয়েও কিছু ভিন্নতা আছে।", "en": "In the Hanafi school it is wajib to say it once after every fard prayer from Fajr of 9 Dhul-Hijjah to ''Asr of the 13th; men aloud, women quietly. Other schools hold it sunnah, with some differences in the period."}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৮৫, ২:২০৩ (নির্দিষ্ট দিনগুলোতে আল্লাহর জিকির)", "en": "Al-Baqarah 2:185, 2:203 (remember Allah on the appointed days)"}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f48a3402-e858-5dd4-ae74-7c0d7c3a3df5', id, 'witr-prayer', '{"bn": "বিতরের নামাজ ও দোয়া কুনুত", "en": "Witr Prayer and Du''a Qunut"}', '{"bn": "ইশার পর থেকে ফজর পর্যন্ত সময়ের বিতর নামাজ: হুকুম, পড়ার পদ্ধতি নিয়ে মতভেদ, আর দুই রকম দোয়া কুনুত।", "en": "Witr, prayed between ''Isha and Fajr: its ruling, the different methods, and the two forms of du''a qunut."}', 'basic', '[{"type": "text", "text": {"bn": "বিতর মানে বেজোড়। রাতের নামাজ বিতর দিয়ে শেষ করতে নবীজি (সা.) বলেছেন: ‘রাতে তোমাদের শেষ নামাজ বিতর বানাও’ (সহিহ বুখারি ৯৯৮)। সময়: ইশার নামাজের পর থেকে সুবহে সাদিক পর্যন্ত।", "en": "Witr means ''odd''. The Prophet said: ''Make witr your last prayer at night'' (Sahih al-Bukhari 998). Time: after ''Isha until dawn."}}, {"type": "differ", "title": {"bn": "বিতরের হুকুম", "en": "Ruling of witr"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "বিতর ওয়াজিব; ছুটে গেলে কাজা করতে হয়।", "en": "Witr is wajib; if missed it must be made up."}, "evidence": {"bn": "‘বিতর প্রত্যেক মুসলিমের ওপর হক’ (সুনান আবু দাউদ ১৪২২); নবীজি (সা.) সফরেও বিতর ছাড়তেন না।", "en": "''Witr is a duty (haqq) on every Muslim'' (Sunan Abi Dawud 1422); the Prophet kept it even when travelling."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "বিতর সুন্নতে মুয়াক্কাদা, খুব গুরুত্বপূর্ণ সুন্নত।", "en": "A strongly emphasised sunnah."}, "evidence": {"bn": "পাঁচ ওয়াক্তের বাইরে আর কিছু ফরজ কি না জিজ্ঞেস করলে নবীজি (সা.) বললেন, ‘না, তবে নফল হিসেবে করতে পারো’ (সহিহ বুখারি ৪৬)।", "en": "Asked if anything beyond the five prayers was obligatory, the Prophet said, ''No, unless you do it voluntarily'' (Sahih al-Bukhari 46)."}}]}, {"type": "heading", "text": {"bn": "হানাফি পদ্ধতি: তিন রাকাত, এক সালাম", "en": "Hanafi method: three rak''ahs, one salam"}}, {"type": "step", "title": {"bn": "প্রথম দুই রাকাত", "en": "First two rak''ahs"}, "text": {"bn": "সাধারণ নামাজের মতো দুই রাকাত পড়ুন; প্রতি রাকাতে সূরা ফাতিহার সাথে আরেকটি সূরা। দ্বিতীয় রাকাতের পর বসে শুধু আত্তাহিয়্যাতু পড়ে দাঁড়িয়ে যান।", "en": "Pray two rak''ahs like any prayer, with al-Fatihah and a surah in each. After the second, sit for tashahhud only and stand up."}}, {"type": "step", "title": {"bn": "তৃতীয় রাকাতে কিরাত", "en": "Third rak''ah recitation"}, "text": {"bn": "তৃতীয় রাকাতেও সূরা ফাতিহা ও আরেকটি সূরা পড়ুন।", "en": "Recite al-Fatihah and a surah in the third rak''ah too."}}, {"type": "step", "title": {"bn": "কুনুতের তাকবির", "en": "Takbir for qunut"}, "text": {"bn": "কিরাত শেষে রুকুতে না গিয়ে কান পর্যন্ত হাত তুলে ‘আল্লাহু আকবার’ বলুন, তারপর আবার হাত বাঁধুন।", "en": "After the recitation, before ruku'', raise your hands to the ears saying ''Allahu Akbar'', then fold them again."}}, {"type": "step", "title": {"bn": "দোয়া কুনুত", "en": "Du''a qunut"}, "text": {"bn": "নিচের দোয়া কুনুত চুপে চুপে পড়ুন। তারপর রুকু, সিজদা, শেষ বৈঠক ও সালাম দিয়ে শেষ করুন।", "en": "Recite the du''a qunut below quietly, then ruku'', sajdahs, the final sitting and salam."}}, {"type": "note", "tone": "tip", "text": {"bn": "দোয়া কুনুত মুখস্থ না থাকলে শেখা পর্যন্ত ‘রাব্বানা আতিনা ফিদ্দুনইয়া হাসানাতাও ওয়া ফিল আখিরাতি হাসানাতাও ওয়া কিনা আযাবান নার’ বা ‘আল্লাহুম্মাগফির লী’ তিনবার পড়া যায়। হানাফি মতে কুনুত ভুলে রুকুতে চলে গেলে আর ফিরে আসবেন না; শেষে সাহু সিজদা দেবেন।", "en": "Until you learn it, you may say ''Rabbana atina fid-dunya hasanah...'' or ''Allahummaghfir li'' three times. In the Hanafi school, if you forget qunut and go into ruku'', do not return; make sajdah al-sahw at the end."}}, {"type": "arabic", "label": {"bn": "দোয়া কুনুত (হানাফি আমলে প্রচলিত)", "en": "Du''a qunut (used in Hanafi practice)"}, "ar": "اللّٰهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ، وَنُؤْمِنُ بِكَ وَنَتَوَكَّلُ عَلَيْكَ، وَنُثْنِي عَلَيْكَ الْخَيْرَ، وَنَشْكُرُكَ وَلَا نَكْفُرُكَ، وَنَخْلَعُ وَنَتْرُكُ مَنْ يَفْجُرُكَ. اللّٰهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَىٰ وَنَحْفِدُ، وَنَرْجُو رَحْمَتَكَ، وَنَخْشَىٰ عَذَابَكَ، إِنَّ عَذَابَكَ بِالْكُفَّارِ مُلْحِقٌ", "pron": {"bn": "আল্লাহুম্মা ইন্না নাসতাঈনুকা ওয়া নাসতাগফিরুকা, ওয়া নু''মিনু বিকা ওয়া নাতাওয়াক্কালু আলাইকা, ওয়া নুসনী আলাইকাল খাইর, ওয়া নাশকুরুকা ওয়া লা নাকফুরুকা, ওয়া নাখলাউ ওয়া নাতরুকু মাই ইয়াফজুরুক। আল্লাহুম্মা ইয়্যাকা না''বুদু, ওয়া লাকা নুসাল্লী ওয়া নাসজুদু, ওয়া ইলাইকা নাস''আ ওয়া নাহফিদু, ওয়া নারজূ রাহমাতাকা, ওয়া নাখশা আযাবাকা, ইন্না আযাবাকা বিলকুফফারি মুলহিক।", "en": "Allahumma inna nasta''inuka wa nastaghfiruka, wa nu''minu bika wa natawakkalu ''alayka, wa nuthni ''alaykal-khayr, wa nashkuruka wa la nakfuruka, wa nakhla''u wa natruku man yafjuruk. Allahumma iyyaka na''budu, wa laka nusalli wa nasjudu, wa ilayka nas''a wa nahfidu, wa narju rahmataka, wa nakhsha ''adhabaka, inna ''adhabaka bil-kuffari mulhiq."}, "meaning": {"bn": "হে আল্লাহ, আমরা তোমার কাছে সাহায্য চাই ও ক্ষমা চাই, তোমার প্রতি ঈমান আনি ও তোমার ওপর ভরসা করি, তোমার উত্তম প্রশংসা করি, তোমার শোকর করি, অকৃতজ্ঞ হই না; যে তোমার অবাধ্যতা করে, তার থেকে আমরা সম্পর্ক ছিন্ন করি ও তাকে ছেড়ে দিই। হে আল্লাহ, আমরা কেবল তোমারই ইবাদত করি, তোমারই জন্য নামাজ পড়ি ও সিজদা করি, তোমারই দিকে ছুটে যাই ও তৎপর থাকি; তোমার রহমতের আশা করি ও তোমার শাস্তিকে ভয় করি। নিশ্চয়ই তোমার শাস্তি কাফেরদের পেয়ে বসবে।", "en": "O Allah, we seek Your help and Your forgiveness, we believe in You and rely on You, we praise You with all good, we thank You and are not ungrateful, and we cast off and leave whoever disobeys You. O Allah, You alone we worship, to You we pray and prostrate, to You we hasten and strive; we hope for Your mercy and fear Your punishment. Surely Your punishment will overtake the disbelievers."}, "ref": {"bn": "উমর (রা.) থেকে বর্ণিত: মুসান্নাফ ইবনে আবি শাইবা; আস-সুনানুল কুবরা, বায়হাকি", "en": "Reported from ''Umar: Musannaf Ibn Abi Shaybah; al-Sunan al-Kubra of al-Bayhaqi"}, "check": true}, {"type": "arabic", "label": {"bn": "দোয়া কুনুত (হাসান ইবনে আলী রা.-কে শেখানো)", "en": "Du''a qunut (taught to al-Hasan ibn ''Ali)"}, "ar": "اللّٰهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، إِنَّكَ تَقْضِي وَلَا يُقْضَىٰ عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ", "pron": {"bn": "আল্লাহুম্মাহদিনী ফীমান হাদাইতা, ওয়া আফিনী ফীমান আফাইতা, ওয়া তাওয়াল্লানী ফীমান তাওয়াল্লাইতা, ওয়া বারিক লী ফীমা আ''তাইতা, ওয়া কিনী শাররা মা কাদাইতা, ইন্নাকা তাকদী ওয়া লা ইউকদা আলাইকা, ওয়া ইন্নাহু লা ইয়াযিল্লু মাও ওয়ালাইতা, ওয়া লা ইয়াইযযু মান আদাইতা, তাবারাকতা রাব্বানা ওয়া তাআলাইতা।", "en": "Allahummahdini fiman hadayta, wa ''afini fiman ''afayta, wa tawallani fiman tawallayta, wa barik li fima a''tayta, wa qini sharra ma qadayta, innaka taqdi wa la yuqda ''alayka, wa innahu la yadhillu man walayta, wa la ya''izzu man ''adayta, tabarakta Rabbana wa ta''alayta."}, "meaning": {"bn": "হে আল্লাহ, যাদের তুমি হেদায়াত দিয়েছ, তাদের সাথে আমাকেও হেদায়াত দাও; যাদের নিরাপত্তা দিয়েছ, তাদের সাথে আমাকেও নিরাপত্তা দাও; যাদের অভিভাবকত্ব নিয়েছ, তাদের সাথে আমারও অভিভাবক হও; যা দিয়েছ তাতে বরকত দাও; আর তোমার ফয়সালার মন্দ থেকে আমাকে রক্ষা করো। তুমিই ফয়সালা করো, তোমার ওপর কেউ ফয়সালা করতে পারে না। তুমি যার বন্ধু হও সে অপমানিত হয় না, আর যার শত্রু হও সে সম্মানিত হয় না। হে আমাদের রব, তুমি বরকতময় ও সুউচ্চ।", "en": "O Allah, guide me among those You have guided, grant me well-being among those You have granted well-being, take me into Your care among those You have taken into Your care, bless me in what You have given, and protect me from the evil of what You have decreed. You decree and none decrees over You. Whoever You befriend is never humbled, and whoever You oppose is never honoured. Blessed are You, our Lord, and Exalted."}, "ref": {"bn": "সুনান আবু দাউদ ১৪২৫; জামে তিরমিজি ৪৬৪; সুনান নাসায়ি ১৭৪৫", "en": "Sunan Abi Dawud 1425; Jami'' al-Tirmidhi 464; Sunan al-Nasa''i 1745"}}, {"type": "text", "text": {"bn": "দুটি দোয়াই পড়া যায়। হানাফিরা সাধারণত প্রথমটি পড়েন; শাফেয়ি ও হাম্বলিরা সাধারণত দ্বিতীয়টি।", "en": "Either may be recited. Hanafis usually recite the first; Shafi''is and Hanbalis usually the second."}}, {"type": "differ", "title": {"bn": "বিতরের রাকাত সংখ্যা ও পদ্ধতি", "en": "Number of rak''ahs and method"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "বিতর তিন রাকাত, দ্বিতীয় রাকাতে বৈঠক, শেষে এক সালাম (মাগরিবের মতো, তবে তিন রাকাতেই সূরা মেলাতে হয়)। কুনুত তৃতীয় রাকাতে রুকুর আগে, সারা বছর।", "en": "Three rak''ahs with a sitting after the second and one salam at the end (like Maghrib, but with a surah in all three). Qunut in the third rak''ah before ruku'', all year."}, "evidence": {"bn": "উবাই ইবনে কা''ব (রা.): নবীজি (সা.) তিন রাকাত বিতর পড়তেন, রুকুর আগে কুনুত পড়তেন (সুনান নাসায়ি ১৬৯৯); আয়েশা (রা.)-এর বর্ণনায় ‘তারপর তিন রাকাত’ (সহিহ বুখারি ১১৪৭)।", "en": "Ubayy ibn Ka''b: the Prophet prayed three rak''ahs of witr and made qunut before ruku'' (Sunan al-Nasa''i 1699); ''A''ishah: ''then he prayed three'' (Sahih al-Bukhari 1147)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "সর্বনিম্ন এক রাকাত; তিন, পাঁচ, সাত, নয় বা এগারোও পড়া যায়। তিন রাকাত পড়লে উত্তম হলো দুই রাকাত পড়ে সালাম ফিরিয়ে আলাদা এক রাকাত পড়া, অথবা তিন রাকাত একটানা শেষে এক বৈঠকে। শাফেয়ি মতে কুনুত রমজানের শেষ অর্ধেকে রুকুর পরে; হাম্বলি মতে সারা বছর রুকুর পরে।", "en": "Minimum one rak''ah; also 3, 5, 7, 9 or 11. For three, preferably two then salam then one, or three together with one sitting at the end. Shafi''i: qunut after ruku'' in the second half of Ramadan; Hanbali: after ruku'' all year."}, "evidence": {"bn": "‘রাতের নামাজ দুই দুই রাকাত; ফজরের আশঙ্কা হলে এক রাকাত বিতর পড়ো’ (সহিহ বুখারি ৯৯০); ‘বিতর শেষ রাতে এক রাকাত’ (সহিহ মুসলিম ৭৫২); ‘কেউ চাইলে পাঁচ, তিন বা এক রাকাত বিতর পড়ুক’ (সুনান আবু দাউদ ১৪২২)।", "en": "''Night prayer is two by two; if you fear dawn, pray one as witr'' (Sahih al-Bukhari 990); ''Witr is one rak''ah at the end of the night'' (Sahih Muslim 752); ''whoever wishes, five, three or one'' (Sunan Abi Dawud 1422)."}}, {"label": {"bn": "মালেকি", "en": "Maliki"}, "text": {"bn": "দুই রাকাত (শাফা'') পড়ে সালাম ফিরিয়ে তারপর এক রাকাত বিতর।", "en": "Two rak''ahs (shaf''), salam, then one rak''ah of witr."}, "evidence": {"bn": "সহিহ বুখারি ৯৯০; সহিহ মুসলিম ৭৫২।", "en": "Sahih al-Bukhari 990; Sahih Muslim 752."}}]}, {"type": "heading", "text": {"bn": "বিতরের সুন্নত", "en": "Sunnahs of witr"}}, {"type": "list", "items": [{"bn": "তিন রাকাতে পর্যায়ক্রমে সূরা আ''লা, সূরা কাফিরুন ও সূরা ইখলাস পড়া (জামে তিরমিজি ৪৬২; সুনান নাসায়ি ১৬৯৯)", "en": "Recite al-A''la, al-Kafirun and al-Ikhlas in the three rak''ahs (Jami'' al-Tirmidhi 462; Sunan al-Nasa''i 1699)"}, {"bn": "শেষ রাতে উঠতে পারার ভরসা থাকলে তাহাজ্জুদের পরে বিতর পড়া উত্তম; না থাকলে ঘুমানোর আগে পড়ে নেওয়া (সহিহ মুসলিম ৭৫৫)", "en": "If you trust you will wake, pray witr at the end of the night after tahajjud; otherwise before sleeping (Sahih Muslim 755)"}, {"bn": "সালামের পর তিনবার ‘সুবহানাল মালিকিল কুদ্দুস’ বলা, তৃতীয়বার একটু টেনে (সুনান নাসায়ি ১৬৯৯)", "en": "After salam say ''Subhanal-Malikil-Quddus'' three times, lengthening the third (Sunan al-Nasa''i 1699)"}]}, {"type": "arabic", "label": {"bn": "বিতরের পর", "en": "After witr"}, "ar": "سُبْحَانَ الْمَلِكِ الْقُدُّوسِ", "pron": {"bn": "সুবহানাল মালিকিল কুদ্দুস (তিনবার)", "en": "Subhanal-Malikil-Quddus (three times)"}, "meaning": {"bn": "পবিত্র মহান সেই অধিপতি, যিনি সব দোষ থেকে মুক্ত।", "en": "Glory be to the King, the Most Holy."}, "ref": {"bn": "সুনান আবু দাউদ ১৪৩০; সুনান নাসায়ি ১৬৯৯", "en": "Sunan Abi Dawud 1430; Sunan al-Nasa''i 1699"}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f4c7a4de-3f76-5693-9fb1-f8a04cc35cc0', id, 'tarawih-prayer', '{"bn": "তারাবির নামাজ", "en": "Tarawih Prayer"}', '{"bn": "রমজানের রাতের বিশেষ নামাজ তারাবি: ফজিলত, পড়ার নিয়ম এবং রাকাত সংখ্যা নিয়ে আলেমদের মত।", "en": "The special night prayer of Ramadan: its virtue, how to pray it, and the scholarly views on its number of rak''ahs."}', 'basic', '[{"type": "text", "text": {"bn": "তারাবি রমজানের রাতে ইশার ফরজ ও সুন্নতের পর এবং বিতরের আগে পড়া হয়। এটি সুন্নতে মুয়াক্কাদা; জামাতে পড়া উত্তম। দুই দুই রাকাত করে পড়া হয়, আর প্রতি চার রাকাত পর একটু বিশ্রাম (তারবিহা) নেওয়া হয়; এ থেকেই নাম ‘তারাবি’।", "en": "Tarawih is prayed in Ramadan after ''Isha (fard and sunnah) and before witr. It is a confirmed sunnah, best in congregation, prayed two rak''ahs at a time with a short rest (tarwihah) after every four, hence the name."}}, {"type": "arabic", "label": {"bn": "ফজিলত", "en": "Virtue"}, "ar": "مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ", "pron": {"bn": "মান কামা রামাদানা ঈমানান ওয়াহতিসাবান গুফিরা লাহু মা তাকাদ্দামা মিন যামবিহ।", "en": "Man qama Ramadana imanan wahtisaban ghufira lahu ma taqaddama min dhanbih."}, "meaning": {"bn": "যে ব্যক্তি ঈমানের সাথে ও সওয়াবের আশায় রমজানের রাতে নামাজে দাঁড়ায়, তার আগের গুনাহ ক্ষমা করে দেওয়া হয়।", "en": "Whoever stands (in prayer) in Ramadan with faith and seeking reward, his previous sins are forgiven."}, "ref": {"bn": "সহিহ বুখারি ৩৭", "en": "Sahih al-Bukhari 37"}}, {"type": "heading", "text": {"bn": "ইতিহাস", "en": "History"}}, {"type": "text", "text": {"bn": "নবীজি (সা.) কয়েক রাত মসজিদে জামাতে রাতের নামাজ পড়েছেন, তারপর ফরজ হয়ে যাওয়ার আশঙ্কায় আর বের হননি (সহিহ বুখারি ২০১২)। পরে উমর (রা.) সবাইকে উবাই ইবনে কা''ব (রা.)-এর পেছনে এক জামাতে একত্র করেন (সহিহ বুখারি ২০১০)।", "en": "The Prophet led the night prayer in congregation for a few nights, then stopped, fearing it would be made obligatory (Sahih al-Bukhari 2012). Later ''Umar gathered the people behind Ubayy ibn Ka''b in one congregation (Sahih al-Bukhari 2010)."}}, {"type": "differ", "title": {"bn": "তারাবি কত রাকাত", "en": "How many rak''ahs"}, "views": [{"label": {"bn": "২০ রাকাত (হানাফি, শাফেয়ি, হাম্বলি)", "en": "20 rak''ahs (Hanafi, Shafi''i, Hanbali)"}, "text": {"bn": "বিতর ছাড়া ২০ রাকাত, দুই দুই করে দশ সালামে। বাংলাদেশের মসজিদগুলোতে এটিই প্রচলিত।", "en": "Twenty rak''ahs besides witr, in ten pairs. This is the common practice in Bangladesh''s mosques."}, "evidence": {"bn": "উমর (রা.)-এর যুগে মানুষ ২০ রাকাত পড়তেন বলে সাইব ইবনে ইয়াজিদ (রা.) থেকে বায়হাকি বর্ণনা করেছেন; মুয়াত্তা মালিকে ইয়াজিদ ইবনে রুমান থেকে ২৩ রাকাত (বিতরসহ) বর্ণিত। পরবর্তী উম্মাহর ব্যাপক আমল।", "en": "Al-Bayhaqi reports from al-Sa''ib ibn Yazid that people prayed 20 in ''Umar''s time; the Muwatta'' reports 23 (with witr) from Yazid ibn Ruman. Widespread later practice of the ummah."}}, {"label": {"bn": "৮ রাকাত", "en": "8 rak''ahs"}, "text": {"bn": "বিতর ছাড়া ৮ রাকাত (বিতরসহ ১১)।", "en": "Eight rak''ahs plus witr (eleven in total)."}, "evidence": {"bn": "আয়েশা (রা.): নবীজি (সা.) রমজানে ও অন্য সময়ে রাতে এগারো রাকাতের বেশি পড়তেন না (সহিহ বুখারি ১১৪৭); মুয়াত্তা মালিকে উমর (রা.) উবাই ও তামিম দারি (রা.)-কে এগারো রাকাত পড়াতে বলেছিলেন।", "en": "''A''ishah: the Prophet did not exceed eleven rak''ahs at night, in Ramadan or otherwise (Sahih al-Bukhari 1147); the Muwatta'' reports ''Umar telling Ubayy and Tamim al-Dari to lead eleven."}}, {"label": {"bn": "নির্দিষ্ট সংখ্যা নেই", "en": "No fixed number"}, "text": {"bn": "ইমাম মালিক (রহ.)-এর মতে মদিনাবাসীর আমলে ৩৬ রাকাত। অনেক আলেমের মতে রাতের নফল নামাজের নির্দিষ্ট সীমা নেই; কেউ কম রাকাত লম্বা করে, কেউ বেশি রাকাত ছোট করে পড়তে পারে।", "en": "Imam Malik reported 36 as the practice of Madinah. Many scholars say night prayer has no fixed limit: fewer long rak''ahs or more short ones."}, "evidence": {"bn": "‘রাতের নামাজ দুই দুই রাকাত’ (সহিহ বুখারি ৯৯০), এখানে কোনো সংখ্যা বেঁধে দেওয়া হয়নি।", "en": "''Night prayer is two by two'' (Sahih al-Bukhari 990), with no number fixed."}}], "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "যে মসজিদে যে নিয়ম, সেখানে ইমামের সাথে শেষ পর্যন্ত পড়াই উত্তম। নবীজি (সা.) বলেছেন, যে ইমামের সাথে তিনি শেষ করা পর্যন্ত দাঁড়ায়, তার জন্য পুরো রাত নামাজের সওয়াব লেখা হয় (জামে তিরমিজি ৮০৬)। তারাবির রাকাত নিয়ে বিবাদ করা উচিত নয়।", "en": "Pray with your mosque''s imam until he finishes. The Prophet said whoever stands with the imam until he finishes gets the reward of the whole night (Jami'' al-Tirmidhi 806). Do not quarrel over the number."}}, {"type": "heading", "text": {"bn": "নিয়ম", "en": "How to pray"}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "মনে মনে নিয়ত করুন যে তারাবির দুই রাকাত সুন্নত পড়ছি; মুখে বলা জরুরি নয়।", "en": "Intend in your heart to pray two rak''ahs of tarawih; saying it aloud is not required."}}, {"type": "step", "title": {"bn": "দুই দুই রাকাত", "en": "Two by two"}, "text": {"bn": "সাধারণ দুই রাকাত সুন্নতের মতো পড়ে সালাম ফেরান।", "en": "Pray like any two-rak''ah sunnah and end with salam."}}, {"type": "step", "title": {"bn": "প্রতি চার রাকাত পর বিশ্রাম", "en": "Rest after every four"}, "text": {"bn": "চার রাকাত পরপর একটু বসে বিশ্রাম নিন; এ সময় তাসবিহ, দরুদ, ইস্তিগফার বা কুরআন পড়তে পারেন।", "en": "Sit and rest after every four rak''ahs; you may make tasbih, durood, istighfar or recite Quran."}}, {"type": "step", "title": {"bn": "শেষে বিতর", "en": "Witr at the end"}, "text": {"bn": "রমজানে বিতর জামাতের সাথে পড়া যায়।", "en": "In Ramadan, witr may be prayed in congregation."}}, {"type": "note", "tone": "info", "text": {"bn": "চার রাকাত পরপর পড়ার জন্য ‘সুবহানা যিল মুলকি ওয়াল মালাকুত...’ নামে যে দোয়া প্রচলিত, তা কোনো হাদিসে তারাবির জন্য নির্দিষ্ট করে বর্ণিত হয়নি। এই বিরতিতে যেকোনো জিকির করা যায়; নির্দিষ্ট দোয়াকে জরুরি মনে করবেন না।", "en": "The popular ''Subhana dhil-mulki wal-malakut...'' recited between sets is not narrated specifically for tarawih in any hadith. Any dhikr is fine in the pause; do not treat a particular one as required."}}, {"type": "text", "text": {"bn": "হানাফি মতে রমজানে তারাবিতে অন্তত একবার পুরো কুরআন খতম করা সুন্নত। জামাতে না পারলে ঘরে একা বা পরিবারের সাথে তারাবি পড়া যায়।", "en": "In the Hanafi school, completing the whole Quran once in tarawih during Ramadan is sunnah. If you cannot attend the mosque, pray it at home alone or with family."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '46afea9c-9492-56ab-842d-61fec65e7d32', id, 'tahajjud-prayer', '{"bn": "তাহাজ্জুদের নামাজ", "en": "Tahajjud (Night) Prayer"}', '{"bn": "ফরজের পর সবচেয়ে মর্যাদাপূর্ণ নামাজ তাহাজ্জুদ: সময়, রাকাত, নিয়ম ও শেষ রাতের দোয়া।", "en": "The most virtuous prayer after the obligatory ones: its time, rak''ahs, method and the value of the last third of the night."}', 'basic', '[{"type": "arabic", "ar": "وَمِنَ اللَّيْلِ فَتَهَجَّدْ بِهِ نَافِلَةً لَكَ عَسَىٰ أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا", "pron": {"bn": "ওয়া মিনাল লাইলি ফাতাহাজ্জাদ বিহী নাফিলাতাল লাক, আসা আই ইয়াবআসাকা রাব্বুকা মাকামাম মাহমূদা।", "en": "Wa minal-layli fatahajjad bihi nafilatal lak, ''asa ay yab''athaka Rabbuka maqamam mahmuda."}, "meaning": {"bn": "আর রাতের কিছু অংশে তাহাজ্জুদ পড়ো; এটি তোমার জন্য অতিরিক্ত। আশা করা যায়, তোমার রব তোমাকে প্রশংসিত স্থানে পৌঁছাবেন।", "en": "And in part of the night, pray tahajjud as an extra for you; perhaps your Lord will raise you to a praised station."}, "ref": {"bn": "সূরা ইসরা ১৭:৭৯", "en": "Al-Isra 17:79"}}, {"type": "list", "items": [{"bn": "‘রমজানের পর সর্বোত্তম রোজা মুহাররমের রোজা, আর ফরজের পর সর্বোত্তম নামাজ রাতের নামাজ’ (সহিহ মুসলিম ১১৬৩)।", "en": "''The best prayer after the obligatory is the night prayer'' (Sahih Muslim 1163)."}, {"bn": "প্রতি রাতের শেষ তৃতীয়াংশে আল্লাহ নিকটতম আসমানে নেমে বলেন: কে আমাকে ডাকবে, আমি সাড়া দেব; কে চাইবে, আমি দেব; কে ক্ষমা চাইবে, আমি ক্ষমা করব (সহিহ বুখারি ১১৪৫)।", "en": "In the last third of every night Allah descends to the lowest heaven and says: who calls Me that I may answer, who asks Me that I may give, who seeks forgiveness that I may forgive (Sahih al-Bukhari 1145)."}]}, {"type": "heading", "text": {"bn": "সময়", "en": "Time"}}, {"type": "text", "text": {"bn": "ইশার পর থেকে সুবহে সাদিক পর্যন্ত যেকোনো সময় পড়া যায়। ঘুম থেকে উঠে পড়া এবং রাতের শেষ তৃতীয়াংশে পড়া সবচেয়ে উত্তম। উঠতে না পারার আশঙ্কা থাকলে ঘুমানোর আগে কিছু নফল পড়ে বিতর পড়ে নিন।", "en": "Any time after ''Isha until dawn. Best after sleeping and in the last third of the night. If you fear not waking, pray some nafl and witr before sleeping."}}, {"type": "heading", "text": {"bn": "রাকাত সংখ্যা", "en": "Number of rak''ahs"}}, {"type": "text", "text": {"bn": "সর্বনিম্ন দুই রাকাত। নবীজি (সা.) সাধারণত বিতরসহ এগারো রাকাত (সহিহ বুখারি ১১৪৭), কখনো তেরো রাকাত (সহিহ বুখারি ১১৩৮) পড়তেন। নির্দিষ্ট কোনো সীমা নেই; সামর্থ্য অনুযায়ী পড়ুন।", "en": "Minimum two rak''ahs. The Prophet usually prayed eleven including witr (Sahih al-Bukhari 1147), sometimes thirteen (Sahih al-Bukhari 1138). There is no fixed limit; pray as you are able."}}, {"type": "heading", "text": {"bn": "নিয়ম", "en": "Method"}}, {"type": "step", "title": {"bn": "ওযু ও নিয়ত", "en": "Wudu and intention"}, "text": {"bn": "ওযু করে মনে মনে তাহাজ্জুদের নিয়ত করুন।", "en": "Make wudu and intend tahajjud in your heart."}}, {"type": "step", "title": {"bn": "হালকা দুই রাকাত দিয়ে শুরু", "en": "Begin with two light rak''ahs"}, "text": {"bn": "নবীজি (সা.) রাতের নামাজ দুই হালকা রাকাত দিয়ে শুরু করতে বলেছেন (সহিহ মুসলিম ৭৬৮)।", "en": "The Prophet advised starting the night prayer with two light rak''ahs (Sahih Muslim 768)."}}, {"type": "step", "title": {"bn": "দুই দুই রাকাত করে", "en": "Two at a time"}, "text": {"bn": "সাধারণ নফল নামাজের মতো দুই দুই রাকাত করে পড়ুন; যেকোনো সূরা পড়া যায়, লম্বা কিরাত ও লম্বা সিজদা উত্তম (সহিহ বুখারি ৯৯০)।", "en": "Pray two rak''ahs at a time like any nafl; any surah is fine; long recitation and sajdah are better (Sahih al-Bukhari 990)."}}, {"type": "step", "title": {"bn": "বিতর দিয়ে শেষ", "en": "End with witr"}, "text": {"bn": "আগে বিতর না পড়ে থাকলে শেষে বিতর পড়ুন (সহিহ বুখারি ৯৯৮)।", "en": "If you have not yet prayed witr, end with it (Sahih al-Bukhari 998)."}}, {"type": "step", "title": {"bn": "দোয়া ও ইস্তিগফার", "en": "Dua and istighfar"}, "text": {"bn": "এ সময় দোয়া কবুলের আশা বেশি; নিজের ভাষায় মন খুলে দোয়া ও ক্ষমা চান।", "en": "This is a time of hope for acceptance; ask and seek forgiveness in your own words."}}, {"type": "note", "tone": "tip", "text": {"bn": "মুখে নিয়ত বলা জরুরি নয়। উদাহরণ (প্রচলিত বাংলা): ‘আমি আল্লাহর জন্য দুই রাকাত তাহাজ্জুদ নামাজ পড়ছি।’ নিয়মিত অল্প পড়া, মাঝে মাঝে বেশি পড়ার চেয়ে ভালো।", "en": "Saying the niyyah aloud is not required. Example (common Bangla phrasing): ''I am praying two rak''ahs of tahajjud for Allah.'' A little done regularly is better than a lot occasionally."}}, {"type": "ref", "text": {"bn": "আরও দেখুন: সূরা মুজ্জাম্মিল ৭৩:১–৬; সূরা সাজদা ৩২:১৬; সূরা যারিয়াত ৫১:১৭–১৮", "en": "See also: Al-Muzzammil 73:1–6; As-Sajdah 32:16; Adh-Dhariyat 51:17–18"}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
